_ProviderTurnReconciliationOutcome = Literal["not_required", "observed", "scheduled"]


@dataclass(frozen=True)
class _SystemReconciliationNotificationContract:
    detail_field: Literal["reason", "prior_turn_id"] | None = None


_SYSTEM_RECONCILIATION_NOTIFICATION_CONTRACTS = {
    _SystemReconciliationNotificationAction.RECOVER_TERMINAL_WORKER_ATTEMPT: (
        _SystemReconciliationNotificationContract(detail_field="reason")
    ),
    _SystemReconciliationNotificationAction.RECONCILE_COMPLETED_WORKER_TURN: (
        _SystemReconciliationNotificationContract(detail_field="reason")
    ),
    _SystemReconciliationNotificationAction.RECONCILE_CONTINUE_SAME_THREAD: (
        _SystemReconciliationNotificationContract()
    ),
    _SystemReconciliationNotificationAction.RECOVER_EXPIRED_REASONER_TURN: (
        _SystemReconciliationNotificationContract(detail_field="prior_turn_id")
    ),
    _SystemReconciliationNotificationAction.RECOVER_INCOMPLETE_REASONER_TURN: (
        _SystemReconciliationNotificationContract(detail_field="prior_turn_id")
    ),
    _SystemReconciliationNotificationAction.REVIEW_RUNTIME_BOUNDARY: (
        _SystemReconciliationNotificationContract()
    ),
    _SystemReconciliationNotificationAction.REARM_SUPERVISION_BOUNDARY: (
        _SystemReconciliationNotificationContract()
    ),
}


def _system_reconciliation_notification_payload(
    *,
    action: _SystemReconciliationNotificationAction,
    boundary_id: str,
    boundary_kind: str,
    generation: int,
    reason: str | None = None,
    prior_turn_id: str | None = None,
) -> dict[str, Any]:
    """Build one notification from the same contract used to authenticate it."""

    contract = _SYSTEM_RECONCILIATION_NOTIFICATION_CONTRACTS[action]
    payload: dict[str, Any] = {
        "action": action.value,
        "boundary_id": boundary_id,
        "boundary_kind": boundary_kind,
        "generation": generation,
    }
    detail_values = {
        "reason": reason,
        "prior_turn_id": prior_turn_id,
    }
    unexpected_details = [
        field
        for field, value in detail_values.items()
        if value is not None and field != contract.detail_field
    ]
    if unexpected_details:
        raise ValueError(f"{action.value} notification does not accept {unexpected_details[0]}")
    if contract.detail_field is not None:
        detail = detail_values[contract.detail_field]
        if not isinstance(detail, str):
            raise ValueError(f"{action.value} notification requires {contract.detail_field}")
        payload[contract.detail_field] = detail
    return payload


def _require_operator_display_label(value: str) -> None:
    if "/" in value or "\\" in value or contains_control_plane_secret(value):
        raise ValidationError("operator label must be a non-secret display label")


_TASK_PRIVATE_LOCATOR = re.compile(
    r"(?:\bfile://|\bowner-private-artifact:|"
    r"(?:\bUNC\s*:\s*)?\\{2}[^\\\s]+\\[^\s,;]+|"
    r"\b[A-Za-z]:\\[^\s,;]+|"
    r"(?<![A-Za-z0-9])\\(?:Windows|Users|ProgramData|Program Files|AppData|"
    r"System32|Temp)(?:\\[^\s,;]+)?|"
    r"(?:\$(?:HOME|USERPROFILE)|\$\{(?:HOME|USERPROFILE)\}|"
    r"%(?:USERPROFILE|HOMEPATH)%)[/\\][^\s,;]+)",
    re.IGNORECASE,
)
_TASK_POSIX_PRIVATE_LOCATOR = re.compile(r"(?:~(?:[A-Za-z0-9._-]+)?/|/+)[^\s,;\"')>\]}]+")
_TASK_HTTP_URL = re.compile(r"\bhttps?://[^\s<>\"']+", re.IGNORECASE)
_TASK_HTTP_ROUTE = re.compile(
    r"\b(?:GET|HEAD|POST|PUT|PATCH|DELETE|OPTIONS|CONNECT|TRACE)\s+"
    r"/(?!/)[^\s,;\"')>\]}]+",
    re.IGNORECASE,
)
_TASK_PRIVATE_HTTP_ROUTE_ROOT = re.compile(
    r"^/{1,2}(?:etc|Users|home|private|Volumes|var|tmp|root|opt|usr|Library|"
    r"System|Applications|dev|proc|sys|run|srv|mnt|media)(?:/|$)",
    re.IGNORECASE,
)
_TASK_PUBLIC_DOCUMENTATION_NETWORKS = tuple(
    ipaddress.ip_network(value)
    for value in ("192.0.2.0/24", "198.51.100.0/24", "203.0.113.0/24", "2001:db8::/32")
)
_TASK_CREDENTIAL_WORDS = frozenset(
    {
        "authorization",
        "bearer",
        "credential",
        "credentials",
        "passphrase",
        "passwd",
        "password",
        "secret",
        "secrets",
        "token",
    }
)
_TASK_CREDENTIAL_COMPACT_SUFFIXES = (
    "password",
    "passwd",
    "passphrase",
    "apikey",
    "accesstoken",
    "authtoken",
    "refreshtoken",
    "idtoken",
    "githubtoken",
    "clientsecret",
    "privatekey",
    "secretkey",
    "signingkey",
)
_TASK_CREDENTIAL_DESCRIPTOR_SUFFIXES = frozenset(
    {
        "algorithm",
        "configured",
        "count",
        "description",
        "documentation",
        "enabled",
        "expiry",
        "format",
        "id",
        "kind",
        "length",
        "name",
        "policy",
        "present",
        "provider",
        "reference",
        "required",
        "rotation",
        "scheme",
        "scope",
        "status",
        "type",
        "usage",
    }
)


def _require_worker_safe_task_payload(value: Any) -> None:
    """Reject secrets and concrete locators before sealing a Worker packet."""

    if contains_control_plane_secret(value) or _contains_generic_credential(value):
        raise ValidationError("task packet contains a credential-like secret")
    if _contains_private_locator(value):
        raise ValidationError(
            "task packet contains a private locator",
            reason_code="task_packet_private_locator",
        )


def _contains_generic_credential(value: Any) -> bool:
    if isinstance(value, str):
        return contains_generic_credential_text(value)
    if isinstance(value, Mapping):
        for key, item in value.items():
            if (
                isinstance(key, str)
                and _is_credential_field_name(key)
                and item not in (None, "", False, [], {}, ())
            ):
                return True
            if _contains_generic_credential(key) or _contains_generic_credential(item):
                return True
        return False
    if isinstance(value, (list, tuple, set, frozenset)):
        return any(_contains_generic_credential(item) for item in value)
    return False


def _is_credential_field_name(value: str) -> bool:
    normalized = unicodedata.normalize("NFKC", value).strip()
    separated = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1_\2", normalized)
    separated = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", "_", separated)
    words = tuple(re.findall(r"[a-z0-9]+", separated.lower()))
    if not words:
        return False
    compact = "".join(words)
    has_credential_marker = any(word in _TASK_CREDENTIAL_WORDS for word in words) or (
        compact == "token" or compact.endswith(_TASK_CREDENTIAL_COMPACT_SUFFIXES)
    )
    if not has_credential_marker:
        return False
    return words[-1] not in _TASK_CREDENTIAL_DESCRIPTOR_SUFFIXES


def _without_public_http_urls(value: str) -> str:
    def replace(match: re.Match[str]) -> str:
        candidate = match.group(0).rstrip(".,;:!?)]}")
        suffix = match.group(0)[len(candidate) :]
        parsed = urlsplit(candidate)
        hostname = str(parsed.hostname or "").lower()
        canonical_hostname = hostname.rstrip(".")
        is_private_ip = False
        with suppress(ValueError):
            address = ipaddress.ip_address(canonical_hostname)
            is_documentation_address = any(
                address in network for network in _TASK_PUBLIC_DOCUMENTATION_NETWORKS
            )
            is_private_ip = not is_documentation_address and (
                address.is_private
                or address.is_loopback
                or address.is_link_local
                or address.is_unspecified
            )
        if not is_private_ip:
            with suppress(OSError):
                legacy_ipv4 = ipaddress.ip_address(socket.inet_aton(canonical_hostname))
                is_private_ip = (
                    legacy_ipv4.is_private
                    or legacy_ipv4.is_loopback
                    or legacy_ipv4.is_link_local
                    or legacy_ipv4.is_unspecified
                )
        if (
            not canonical_hostname
            or parsed.username is not None
            or parsed.password is not None
            or canonical_hostname in {"localhost", "localhost.localdomain"}
            or canonical_hostname.endswith(
                (".localhost", ".local", ".localdomain", ".internal", ".lan")
            )
            or ("." not in canonical_hostname and ":" not in canonical_hostname)
            or is_private_ip
        ):
            return f" /private-network-location{suffix}"
        return suffix

    without_urls = _TASK_HTTP_URL.sub(replace, value)

    def replace_route(match: re.Match[str]) -> str:
        target = match.group(0).split(maxsplit=1)[1]
        return match.group(0) if _TASK_PRIVATE_HTTP_ROUTE_ROOT.search(target) else ""

    return _TASK_HTTP_ROUTE.sub(replace_route, without_urls)


def _contains_private_locator(value: Any) -> bool:
    if isinstance(value, str):
        normalized = unicodedata.normalize("NFKC", value)
        without_public_urls = _without_public_http_urls(normalized)
        if _TASK_PRIVATE_LOCATOR.search(without_public_urls) is not None:
            return True
        for index, character in enumerate(without_public_urls):
            if character not in {"/", "~"}:
                continue
            if index > 0:
                previous = without_public_urls[index - 1]
                category = unicodedata.category(previous)
                if (
                    previous in "_+.-/"
                    or previous.isalnum()
                    or category[:1] in {"L", "M", "N", "S"}
                ):
                    continue
            if _TASK_POSIX_PRIVATE_LOCATOR.match(without_public_urls, index) is not None:
                return True
        return False
    if isinstance(value, Mapping):
        return any(
            _contains_private_locator(key) or _contains_private_locator(item)
            for key, item in value.items()
        )
    if isinstance(value, (list, tuple, set, frozenset)):
        return any(_contains_private_locator(item) for item in value)
    return False


def _worker_safe_report_text(value: Any, *, limit: int = 2000) -> str:
    """Keep a bounded report phrase only when it has no secret/local locator."""

    if not isinstance(value, str):
        return ""
    normalized = unicodedata.normalize("NFKC", value).strip()
    if (
        not normalized
        or contains_control_plane_secret(normalized)
        or _contains_generic_credential(normalized)
        or _contains_private_locator(normalized)
    ):
        return ""
    return normalized[:limit]


def _row(row: sqlite3.Row | None) -> dict[str, Any] | None:
    if row is None:
        return None
    return dict(row)


def _now_dt() -> datetime:
    return datetime.now(UTC)


def _is_expired(value: str | None) -> bool:
    if not value:
        return False
    try:
        # Equality is expired.  Leases have second precision in SQLite, so
        # accepting the boundary second would create a same-second replay
        # window between ticket issue, exchange, authentication, and action.
        return datetime.fromisoformat(value.replace("Z", "+00:00")) <= _now_dt()
    except ValueError:
        return True


