    def read_artifact_content(
        self,
        actor: dict[str, Any],
        request: ArtifactContentReadInput,
    ) -> dict[str, Any]:
        """Read one manifest-bound text chunk for the current CAO attachment."""

        self._require_role(actor, PrincipalRole.CAO)
        attachment_id = str(actor.get("_cao_attachment_id") or "")
        attachment_generation = actor.get("_cao_attachment_generation")
        if (
            not attachment_id
            or not isinstance(attachment_generation, int)
            or isinstance(attachment_generation, bool)
            or not (
                actor.get("_cao_conversation_credential_id")
                or actor.get("_cao_runtime_credential_id")
            )
        ):
            raise AuthorizationError("artifact content read requires the current CAO attachment")
        request_fields = request.model_dump(mode="json")
        idempotency_key = str(request_fields.pop("idempotency_key"))
        request_digest = _digest(
            {
                "format": "cao-verified-artifact-text-read-request/v1",
                "supervisor_attachment_id": attachment_id,
                "supervisor_attachment_generation": int(attachment_generation),
                "request": request_fields,
            }
        )
        idempotency_key_digest = hashlib.sha256(
            (
                "cao-artifact-content-read-idempotency-v1\0"
                + actor["id"]
                + "\0"
                + attachment_id
                + "\0"
                + idempotency_key
            ).encode("utf-8")
        ).hexdigest()

        with self.db.transaction() as connection:
            if actor.get("_cao_attachment_id"):
                self._require_current_cao_attachment_actor_tx(connection, actor)
            artifact = connection.execute(
                """
                SELECT artifact.*,
                       work.supervisor_attachment_id AS work_attachment_id
                FROM artifacts AS artifact
                JOIN attempts AS attempt
                  ON attempt.id = artifact.attempt_id
                 AND attempt.work_item_id = artifact.work_item_id
                JOIN work_items AS work ON work.id = artifact.work_item_id
                WHERE artifact.id = ?
                  AND artifact.work_item_id = ?
                  AND artifact.attempt_id = ?
                  AND work.supervisor_attachment_id = ?
                """,
                (
                    request.artifact_id,
                    request.work_item_id,
                    request.attempt_id,
                    attachment_id,
                ),
            ).fetchone()
            if artifact is None:
                raise NotFoundError("verified artifact binding", request.artifact_id)

            attempt = connection.execute(
                "SELECT * FROM attempts WHERE id = ? AND work_item_id = ?",
                (request.attempt_id, request.work_item_id),
            ).fetchone()
            assert attempt is not None
            completion_claim = _load(str(attempt["completion_claim_json"]), {})
            manifest_attempt: Mapping[str, Any] | sqlite3.Row = attempt
            if not completion_claim:
                captured_manifest = connection.execute(
                    """SELECT output.artifact_manifest_json FROM worker_output_receipts output
                       JOIN boundaries b ON b.id = output.boundary_id
                       JOIN work_items w ON w.id = b.work_item_id
                       LEFT JOIN boundary_dispositions d ON d.boundary_id = b.id
                       LEFT JOIN boundary_supersessions s ON s.boundary_id = b.id
                       WHERE output.attempt_id = ? AND output.event_kind = 'turn_end'
                         AND b.kind = 'worker_output' AND b.generation = w.generation
                         AND d.id IS NULL AND s.boundary_id IS NULL
                       ORDER BY output.sequence DESC LIMIT 1""",
                    (request.attempt_id,),
                ).fetchone()
                if captured_manifest is not None:
                    completion_claim = {
                        "artifact_manifest_scope": "verified_attempt_artifacts_v2",
                        "artifacts": _load(str(captured_manifest["artifact_manifest_json"]), []),
                    }
                    manifest_attempt = {
                        **dict(attempt),
                        "completion_claim_json": _json(completion_claim),
                    }
            if (
                not isinstance(completion_claim, Mapping)
                or completion_claim.get("artifact_manifest_scope")
                != "verified_attempt_artifacts_v2"
            ):
                raise ConflictError(
                    "artifact is not in the verified completion manifest",
                    reason_code="artifact_content_manifest_unverified",
                )
            manifest = self._completion_claim_artifact_rows_tx(connection, manifest_attempt)
            if manifest is None or not any(
                str(item["id"]) == request.artifact_id
                and str(item["digest"]) == str(artifact["digest"])
                for item in manifest
            ):
                raise ConflictError(
                    "artifact is not in the verified completion manifest",
                    reason_code="artifact_content_manifest_unverified",
                )

            digest = str(artifact["digest"])
            if (
                not hmac.compare_digest(digest, request.expected_digest)
                or str(artifact["uri"]) != f"owner-private-artifact:{digest}"
            ):
                raise ConflictError(
                    "verified artifact digest binding does not match",
                    reason_code="artifact_content_digest_mismatch",
                )
            try:
                media_type = canonical_utf8_text_media_type(artifact["media_type"])
                expected_media_type = canonical_utf8_text_media_type(request.expected_media_type)
            except ArtifactContentTypeError as error:
                raise ConflictError(
                    "verified artifact content type is unavailable",
                    reason_code=error.code,
                ) from None
            if not hmac.compare_digest(media_type, expected_media_type):
                raise ConflictError(
                    "verified artifact content type does not match",
                    reason_code="artifact_content_media_type_mismatch",
                )
            prior_audit = connection.execute(
                """
                SELECT sequence, data_json
                FROM events
                WHERE event_type = 'artifact.content_read'
                  AND aggregate_type = 'artifact'
                  AND actor_id = ?
                  AND json_extract(
                        data_json, '$.idempotency_key_digest'
                      ) = ?
                ORDER BY sequence
                LIMIT 1
                """,
                (
                    actor["id"],
                    idempotency_key_digest,
                ),
            ).fetchone()
            if prior_audit is not None:
                prior_data = _load(str(prior_audit["data_json"]), {})
                if not isinstance(prior_data, Mapping) or not hmac.compare_digest(
                    str(prior_data.get("request_digest", "")),
                    request_digest,
                ):
                    raise ConflictError(
                        "artifact read idempotency key was reused with different parameters",
                        reason_code="artifact_content_idempotency_conflict",
                    )
            try:
                chunk = self.owner_private_artifact_preservation.read_verified_text_chunk(
                    digest=digest,
                    byte_offset=request.byte_offset,
                    max_bytes=request.max_bytes,
                )
            except ArtifactPreservationProviderError as error:
                raise ConflictError(
                    "verified artifact content is unavailable",
                    reason_code=error.code,
                ) from None
            audit_data = {
                "format": "cao-verified-artifact-text-read/v1",
                "work_item_id": request.work_item_id,
                "attempt_id": request.attempt_id,
                "artifact_id": request.artifact_id,
                "digest": digest,
                "media_type": media_type,
                "supervisor_attachment_id": attachment_id,
                "supervisor_attachment_generation": int(attachment_generation),
                "byte_offset": chunk.byte_offset,
                "byte_count": chunk.byte_count,
                "total_bytes": chunk.total_bytes,
                "complete": chunk.complete,
                "chunk_digest": chunk.chunk_digest,
                "idempotency_key_digest": idempotency_key_digest,
                "request_digest": request_digest,
            }
            if prior_audit is not None:
                if dict(prior_data) != audit_data:
                    raise ConflictError(
                        "artifact read audit evidence no longer matches",
                        reason_code="artifact_content_audit_mismatch",
                    )
                event_sequence = int(prior_audit["sequence"])
            else:
                event_sequence = self._event(
                    connection,
                    "artifact.content_read",
                    "artifact",
                    request.artifact_id,
                    actor["id"],
                    audit_data,
                )
            return {
                "format": "cao-verified-artifact-text/v1",
                "work_item_id": request.work_item_id,
                "attempt_id": request.attempt_id,
                "artifact_id": request.artifact_id,
                "digest": digest,
                "media_type": media_type,
                "content_encoding": "utf-8",
                "content": chunk.content,
                "byte_offset": chunk.byte_offset,
                "byte_count": chunk.byte_count,
                "total_bytes": chunk.total_bytes,
                "next_byte_offset": chunk.next_byte_offset,
                "complete": chunk.complete,
                "chunk_digest": chunk.chunk_digest,
                "audit_event_sequence": event_sequence,
            }

    def query_work(
        self, request: QueryInput, actor: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        if actor is not None and actor.get("_cao_conversation_credential_id"):
            self._require_role(actor, PrincipalRole.CAO)
        clauses = ["1 = 1"]
        params: list[Any] = []
        if actor is not None:
            role = actor["role"]
            if role == PrincipalRole.USER.value:
                clauses.append("requester_id = ?")
                params.append(actor["id"])
            elif role == PrincipalRole.WORKER.value:
                clauses.append("assigned_worker_id = ?")
                params.append(actor["id"])
            elif role == PrincipalRole.CAO.value and actor.get("_cao_attachment_id"):
                clauses.append("supervisor_attachment_id = ?")
                params.append(actor["_cao_attachment_id"])
            elif role != PrincipalRole.CAO.value:
                raise AuthorizationError("principal cannot query work items")
        if request.worker_id:
            clauses.append("assigned_worker_id = ?")
            params.append(request.worker_id)
        if request.state:
            clauses.append("state = ?")
            params.append(request.state.value)
        if request.attention_owner:
            clauses.append("attention_owner = ?")
            params.append(request.attention_owner.value)
        if request.cursor:
            priority, updated_at, work_id = self._decode_work_cursor(request.cursor)
            clauses.append(
                "(priority < ? OR (priority = ? AND updated_at < ?) "
                "OR (priority = ? AND updated_at = ? AND id < ?))"
            )
            params.extend([priority, priority, updated_at, priority, updated_at, work_id])
        rows = self.db.fetchall(
            f"SELECT id, priority, updated_at FROM work_items "
            f"WHERE {' AND '.join(clauses)} "
            "ORDER BY priority DESC, updated_at DESC, id DESC LIMIT ?",
            [*params, request.limit + 1],
        )
        has_more = len(rows) > request.limit
        rows = rows[: request.limit]
        items = [self.get_work(row["id"], actor) for row in rows]
        next_cursor = self._encode_work_cursor(rows[-1]) if has_more and rows else None
        return {"items": items, "next_cursor": next_cursor}

    def get_worker_context(
        self, actor: dict[str, Any], attempt_id: str | None = None
    ) -> dict[str, Any]:
        self._require_role(actor, PrincipalRole.WORKER, PrincipalRole.CAO)
        with self.db.transaction() as connection:
            if attempt_id:
                row = connection.execute(
                    "SELECT * FROM attempts WHERE id = ?", (attempt_id,)
                ).fetchone()
            else:
                row = connection.execute(
                    """
                    SELECT * FROM attempts
                    WHERE worker_id = ?
                      AND state NOT IN (?, ?, ?)
                    ORDER BY updated_at DESC LIMIT 1
                    """,
                    (
                        actor["id"],
                        AttemptState.COMPLETED.value,
                        AttemptState.FAILED.value,
                        AttemptState.CANCELED.value,
                    ),
                ).fetchone()
            if row is not None and actor["role"] == PrincipalRole.WORKER.value:
                expected_runtime_id = str(row["runtime_session_id"] or "")
                if not expected_runtime_id:
                    raise ConflictError("Worker attempt is not bound to a managed MCP runtime")
                self._require_worker_runtime_actor_tx(
                    connection,
                    actor,
                    expected_runtime_id=expected_runtime_id,
                )
            continuation = (
                self._continuation_context_tx(connection, str(row["work_item_id"]))
                if row is not None
                else None
            )
        if row is None:
            raise NotFoundError("active attempt", attempt_id or actor["id"])
        if actor["role"] == PrincipalRole.WORKER.value and row["worker_id"] != actor["id"]:
            raise AuthorizationError("Worker cannot access another Worker's attempt")
        work = self.get_work(row["work_item_id"], actor)
        if actor["role"] == PrincipalRole.WORKER.value:
            work, safe_attempt = self._worker_context_views(work)
        else:
            safe_attempt = work["current_attempt"]
        inbox = self.get_inbox(actor, after=0, limit=100, attempt_id=row["id"])
        inbox_items = (
            [self._worker_context_message_view(item) for item in inbox["items"]]
            if actor["role"] == PrincipalRole.WORKER.value
            else inbox["items"]
        )
        return {
            "work": work,
            "attempt": safe_attempt,
            "inbox": inbox_items,
            "continuation": continuation,
        }

    @staticmethod
    def _worker_context_views(
        work: Mapping[str, Any],
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        """Return positive allowlists for the Worker-owned task surface."""

        goal = cast(Mapping[str, Any], work["current_goal_revision"])
        packet = goal.get("packet")
        dependencies = list(packet.get("dependencies", [])) if isinstance(packet, Mapping) else []
        attempt = cast(Mapping[str, Any], work["current_attempt"])
        safe_work = {
            "id": str(work["id"]),
            "title": str(work["title"]),
            "state": str(work["state"]),
            "priority": int(work["priority"]),
            "attention_owner": str(work["attention_owner"]),
            "generation": int(work["generation"]),
            "goal_version": int(work["goal_version"]),
            "objective": str(work["objective"]),
            "maturity": str(work["maturity"]),
            "acceptance": list(work["acceptance"]),
            "non_goals": list(work["non_goals"]),
            "completion_contract": str(work["completion_contract"]),
            "dependencies": dependencies,
            "managed_task_policy": (
                dict(packet["managed_task_policy"])
                if isinstance(packet, Mapping)
                and isinstance(packet.get("managed_task_policy"), Mapping)
                else None
            ),
        }
        safe_attempt = {
            "id": str(attempt["id"]),
            "work_item_id": str(attempt["work_item_id"]),
            "attempt_number": int(attempt["attempt_number"]),
            "goal_version": int(attempt["goal_version"]),
            "goal_packet_digest": str(attempt["goal_packet_digest"]),
            "task_packet_digest": str(attempt["task_packet_digest"]),
            "state": str(attempt["state"]),
            "trajectory": str(attempt["trajectory"]),
            "evidence_confidence": str(attempt["evidence_confidence"]),
            "stage": str(attempt["stage"]),
            "next_boundary": str(attempt["next_boundary"]),
        }
        return safe_work, safe_attempt

    @staticmethod
    def _worker_context_message_view(message: Mapping[str, Any]) -> dict[str, Any]:
        """Keep acknowledgement identity plus sealed task semantics only."""

        payload = message.get("payload")
        safe_payload: dict[str, Any] = {}
        if isinstance(payload, Mapping):
            semantic_fields = (
                "work_item_id",
                "attempt_id",
                "goal_version",
                "generation",
                "priority",
                "goal_packet_digest",
                "task_packet_digest",
                "managed_task_policy",
                "action",
                "response_due_at",
            )
            for field in semantic_fields:
                value = payload.get(field)
                if isinstance(value, Mapping) and field == "managed_task_policy":
                    safe_payload[field] = dict(value)
                elif isinstance(value, (str, int)) and not isinstance(value, bool):
                    safe_payload[field] = value
            message_kind = str(message.get("kind") or "")
            text_fields: tuple[str, ...] = ()
            if message_kind == MessageKind.ASSIGNMENT.value:
                text_fields = ("title", "objective", "maturity")
                command = payload.get("command")
                if isinstance(command, Mapping):
                    safe_payload["command"] = {
                        field: _worker_safe_report_text(command.get(field))
                        for field in ("action", "reason", "instruction")
                    }
            elif message_kind == MessageKind.INSTRUCTION.value:
                text_fields = ("instruction", "message")
            elif message_kind == MessageKind.STATUS_REQUEST.value:
                text_fields = ("summary",)
            for field in text_fields:
                safe_text = _worker_safe_report_text(payload.get(field))
                if safe_text:
                    safe_payload[field] = safe_text
            list_fields = (
                ("acceptance", "non_goals", "dependencies")
                if message_kind == MessageKind.ASSIGNMENT.value
                else ()
            )
            for field in list_fields:
                value = payload.get(field)
                if isinstance(value, list):
                    safe_payload[field] = [
                        safe for item in value if (safe := _worker_safe_report_text(item))
                    ]
        return {
            field: message[field]
            for field in (
                "id",
                "sequence",
                "work_item_id",
                "attempt_id",
                "kind",
                "payload_digest",
                "message_digest",
                "goal_version",
                "goal_packet_digest",
                "task_packet_digest",
                "created_at",
                "delivery_state",
                "acknowledged",
            )
            if field in message
        } | {"payload": safe_payload}

    @staticmethod
    def _continuation_context_tx(
        connection: sqlite3.Connection, successor_work_id: str
    ) -> dict[str, Any] | None:
        """Return a fixed, Worker-safe continuation provenance block."""

        rows = connection.execute(
            """
            SELECT directive.target_work_item_id AS prior_work_item_id,
                   directive.expected_goal_version AS prior_goal_version,
                   directive.expected_goal_packet_digest AS prior_goal_packet_digest,
                   prior.state AS prior_state,
                   prior_goal.packet_json AS prior_packet_json,
                   successor_goal.packet_json AS successor_packet_json
            FROM directives AS directive
            JOIN submitted_intents AS intent
              ON intent.id = directive.submitted_intent_id
             AND intent.source_receipt_id = directive.source_receipt_id
            JOIN intent_dispositions AS disposition
              ON disposition.submitted_intent_id = intent.id
             AND disposition.source_receipt_id = directive.source_receipt_id
             AND disposition.kind = 'task'
             AND disposition.relation = 'continue'
             AND disposition.target_work_item_id = directive.target_work_item_id
             AND disposition.result_work_item_id = directive.created_work_item_id
             AND disposition.result_directive_id = directive.id
            JOIN work_items AS prior
              ON prior.id = directive.target_work_item_id
            JOIN goal_revisions AS prior_goal
              ON prior_goal.work_item_id = prior.id
             AND prior_goal.version = directive.expected_goal_version
             AND prior_goal.packet_digest = directive.expected_goal_packet_digest
            JOIN work_items AS successor
              ON successor.id = directive.created_work_item_id
             AND successor.id = ?
             AND successor.id <> prior.id
             AND successor.supervisor_id = prior.supervisor_id
             AND successor.requester_id IS prior.requester_id
            JOIN goal_revisions AS successor_goal
              ON successor_goal.work_item_id = successor.id
             AND successor_goal.version = 1
             AND successor_goal.source_intent_id = intent.id
             AND successor_goal.correlation_id = directive.source_receipt_id
             AND successor_goal.title = prior_goal.title
             AND successor_goal.objective = prior_goal.objective
             AND successor_goal.maturity = prior_goal.maturity
             AND successor_goal.acceptance_json = prior_goal.acceptance_json
             AND successor_goal.non_goals_json = prior_goal.non_goals_json
             AND successor_goal.priority = prior_goal.priority
             AND successor_goal.requester_id IS prior_goal.requester_id
             AND successor_goal.metadata_json = prior_goal.metadata_json
            WHERE directive.relation = 'continue'
              AND directive.state = 'handled'
              AND directive.created_work_item_id = ?
              AND directive.target_work_item_id IS NOT NULL
            """,
            (successor_work_id, successor_work_id),
        ).fetchall()
        if len(rows) != 1:
            return None
        row = rows[0]
        prior_packet = _load(str(row["prior_packet_json"]), {})
        successor_packet = _load(str(row["successor_packet_json"]), {})
        if (
            not isinstance(prior_packet, Mapping)
            or not isinstance(successor_packet, Mapping)
            or list(prior_packet.get("dependencies", []))
            != list(successor_packet.get("dependencies", []))
            or prior_packet.get("managed_task_policy")
            != successor_packet.get("managed_task_policy")
        ):
            return None
        prior_work_item_id = str(row["prior_work_item_id"])
        progress_rows = connection.execute(
            """
            SELECT message.kind, message.payload_json, message.payload_digest,
                   message.message_digest, message.goal_version
            FROM messages AS message
            JOIN attempts AS attempt ON attempt.id = message.attempt_id
             AND attempt.work_item_id = message.work_item_id
             AND attempt.worker_id = message.sender_id
             AND attempt.goal_version = message.goal_version
             AND attempt.goal_packet_digest = message.goal_packet_digest
             AND attempt.task_packet_digest = message.task_packet_digest
            WHERE message.work_item_id = ?
              AND message.kind IN ('progress', 'artifact', 'completion_claim')
              AND attempt.goal_version = ?
              AND attempt.goal_packet_digest = ?
            ORDER BY message.sequence
            """,
            (
                prior_work_item_id,
                int(row["prior_goal_version"]),
                str(row["prior_goal_packet_digest"]),
            ),
        ).fetchall()
        progress_refs: list[dict[str, Any]] = []
        evidence_refs: list[dict[str, str]] = []
        for progress in progress_rows:
            payload = _load(str(progress["payload_json"]), {})
            if not isinstance(payload, Mapping):
                continue
            ref: dict[str, Any] = {
                "kind": str(progress["kind"]),
                "payload_digest": str(progress["payload_digest"]),
                "message_digest": str(progress["message_digest"]),
                "goal_version": int(progress["goal_version"]),
            }
            for field in ("summary", "stage", "next_boundary"):
                safe_text = _worker_safe_report_text(payload.get(field))
                if safe_text:
                    ref[field] = safe_text
            progress_refs.append(ref)
            evidence = payload.get("evidence", [])
            if isinstance(evidence, list):
                evidence_refs.extend(
                    {
                        "report_message_digest": str(progress["message_digest"]),
                        "evidence_digest": _digest(item),
                    }
                    for item in evidence
                    if isinstance(item, Mapping)
                )
        artifact_rows = connection.execute(
            """
            SELECT artifact.id, artifact.digest, artifact.media_type
            FROM artifacts AS artifact
            JOIN attempts AS attempt ON attempt.id = artifact.attempt_id
             AND attempt.work_item_id = artifact.work_item_id
             AND attempt.worker_id = artifact.producer_id
            WHERE artifact.work_item_id = ? AND artifact.digest <> ''
              AND attempt.goal_version = ?
              AND attempt.goal_packet_digest = ?
            ORDER BY artifact.created_at, artifact.id
            """,
            (
                prior_work_item_id,
                int(row["prior_goal_version"]),
                str(row["prior_goal_packet_digest"]),
            ),
        ).fetchall()
        return {
            "mode": "continue_prior",
            "prior_work_item_id": prior_work_item_id,
            "prior_goal_version": int(row["prior_goal_version"]),
            "prior_goal_packet_digest": str(row["prior_goal_packet_digest"]),
            "prior_state": str(row["prior_state"]),
            "provenance": "exact_goal_packet",
            "progress_refs": progress_refs,
            "artifact_refs": [
                {
                    "artifact_id": str(artifact["id"]),
                    "digest": str(artifact["digest"]),
                    "media_type": str(artifact["media_type"]),
                }
                for artifact in artifact_rows
            ],
            "evidence_refs": evidence_refs,
        }

    def cancel_work(
        self,
        actor: dict[str, Any],
        work_id: str,
        reason: str,
        idempotency_key: str = "",
    ) -> dict[str, Any]:
        """Record explicit cancellation as a durable submitted directive."""

        self._require_role(actor, PrincipalRole.CAO, PrincipalRole.USER)
        if not reason.strip():
            raise ValidationError("cancellation reason is required")
        request_digest = _digest({"work_item_id": work_id, "reason": reason.strip()})
        source_id = (
            f"cancel_work:{work_id}:{idempotency_key}" if idempotency_key else _id("cancel_source")
        )
        source_payload = {
            "type": "cancel_work",
            "target_work_item_id": work_id,
            "reason": reason.strip(),
        }
        disposition_request = IntentDisposition(
            kind=IntentKind.DIRECTIVE,
            relation=IntentRelation.CANCEL,
            target_work_item_id=work_id,
            directive=reason.strip(),
            reason=reason.strip(),
        )
        with self.db.transaction() as connection:
            if actor.get("_cao_attachment_id"):
                self._require_current_cao_attachment_actor_tx(connection, actor)
            work = self._require_authorized_work_tx(connection, actor, work_id)
            cached = self._idempotent_get_tx(
                connection,
                actor["id"],
                "cancel_work",
                idempotency_key,
                request_digest,
            )
            if cached is not None:
                return cached
            if work["state"] in {
                WorkState.COMPLETED.value,
                WorkState.CANCELED.value,
                WorkState.FAILED.value,
            }:
                raise ConflictError(
                    "terminal work cannot receive a cancellation directive",
                    state=work["state"],
                )
            receipt, intent = self._record_submitted_intent_tx(
                connection,
                source_principal_id=actor["id"],
                source_id=source_id,
                payload=source_payload,
            )
            directive = self._create_directive_tx(
                connection,
                actor_id=actor["id"],
                intent=intent,
                receipt=receipt,
                relation=IntentRelation.CANCEL,
                content=reason.strip(),
                reason=reason.strip(),
                target_work_item_id=work_id,
                created_work_item_id=None,
                expected_goal_version=int(work["goal_version"]),
            )
            result = self._cancel_work_tx(
                connection,
                actor_id=actor["id"],
                work=work,
                reason=reason.strip(),
                directive_id=str(directive["id"]),
            )
            self._store_intent_disposition_tx(
                connection,
                actor_id=actor["id"],
                intent=intent,
                receipt=receipt,
                kind=IntentKind.DIRECTIVE,
                relation=IntentRelation.CANCEL,
                target_work_item_id=work_id,
                result_work_item_id=work_id,
                result_directive_id=str(directive["id"]),
                reason=reason.strip(),
                request_digest=_digest(disposition_request.model_dump(mode="json")),
                result={
                    "receipt": self._source_receipt_view(receipt),
                    "intent": self._submitted_intent_view(intent),
                    "kind": IntentKind.DIRECTIVE.value,
                    "relation": IntentRelation.CANCEL.value,
                    "directive": directive,
                    "work": result,
                },
            )
            self._idempotent_put(
                connection,
                actor["id"],
                "cancel_work",
                idempotency_key,
                request_digest,
                result,
            )
            return result

    # ------------------------------------------------------------------
    # Messages and reports
    # ------------------------------------------------------------------
    def get_inbox(
        self,
        actor: dict[str, Any],
        *,
        after: int = 0,
        limit: int = 100,
        attempt_id: str | None = None,
        include_acknowledged: bool = False,
    ) -> dict[str, Any]:
        if actor.get("_cao_conversation_credential_id"):
            self._require_role(actor, PrincipalRole.CAO)
        clauses = ["d.recipient_id = ?", "m.sequence > ?"]
        params: list[Any] = [actor["id"], after]
        scoped_attachment_id = str(actor.get("_cao_attachment_id") or "")
        if scoped_attachment_id:
            clauses.append("d.recipient_attachment_id = ?")
            params.append(scoped_attachment_id)
            clauses.append(
                cao_notification_inbox_visible_sql(
                    include_acknowledged=include_acknowledged,
                )
            )
        if attempt_id:
            clauses.append("m.attempt_id = ?")
            params.append(attempt_id)
        if not scoped_attachment_id:
            if not include_acknowledged:
                clauses.append("d.state NOT IN (?, ?)")
                params.extend([DeliveryState.ACKNOWLEDGED.value, DeliveryState.HANDLED.value])
            clauses.append(runtime_delivery_lane_head_sql())
        params.append(min(max(limit, 1), 1000) + 1)
        with self.db.transaction() as connection:
            if actor.get("role") == PrincipalRole.CAO.value and scoped_attachment_id:
                self._require_current_cao_attachment_actor_tx(connection, actor)
            elif actor.get("role") == PrincipalRole.WORKER.value:
                self._require_worker_runtime_actor_tx(connection, actor)
            rows = connection.execute(
                f"""
                SELECT m.*, d.state AS recipient_delivery_state,
                       d.acknowledged_at, d.handled_at,
                       d.generation AS delivery_generation
                FROM messages m
                JOIN message_deliveries d
                  ON d.message_id = m.id AND d.recipient_id = ?
                WHERE {" AND ".join(clauses)}
                ORDER BY m.sequence ASC
                LIMIT ?
                """,
                [actor["id"], *params],
            ).fetchall()
            effective_limit = min(max(limit, 1), 1000)
            has_more = len(rows) > effective_limit
            rows = rows[:effective_limit]
            items = [self._message_view(row, connection=connection) for row in rows]
        return {
            "items": items,
            "next_cursor": items[-1]["sequence"] if has_more and items else None,
        }

    def _resolved_cao_boundary_notification_tx(
        self,
        connection: sqlite3.Connection,
        *,
        actor: dict[str, Any],
        message: sqlite3.Row,
        delivery: sqlite3.Row,
    ) -> dict[str, Any] | None:
        """Bind a late receipt to immutable resolution of its exact notification.

        A Boundary may be resolved while its Work awaits the requester, or be
        superseded by a later goal. Neither grants receipt authority for another
        packet or conversation, and neither proves native transport delivery.
        """

        attachment_id = str(actor.get("_cao_attachment_id") or "")
        if (
            actor.get("role") != PrincipalRole.CAO.value
            or not attachment_id
            or str(delivery["recipient_id"]) != actor["id"]
            or str(delivery["recipient_attachment_id"] or "") != attachment_id
        ):
            return None
        payload = _load(message["payload_json"], {})
        if not isinstance(payload, Mapping) or not payload.get("boundary_id"):
            return None
        if any(
            field in payload and payload[field] != message[field]
            for field in ("goal_packet_digest", "task_packet_digest")
        ):
            return None
        row = connection.execute(
            """
            SELECT boundary.id AS boundary_id, boundary.generation AS boundary_generation,
                   disposition.id AS disposition_id,
                   supersession.superseding_event_sequence
            FROM boundaries AS boundary
            JOIN work_items AS work ON work.id = boundary.work_item_id
            JOIN attempts AS attempt
              ON attempt.id = boundary.attempt_id
             AND attempt.work_item_id = boundary.work_item_id
            LEFT JOIN boundary_dispositions AS disposition
              ON disposition.boundary_id = boundary.id
             AND disposition.generation = boundary.generation
             AND disposition.decided_by = work.supervisor_id
            LEFT JOIN boundary_supersessions AS supersession
              ON supersession.boundary_id = boundary.id
            WHERE boundary.id = ?
              AND boundary.work_item_id = ? AND boundary.attempt_id = ?
              AND boundary.goal_version = ?
              AND boundary.goal_packet_digest = ? AND boundary.task_packet_digest = ?
              AND work.supervisor_id = ? AND work.supervisor_attachment_id = ?
              AND (disposition.id IS NOT NULL OR supersession.boundary_id IS NOT NULL)
            """,
            (
                str(payload["boundary_id"]),
                message["work_item_id"],
                message["attempt_id"],
                message["goal_version"],
                message["goal_packet_digest"],
                message["task_packet_digest"],
                actor["id"],
                attachment_id,
            ),
        ).fetchone()
        if row is None:
            return None
        for field in ("generation", "expected_generation"):
            if field in payload and (
                isinstance(payload[field], bool)
                or not isinstance(payload[field], int)
                or payload[field] != int(row["boundary_generation"])
            ):
                return None
        return {
            "boundary_id": str(row["boundary_id"]),
            "boundary_disposition_id": str(row["disposition_id"] or ""),
            "boundary_superseding_event_sequence": row["superseding_event_sequence"],
        }

    def acknowledge(self, actor: dict[str, Any], request: AckInput) -> dict[str, Any]:
        if actor.get("_cao_runtime_credential_id") or actor.get("_cao_conversation_credential_id"):
            self._require_role(actor, PrincipalRole.CAO)
        now = utc_now()
        acknowledged: list[str] = []
        with self.db.transaction() as connection:
            if actor.get("role") == PrincipalRole.CAO.value and (
                actor.get("_cao_conversation_credential_id")
                or actor.get("_cao_runtime_credential_id")
            ):
                self._require_current_cao_attachment_actor_tx(connection, actor)
            for message_id in dict.fromkeys(request.message_ids):
                message = connection.execute(
                    "SELECT * FROM messages WHERE id = ?", (message_id,)
                ).fetchone()
                if message is None:
                    raise NotFoundError("message", message_id)
                delivery = connection.execute(
                    """
                    SELECT * FROM message_deliveries
                    WHERE message_id = ? AND recipient_id = ?
                    """,
                    (message_id, actor["id"]),
                ).fetchone()
                if delivery is None:
                    raise AuthorizationError("message is not addressed to this principal")
                if actor.get("_cao_attachment_id"):
                    expected_attachment_id = str(actor["_cao_attachment_id"])
                    if str(delivery["recipient_attachment_id"] or "") != expected_attachment_id:
                        raise AuthorizationError("message is not bound to this CAO conversation")
                    active_runtime = connection.execute(
                        """
                        SELECT 1
                        FROM runtime_sessions AS active_runtime
                        WHERE active_runtime.id = ?
                          AND active_runtime.state = 'busy'
                          AND ? = (
                            SELECT newest_delivery.owner_token
                            FROM message_deliveries AS newest_delivery
                            JOIN messages AS newest_message
                              ON newest_message.id = newest_delivery.message_id
                            WHERE newest_delivery.runtime_session_id = ?
                              AND newest_delivery.recipient_id = ?
                              AND newest_delivery.state = 'dispatched'
                              AND newest_delivery.owner_token <> ''
                            ORDER BY newest_message.sequence DESC
                            LIMIT 1
                          )
                        """,
                        (
                            delivery["runtime_session_id"],
                            delivery["owner_token"],
                            delivery["runtime_session_id"],
                            delivery["recipient_id"],
                        ),
                    ).fetchone()
                    settled_unknown = delivery["state"] == DeliveryState.DISPATCHED.value and (
                        not str(delivery["owner_token"] or "")
                        or (
                            (delivery["lease_until"] is None or str(delivery["lease_until"]) <= now)
                            and active_runtime is None
                        )
                    )
                    if settled_unknown:
                        raise ConflictError(
                            "unknown CAO handoff is preserved and unavailable for acknowledgement",
                            state=delivery["state"],
                        )
                if actor.get("role") == PrincipalRole.WORKER.value:
                    expected_runtime_id = str(delivery["runtime_session_id"] or "")
                    if not expected_runtime_id:
                        raise ConflictError("Worker delivery is not bound to a managed MCP runtime")
                    self._require_worker_runtime_actor_tx(
                        connection,
                        actor,
                        expected_runtime_id=expected_runtime_id,
                    )
                if delivery["state"] in {
                    DeliveryState.ACKNOWLEDGED.value,
                    DeliveryState.HANDLED.value,
                }:
                    acknowledged.append(message_id)
                    continue
                if delivery["state"] == DeliveryState.DEAD.value:
                    boundary_resolution = self._resolved_cao_boundary_notification_tx(
                        connection, actor=actor, message=message, delivery=delivery
                    )
                    if boundary_resolution is not None:
                        # An explicit late CAO receipt settles semantic history,
                        # not transport. Retain the exact prior attempt count,
                        # generation, delivery timestamp, and supersession error.
                        updated = connection.execute(
                            """
                            UPDATE message_deliveries
                            SET state = ?, acknowledged_at = COALESCE(acknowledged_at, ?),
                                handled_at = COALESCE(handled_at, ?), updated_at = ?
                            WHERE message_id = ? AND recipient_id = ?
                              AND generation = ? AND state = ?
                            """,
                            (
                                DeliveryState.HANDLED.value,
                                now,
                                now,
                                now,
                                message_id,
                                actor["id"],
                                delivery["generation"],
                                DeliveryState.DEAD.value,
                            ),
                        ).rowcount
                        if updated != 1:
                            raise ConflictError("message acknowledgement lost its delivery fence")
                        self._event(
                            connection,
                            "message.dead_acknowledged",
                            "message",
                            message_id,
                            actor["id"],
                            {
                                **boundary_resolution,
                                "prior_delivery_state": DeliveryState.DEAD.value,
                                "delivery_generation": int(delivery["generation"]),
                                "prior_error_digest": _digest(str(delivery["last_error"])),
                            },
                            causation_id=message_id,
                        )
                        acknowledged.append(message_id)
                        continue
                    payload = _load(message["payload_json"], {})
                    if (
                        actor.get("role") == PrincipalRole.CAO.value
                        and actor.get("_cao_attachment_id")
                        and isinstance(payload, Mapping)
                        and payload.get("boundary_id")
                    ):
                        # A terminal Work is not a substitute for the exact
                        # historical Boundary/packet authority of this receipt.
                        raise ConflictError(
                            "message is not available for acknowledgement",
                            state=delivery["state"],
                        )
                    work = (
                        connection.execute(
                            "SELECT state FROM work_items WHERE id = ?",
                            (message["work_item_id"],),
                        ).fetchone()
                        if message["work_item_id"] is not None
                        else None
                    )
                    if work is not None and work["state"] in {
                        WorkState.COMPLETED.value,
                        WorkState.CANCELED.value,
                        WorkState.FAILED.value,
                    }:
                        updated = connection.execute(
                            """
                            UPDATE message_deliveries
                            SET state = ?, acknowledged_at = COALESCE(acknowledged_at, ?),
                                handled_at = COALESCE(handled_at, ?), lease_until = NULL,
                                owner_token = '', updated_at = ?
                            WHERE message_id = ? AND recipient_id = ? AND state = ?
                            """,
                            (
                                DeliveryState.HANDLED.value,
                                now,
                                now,
                                now,
                                message_id,
                                actor["id"],
                                DeliveryState.DEAD.value,
                            ),
                        ).rowcount
                        if updated == 1:
                            self._event(
                                connection,
                                "message.dead_acknowledged",
                                "message",
                                message_id,
                                actor["id"],
                                {"terminal_work_state": str(work["state"])},
                                causation_id=message_id,
                            )
                        acknowledged.append(message_id)
                        continue
                self._require_delivery_head_tx(connection, message, delivery)
                attempt = None
                if message["attempt_id"] is not None:
                    attempt = connection.execute(
                        "SELECT * FROM attempts WHERE id = ?",
                        (message["attempt_id"],),
                    ).fetchone()
                    if (
                        attempt is None
                        or int(message["goal_version"] or 0) != int(attempt["goal_version"])
                        or str(message["goal_packet_digest"]) != str(attempt["goal_packet_digest"])
                        or str(message["task_packet_digest"]) != str(attempt["task_packet_digest"])
                    ):
                        raise ConflictError("message acknowledgement targets a stale task packet")
                if delivery["state"] not in {
                    DeliveryState.QUEUED.value,
                    DeliveryState.LEASED.value,
                    DeliveryState.DISPATCHED.value,
                    DeliveryState.DELIVERED.value,
                }:
                    raise ConflictError(
                        "message is not available for acknowledgement",
                        state=delivery["state"],
                    )
                updated = connection.execute(
                    """
                    UPDATE message_deliveries
                    SET state = ?, acknowledged_at = COALESCE(acknowledged_at, ?),
                        lease_until = NULL, owner_token = '', updated_at = ?
                    WHERE message_id = ? AND recipient_id = ?
                      AND state IN ('queued', 'leased', 'dispatched', 'delivered')
                    """,
                    (
                        DeliveryState.ACKNOWLEDGED.value,
                        now,
                        now,
                        message_id,
                        actor["id"],
                    ),
                ).rowcount
                if updated != 1:
                    raise ConflictError("message acknowledgement lost its delivery fence")
                self._event(
                    connection,
                    "message.acknowledged",
                    "message",
                    message_id,
                    actor["id"],
                    {},
                    causation_id=message_id,
                )
                if (
                    attempt is not None
                    and message["kind"] == MessageKind.ASSIGNMENT.value
                    and attempt["worker_id"] == actor["id"]
                    and attempt["state"] == AttemptState.ASSIGNED.value
                ):
                    connection.execute(
                        "UPDATE attempts SET state = ?, updated_at = ? WHERE id = ?",
                        (AttemptState.ACCEPTED.value, now, attempt["id"]),
                    )
                    self._event(
                        connection,
                        "work.assignment_accepted",
                        "work_item",
                        str(attempt["work_item_id"]),
                        actor["id"],
                        {
                            "attempt_id": str(attempt["id"]),
                            "goal_version": int(attempt["goal_version"]),
                            "goal_packet_digest": str(attempt["goal_packet_digest"]),
                            "task_packet_digest": str(attempt["task_packet_digest"]),
                        },
                        causation_id=message_id,
                    )
                acknowledged.append(message_id)
        return {"acknowledged": acknowledged, "at": now}

    def resolve_delivery(
        self,
        actor: dict[str, Any],
        message_id: str,
        request: DeliveryResolveInput,
    ) -> dict[str, Any]:
        """Resolve a dispatch whose external delivery outcome is unknown."""

        self._require_role(actor, PrincipalRole.CAO)
        now = utc_now()
        with self.db.transaction() as connection:
            message = connection.execute(
                "SELECT * FROM messages WHERE id = ?", (message_id,)
            ).fetchone()
            if message is None:
                raise NotFoundError("message", message_id)
            work: sqlite3.Row | None = None
            if message["work_item_id"] is not None:
                work = connection.execute(
                    "SELECT * FROM work_items WHERE id = ?",
                    (message["work_item_id"],),
                ).fetchone()
                if work is None:
                    raise NotFoundError("work item", str(message["work_item_id"]))
                self._authorize_work_actor(actor, work)
            delivery = connection.execute(
                """
                SELECT * FROM message_deliveries
                WHERE message_id = ? AND recipient_id = ?
                """,
                (message_id, request.recipient_id),
            ).fetchone()
            if delivery is None:
                raise NotFoundError("message delivery", message_id)
            if delivery["state"] != DeliveryState.DISPATCHED.value:
                raise ConflictError(
                    "only an unknown dispatched delivery can be resolved",
                    state=delivery["state"],
                )
            if request.outcome == "delivered":
                next_state = DeliveryState.DELIVERED
                generation_increment = 0
                delivered_at = now
                next_attempt_at = delivery["next_attempt_at"]
            elif request.outcome == "not_delivered":
                assignment_is_current = True
                if str(message["kind"]) == MessageKind.ASSIGNMENT.value:
                    payload = _load(str(message["payload_json"]), {})
                    attempt = (
                        connection.execute(
                            """
                            SELECT attempt.*
                            FROM attempts AS attempt
                            WHERE attempt.id = ? AND attempt.work_item_id = ?
                              AND attempt.id = (
                                SELECT latest.id FROM attempts AS latest
                                WHERE latest.work_item_id = attempt.work_item_id
                                ORDER BY latest.attempt_number DESC LIMIT 1
                              )
                            """,
                            (message["attempt_id"], message["work_item_id"]),
                        ).fetchone()
                        if message["attempt_id"] is not None and message["work_item_id"] is not None
                        else None
                    )
                    assignment_is_current = bool(
                        work is not None
                        and attempt is not None
                        and isinstance(payload, Mapping)
                        and _digest(payload) == str(message["payload_digest"])
                        and str(payload.get("work_item_id") or "") == str(work["id"])
                        and str(payload.get("attempt_id") or "") == str(attempt["id"])
                        and payload.get("generation") == int(work["generation"])
                        and str(work["state"]) == WorkState.ACTIVE.value
                        and str(work["attention_owner"]) == AttentionOwner.WORKER.value
                        and str(attempt["state"])
                        in {
                            AttemptState.ASSIGNED.value,
                            AttemptState.ACCEPTED.value,
                            AttemptState.WORKING.value,
                        }
                        and str(attempt["worker_id"]) == str(request.recipient_id)
                        and str(attempt["runtime_session_id"] or "")
                        == str(delivery["runtime_session_id"] or "")
                    )
                next_state = DeliveryState.QUEUED if assignment_is_current else DeliveryState.DEAD
                generation_increment = 1 if assignment_is_current else 0
                delivered_at = None
                next_attempt_at = now
            else:
                next_state = DeliveryState.DEAD
                generation_increment = 0
                delivered_at = None
                next_attempt_at = delivery["next_attempt_at"]
            last_error = (
                "system_reconciliation_required"
                if request.outcome == "not_delivered" and next_state == DeliveryState.DEAD
                else f"resolved:{request.outcome};evidence_digest={_digest(request.evidence)}"
            )
            updated = connection.execute(
                """
                UPDATE message_deliveries
                SET state = ?, generation = generation + ?, next_attempt_at = ?,
                    delivered_at = COALESCE(delivered_at, ?), lease_until = NULL,
                    owner_token = '', last_error = ?, updated_at = ?
                WHERE message_id = ? AND recipient_id = ? AND state = ?
                """,
                (
                    next_state.value,
                    generation_increment,
                    next_attempt_at,
                    delivered_at,
                    last_error,
                    now,
                    message_id,
                    request.recipient_id,
                    DeliveryState.DISPATCHED.value,
                ),
            ).rowcount
            if updated != 1:
                raise ConflictError("delivery resolution lost its state fence")
            if request.outcome == "not_delivered" and next_state == DeliveryState.DEAD:
                self._event(
                    connection,
                    "message.delivery_superseded",
                    "message",
                    message_id,
                    actor["id"],
                    {
                        "recipient_id": request.recipient_id,
                        "reason_code": "system_reconciliation_required",
                    },
                    causation_id=message_id,
                )
            if (
                request.outcome == "not_delivered"
                and str(message["kind"]) == MessageKind.ASSIGNMENT.value
                and message["attempt_id"] is not None
                and delivery["runtime_session_id"] is not None
            ):
                # This explicit outcome is the sole post-dispatch proof that
                # no provider handoff occurred. Release only the exact
                # half-open tuple in the same transaction as the Delivery
                # generation fence; delivered/dead/unknown never reopen it.
                self._release_provider_runtime_probe_tx(
                    connection,
                    str(delivery["runtime_session_id"]),
                    message_id,
                    str(message["attempt_id"]),
                )
            self._event(
                connection,
                "message.delivery_resolved",
                "message",
                message_id,
                actor["id"],
                {
                    "recipient_id": request.recipient_id,
                    "outcome": request.outcome,
                    "evidence_digest": _digest(request.evidence),
                },
                causation_id=message_id,
            )
            row = connection.execute(
                """
                SELECT * FROM message_deliveries
                WHERE message_id = ? AND recipient_id = ?
                """,
                (message_id, request.recipient_id),
            ).fetchone()
            assert row is not None
            return dict(row)

    def mark_message_handled(
        self, actor: dict[str, Any], message_id: str, *, evidence: str
    ) -> dict[str, Any]:
        if actor.get("_cao_runtime_credential_id") or actor.get("_cao_conversation_credential_id"):
            self._require_role(actor, PrincipalRole.CAO)
        if not evidence.strip():
            raise ValidationError("message handling evidence is required")
        now = utc_now()
        with self.db.transaction() as connection:
            if actor.get("role") == PrincipalRole.CAO.value and actor.get("_cao_attachment_id"):
                self._require_current_cao_attachment_actor_tx(connection, actor)
            delivery = connection.execute(
                """
                SELECT * FROM message_deliveries
                WHERE message_id = ? AND recipient_id = ?
                """,
                (message_id, actor["id"]),
            ).fetchone()
            if delivery is None:
                raise NotFoundError("message delivery", message_id)
            if actor.get("_cao_attachment_id"):
                expected_attachment_id = str(actor["_cao_attachment_id"])
                if str(delivery["recipient_attachment_id"] or "") != expected_attachment_id:
                    raise AuthorizationError("message is not bound to this CAO conversation")
            if actor.get("role") == PrincipalRole.WORKER.value:
                expected_runtime_id = str(delivery["runtime_session_id"] or "")
                if not expected_runtime_id:
                    raise ConflictError("Worker delivery is not bound to a managed MCP runtime")
                self._require_worker_runtime_actor_tx(
                    connection,
                    actor,
                    expected_runtime_id=expected_runtime_id,
                )
            message = connection.execute(
                "SELECT * FROM messages WHERE id = ?", (message_id,)
            ).fetchone()
            if message is None:
                raise NotFoundError("message", message_id)
            self._require_delivery_head_tx(connection, message, delivery)
            if delivery["state"] == DeliveryState.HANDLED.value:
                return dict(delivery)
            if delivery["state"] != DeliveryState.ACKNOWLEDGED.value:
                raise ConflictError(
                    "message must be acknowledged before it is handled",
                    state=delivery["state"],
                )
            payload = _load(message["payload_json"], {})
            boundary_id = (
                str(payload.get("boundary_id") or "") if isinstance(payload, Mapping) else ""
            )
            if boundary_id:
                if actor.get("role") == PrincipalRole.CAO.value and actor.get("_cao_attachment_id"):
                    resolved = self._resolved_cao_boundary_notification_tx(
                        connection, actor=actor, message=message, delivery=delivery
                    )
                else:
                    resolved = connection.execute(
                        "SELECT boundary_id FROM boundary_dispositions WHERE boundary_id = ? "
                        "UNION ALL "
                        "SELECT boundary_id FROM boundary_supersessions WHERE boundary_id = ?",
                        (boundary_id, boundary_id),
                    ).fetchone()
                if resolved is None:
                    raise ConflictError(
                        "supervisor boundary must be disposed before its message is handled",
                        boundary_id=boundary_id,
                    )
            connection.execute(
                """
                UPDATE message_deliveries
                SET state = ?, handled_at = ?, updated_at = ?
                WHERE message_id = ? AND recipient_id = ?
                """,
                (
                    DeliveryState.HANDLED.value,
                    now,
                    now,
                    message_id,
                    actor["id"],
                ),
            )
            self._event(
                connection,
                "message.handled",
                "message",
                message_id,
                actor["id"],
                {"evidence_digest": _digest(evidence.strip())},
                causation_id=message_id,
            )
            row = connection.execute(
                """
                SELECT * FROM message_deliveries
                WHERE message_id = ? AND recipient_id = ?
                """,
                (message_id, actor["id"]),
            ).fetchone()
            assert row is not None
            return dict(row)

    def _require_delivery_head_tx(
        self,
        connection: sqlite3.Connection,
        message: sqlite3.Row,
        delivery: sqlite3.Row,
    ) -> None:
        """Require command FIFO without coupling independent CAO notifications.

        MCP inbox reads and acknowledgements are a pull-delivery path.  They
        must enforce the same predecessor fence as the asynchronous dispatcher
        so a Worker cannot observe or apply a later correction/cancel packet
        before the earlier packet is fully handled.
        """

        if str(delivery["recipient_attachment_id"] or ""):
            # The caller separately verifies the exact attachment, unknown
            # handoff state, and Boundary disposition. Reading or incorporating
            # a notification never requires a decision about an earlier Work.
            return

        head = connection.execute(
            f"""
            SELECT 1
            FROM messages AS m
            JOIN message_deliveries AS d
              ON d.message_id = m.id AND d.recipient_id = ?
            WHERE m.id = ? AND d.runtime_session_id IS ?
              AND {runtime_delivery_lane_head_sql()}
            """,
            (
                delivery["recipient_id"],
                message["id"],
                delivery["runtime_session_id"],
            ),
        ).fetchone()
        if head is None:
            raise ConflictError("message has an unhandled predecessor")

    def send_message(
        self,
        actor: dict[str, Any],
        recipient_ids: Iterable[str],
        *,
        kind: MessageKind,
        payload: dict[str, Any],
        work_item_id: str | None = None,
        attempt_id: str | None = None,
        goal_version: int | None = None,
        idempotency_key: str = "",
    ) -> dict[str, Any]:
        self._require_role(actor, PrincipalRole.CAO)
        with self.db.transaction() as connection:
            return self._message(
                connection,
                sender_id=actor["id"],
                recipient_ids=recipient_ids,
                kind=kind,
                payload=payload,
                work_item_id=work_item_id,
                attempt_id=attempt_id,
                goal_version=goal_version,
                idempotency_key=idempotency_key,
            )

    def report(
        self,
        actor: dict[str, Any],
        attempt_id: str,
        request: ReportInput,
    ) -> dict[str, Any]:
        self._require_role(actor, PrincipalRole.WORKER)
        request_payload = request.model_dump(mode="json")
        if contains_control_plane_secret(request_payload) or _contains_generic_credential(
            request_payload
        ):
            # A Worker necessarily knows its current runtime credential.  It
            # must not be able to smuggle that credential (or any other CAO
            # bearer/ticket) into completion claims, artifacts, Boundaries,
            # Messages, Events, or idempotency results.
            raise ValidationError("Worker report contains credential-like secret")
        locator_payload = dict(request_payload)
        locator_payload["artifacts"] = [
            {key: value for key, value in artifact.items() if key != "uri"}
            for artifact in request_payload.get("artifacts", [])
            if isinstance(artifact, Mapping)
        ]
        if _contains_private_locator(locator_payload):
            raise ValidationError("Worker report contains a private locator")
        digest_payload = self._artifact_request_digest_payload(request_payload)
        request_digest = _digest({"attempt_id": attempt_id, "request": digest_payload})
        compatible_request_digest_values = [
            _digest({"attempt_id": attempt_id, "request": request_payload})
        ]
        if not request.incorporated_message_ids:
            pre_instruction_payload = dict(digest_payload)
            pre_instruction_payload.pop("incorporated_message_ids", None)
            compatible_request_digest_values.append(
                _digest({"attempt_id": attempt_id, "request": pre_instruction_payload})
            )
            legacy_payload = dict(request_payload)
            legacy_payload.pop("incorporated_message_ids", None)
            compatible_request_digest_values.append(
                _digest({"attempt_id": attempt_id, "request": legacy_payload})
            )
        compatible_request_digests = tuple(
            value
            for value in dict.fromkeys(compatible_request_digest_values)
            if value != request_digest
        )
        with self.db.transaction() as connection:
            attempt = connection.execute(
                "SELECT * FROM attempts WHERE id = ?", (attempt_id,)
            ).fetchone()
            if attempt is None:
                raise NotFoundError("attempt", attempt_id)
            if attempt["worker_id"] != actor["id"]:
                raise AuthorizationError("Worker cannot report for another Worker's attempt")
            expected_runtime_id = str(attempt["runtime_session_id"] or "")
            if not expected_runtime_id:
                raise ConflictError("Worker attempt is not bound to a managed MCP runtime")
            self._require_worker_runtime_actor_tx(
                connection,
                actor,
                expected_runtime_id=expected_runtime_id,
            )
            work = connection.execute(
                "SELECT * FROM work_items WHERE id = ?", (attempt["work_item_id"],)
            ).fetchone()
            if work is None:
                raise NotFoundError("work item", attempt["work_item_id"])
            self._authorize_work_actor(actor, work)
            cached = self._idempotent_get_tx(
                connection,
                actor["id"],
                "report",
                request.idempotency_key,
                request_digest,
                compatible_request_digests=compatible_request_digests,
            )
            if cached is not None:
                return cached
            if work["goal_version"] != request.expected_goal_version:
                raise StaleGoalError(request.expected_goal_version, work["goal_version"])
            if (
                str(attempt["goal_packet_digest"]) != request.expected_goal_packet_digest
                or str(attempt["task_packet_digest"]) != request.expected_task_packet_digest
                or int(attempt["goal_version"]) != request.expected_goal_version
            ):
                raise ConflictError("report targets a stale or partial task packet")
            if int(work["generation"]) != request.expected_generation:
                raise StaleGenerationError(request.expected_generation, int(work["generation"]))
            latest_attempt = self._latest_attempt_tx(connection, str(work["id"]))
            if latest_attempt is None or latest_attempt["id"] != attempt_id:
                raise ConflictError("report targets a superseded attempt")
            if attempt["state"] in {
                AttemptState.SUSPENDED.value,
                AttemptState.COMPLETED.value,
                AttemptState.FAILED.value,
                AttemptState.CANCELED.value,
            }:
                raise ConflictError(
                    "attempt cannot report in its current state",
                    state=attempt["state"],
                )
            if work["state"] in {
                WorkState.COMPLETED.value,
                WorkState.CANCELED.value,
                WorkState.FAILED.value,
            }:
                raise ConflictError("cannot report against terminal work", state=work["state"])

            unresolved_boundary = connection.execute(
                """
                SELECT b.id
                FROM boundaries AS b
                LEFT JOIN boundary_dispositions AS d ON d.boundary_id = b.id
                LEFT JOIN boundary_supersessions AS s ON s.boundary_id = b.id
                WHERE b.attempt_id = ? AND d.id IS NULL
                  AND s.boundary_id IS NULL
                ORDER BY b.created_at DESC
                LIMIT 1
                """,
                (attempt_id,),
            ).fetchone()
            if unresolved_boundary is not None:
                raise ConflictError(
                    "attempt already has an unresolved supervisor boundary",
                    boundary_id=unresolved_boundary["id"],
                )

            incorporated_instructions = [
                self._require_incorporated_worker_instruction_tx(
                    connection,
                    message_id=message_id,
                    actor_id=str(actor["id"]),
                    expected_runtime_id=expected_runtime_id,
                    work=work,
                    attempt=attempt,
                    request=request,
                )
                for message_id in request.incorporated_message_ids
            ]

            now = utc_now()
            self._handle_attempt_assignment_from_report_tx(
                connection,
                actor_id=actor["id"],
                runtime_id=expected_runtime_id,
                attempt_id=attempt_id,
                report_kind=request.kind,
                now=now,
            )
            self._handle_status_requests_from_report_tx(
                connection,
                actor_id=actor["id"],
                runtime_id=expected_runtime_id,
                attempt_id=attempt_id,
                report_kind=request.kind,
                now=now,
            )
            needs_disposition = request.kind in {
                ReportKind.QUESTION,
                ReportKind.BLOCKER,
                ReportKind.COMPLETION_CLAIM,
            }
            attempt_state = (
                AttemptState.WAITING_SUPERVISOR if needs_disposition else AttemptState.WORKING
            )
            work_state = WorkState.WAITING_SUPERVISOR if needs_disposition else WorkState.ACTIVE
            attention = AttentionOwner.CAO if needs_disposition else AttentionOwner.WORKER
            trajectory = (
                request.trajectory.value
                if request.trajectory is not None
                else (
                    Trajectory.COMPLETE.value
                    if request.kind == ReportKind.COMPLETION_CLAIM
                    else attempt["trajectory"]
                )
            )
            evidence_confidence = (
                EvidenceConfidence.DECLARED.value
                if request.kind == ReportKind.COMPLETION_CLAIM
                else attempt["evidence_confidence"]
            )
            artifact_views: list[dict[str, Any]] = []
            for artifact in request.artifacts:
                artifact_views.append(
                    self._create_artifact_tx(
                        connection,
                        actor=actor,
                        work=work,
                        attempt=attempt,
                        artifact=artifact,
                    )
                )
            if request.kind == ReportKind.COMPLETION_CLAIM:
                claimed_artifacts = artifact_views
                if not claimed_artifacts:
                    claimed_artifacts = [
                        self._artifact_view(row)
                        for row in connection.execute(
                            "SELECT * FROM artifacts WHERE attempt_id = ? ORDER BY created_at, id",
                            (attempt_id,),
                        ).fetchall()
                        if re.fullmatch(r"[0-9a-f]{64}", str(row["digest"]))
                        and str(row["uri"]) == f"owner-private-artifact:{row['digest']}"
                    ]
                completion_claim = {
                    "summary": request.summary,
                    "evidence": request.evidence,
                    "artifacts": claimed_artifacts,
                    "artifact_manifest_scope": "verified_attempt_artifacts_v2",
                    "goal_packet_digest": request.expected_goal_packet_digest,
                    "task_packet_digest": request.expected_task_packet_digest,
                    "claimed_at": now,
                }
            else:
                completion_claim = _load(attempt["completion_claim_json"], {})
            connection.execute(
                """
                UPDATE attempts
                SET state = ?, trajectory = ?, evidence_confidence = ?,
                    stage = ?, next_boundary = ?, completion_claim_json = ?,
                    updated_at = ?
                WHERE id = ?
                """,
                (
                    attempt_state.value,
                    trajectory,
                    evidence_confidence,
                    request.stage,
                    request.next_boundary,
                    _json(completion_claim),
                    now,
                    attempt_id,
                ),
            )
            connection.execute(
                """
                UPDATE work_items
                SET state = ?, attention_owner = ?, updated_at = ?
                WHERE id = ?
                """,
                (work_state.value, attention.value, now, work["id"]),
            )
            boundary: dict[str, Any] | None = None
            if needs_disposition:
                boundary_kind = {
                    ReportKind.QUESTION: BoundaryKind.QUESTION,
                    ReportKind.BLOCKER: BoundaryKind.BLOCKER,
                    ReportKind.COMPLETION_CLAIM: BoundaryKind.COMPLETION,
                }[request.kind]
                source_event_id = (
                    f"report:{attempt_id}:{request.idempotency_key}"
                    if request.idempotency_key
                    else _id("report_event")
                )
                boundary = self._record_boundary_tx(
                    connection,
                    actor=actor,
                    request=BoundaryInput(
                        source_event_id=source_event_id,
                        work_item_id=str(work["id"]),
                        attempt_id=attempt_id,
                        expected_goal_version=int(work["goal_version"]),
                        expected_goal_packet_digest=request.expected_goal_packet_digest,
                        expected_task_packet_digest=request.expected_task_packet_digest,
                        expected_generation=request.expected_generation,
                        kind=boundary_kind,
                        summary=request.summary,
                        runtime_state=RuntimeState.WAITING,
                        metadata={
                            "report_kind": request.kind.value,
                            "trajectory": trajectory,
                            "stage": request.stage,
                            "next_boundary": request.next_boundary,
                            "evidence": request.evidence,
                            "artifact_ids": [artifact["id"] for artifact in artifact_views],
                        },
                    ),
                )
            kind = MessageKind(request.kind.value)
            payload = {
                "summary": request.summary,
                "trajectory": trajectory,
                "stage": request.stage,
                "next_boundary": request.next_boundary,
                "evidence": request.evidence,
                "artifacts": artifact_views,
                "incorporated_message_ids": list(request.incorporated_message_ids),
                "boundary_id": boundary["id"] if boundary else None,
            }
            message = self._message(
                connection,
                sender_id=actor["id"],
                recipient_id=work["supervisor_id"] or work["created_by"],
                kind=kind,
                payload=payload,
                work_item_id=work["id"],
                attempt_id=attempt_id,
                goal_version=work["goal_version"],
                idempotency_key=(
                    f"report:{request.idempotency_key}" if request.idempotency_key else ""
                ),
                # Every meaningful Worker report wakes the exact immutable CAO
                # conversation selected at delegation.  Deliveries remain
                # individual durable facts: each lane head owns one CAO turn,
                # and only after that exact Delivery is handled may the next
                # Delivery be queued.  A turn must never drain a later message
                # whose own native wake can already be admitted.  An artifact-
                # only report remains history/read-model input and does not
                # autonomously resume the model.
                create_delivery=request.kind != ReportKind.ARTIFACT,
            )
            self._event(
                connection,
                f"attempt.{request.kind.value}",
                "attempt",
                attempt_id,
                actor["id"],
                payload,
                causation_id=message["id"],
            )
            for instruction, delivery in incorporated_instructions:
                self._handle_incorporated_worker_instruction_tx(
                    connection,
                    actor_id=str(actor["id"]),
                    instruction=instruction,
                    delivery=delivery,
                    report_message_id=str(message["id"]),
                    report_kind=request.kind,
                    now=now,
                )
            self._close_provider_rate_limit_probe_tx(
                connection,
                expected_runtime_id,
                attempt_id,
                actor_id=str(actor["id"]),
            )
            result = self._work_bundle_tx(connection, work["id"])
            self._idempotent_put(
                connection,
                actor["id"],
                "report",
                request.idempotency_key,
                request_digest,
                result,
            )
        return result

    def _require_incorporated_worker_instruction_tx(
        self,
        connection: sqlite3.Connection,
        *,
        message_id: str,
        actor_id: str,
        expected_runtime_id: str,
        work: sqlite3.Row,
        attempt: sqlite3.Row,
        request: ReportInput,
    ) -> tuple[sqlite3.Row, sqlite3.Row]:
        """Validate an exact acknowledged instruction before report mutation."""

        instruction = connection.execute(
            "SELECT * FROM messages WHERE id = ?",
            (message_id,),
        ).fetchone()
        if instruction is None:
            raise NotFoundError("message", message_id)
        expected_supervisor = str(work["supervisor_id"] or work["created_by"])
        if (
            str(instruction["kind"]) != MessageKind.INSTRUCTION.value
            or str(instruction["sender_id"]) != expected_supervisor
            or str(instruction["work_item_id"] or "") != str(work["id"])
            or str(instruction["attempt_id"] or "") != str(attempt["id"])
            or int(instruction["goal_version"] or 0) != request.expected_goal_version
            or str(instruction["goal_packet_digest"]) != request.expected_goal_packet_digest
            or str(instruction["task_packet_digest"]) != request.expected_task_packet_digest
        ):
            raise ConflictError("incorporated message is not an instruction for this task packet")
        delivery = connection.execute(
            "SELECT * FROM message_deliveries WHERE message_id = ? AND recipient_id = ?",
            (message_id, actor_id),
        ).fetchone()
        if (
            delivery is None
            or str(delivery["runtime_session_id"] or "") != expected_runtime_id
            or str(delivery["state"]) != DeliveryState.ACKNOWLEDGED.value
        ):
            raise ConflictError(
                "incorporated instruction must be acknowledged on this runtime lane"
            )
        self._require_delivery_head_tx(connection, instruction, delivery)
        return instruction, delivery

    def _handle_incorporated_worker_instruction_tx(
        self,
        connection: sqlite3.Connection,
        *,
        actor_id: str,
        instruction: sqlite3.Row,
        delivery: sqlite3.Row,
        report_message_id: str,
        report_kind: ReportKind,
        now: str,
    ) -> None:
        """Settle one explicitly incorporated instruction with exact evidence."""

        updated = connection.execute(
            """
            UPDATE message_deliveries
            SET state = 'handled', handled_at = ?, lease_until = NULL,
                owner_token = '', updated_at = ?
            WHERE message_id = ? AND recipient_id = ?
              AND runtime_session_id = ? AND generation = ?
              AND state = 'acknowledged'
            """,
            (
                now,
                now,
                instruction["id"],
                actor_id,
                delivery["runtime_session_id"],
                delivery["generation"],
            ),
        ).rowcount
        if updated != 1:
            raise ConflictError("instruction handling lost its delivery fence")
        self._event(
            connection,
            "message.handled",
            "message",
            str(instruction["id"]),
            actor_id,
            {
                "reason_code": "worker_report_incorporated_instruction",
                "report_kind": report_kind.value,
                "evidence_digest": _digest(
                    {
                        "report_message_id": report_message_id,
                        "instruction_message_id": str(instruction["id"]),
                    }
                ),
            },
            causation_id=report_message_id,
        )

    def _handle_attempt_assignment_from_report_tx(
        self,
        connection: sqlite3.Connection,
        *,
        actor_id: str,
        runtime_id: str,
        attempt_id: str,
        report_kind: ReportKind,
        now: str,
    ) -> None:
        """Consume the exact Assignment proven incorporated by a Worker report.

        Any fenced report demonstrates that the Worker read and acted on its
        immutable task packet. Leaving that Assignment merely acknowledged
        would make the ordered inbox hide every later correction or review
        instruction and deadlock supervision.
        """

        row = connection.execute(
            """
            SELECT m.id, d.state
            FROM messages AS m
            JOIN message_deliveries AS d
              ON d.message_id = m.id AND d.recipient_id = ?
            WHERE m.attempt_id = ? AND m.kind = 'assignment'
              AND d.runtime_session_id = ?
            ORDER BY m.sequence
            LIMIT 1
            """,
            (actor_id, attempt_id, runtime_id),
        ).fetchone()
        if row is None or row["state"] == DeliveryState.HANDLED.value:
            return
        updated = connection.execute(
            """
            UPDATE message_deliveries
            SET state = 'handled', delivered_at = COALESCE(delivered_at, ?),
                acknowledged_at = COALESCE(acknowledged_at, ?),
                handled_at = COALESCE(handled_at, ?), lease_until = NULL,
                owner_token = '', updated_at = ?
            WHERE message_id = ? AND recipient_id = ?
              AND runtime_session_id = ?
              AND state IN ('queued', 'leased', 'dispatched', 'delivered', 'acknowledged')
            """,
            (now, now, now, now, row["id"], actor_id, runtime_id),
        ).rowcount
        if updated == 1:
            self._event(
                connection,
                "message.handled",
                "message",
                str(row["id"]),
                actor_id,
                {
                    "evidence_digest": _digest(
                        f"worker-report-incorporated-assignment:{report_kind.value}"
                    )
                },
                causation_id=str(row["id"]),
            )

    def _handle_status_requests_from_report_tx(
        self,
        connection: sqlite3.Connection,
        *,
        actor_id: str,
        runtime_id: str,
        attempt_id: str,
        report_kind: ReportKind,
        now: str,
    ) -> None:
        """Treat a fenced Worker report as incorporation of prior status asks."""

        if report_kind == ReportKind.ARTIFACT:
            return

        rows = connection.execute(
            """
            SELECT m.id FROM messages AS m
            JOIN message_deliveries AS d
              ON d.message_id = m.id AND d.recipient_id = ?
            WHERE m.attempt_id = ? AND m.kind = 'status_request'
              AND d.runtime_session_id = ?
              AND d.state IN (
                'queued', 'leased', 'dispatched', 'delivered', 'acknowledged', 'dead'
              )
            ORDER BY m.sequence
            """,
            (actor_id, attempt_id, runtime_id),
        ).fetchall()
        for row in rows:
            updated = connection.execute(
                """
                UPDATE message_deliveries
                SET state = 'handled', delivered_at = COALESCE(delivered_at, ?),
                    acknowledged_at = COALESCE(acknowledged_at, ?),
                    handled_at = COALESCE(handled_at, ?), lease_until = NULL,
                    owner_token = '', updated_at = ?
                WHERE message_id = ? AND recipient_id = ?
                  AND runtime_session_id = ?
                  AND state IN (
                    'queued', 'leased', 'dispatched', 'delivered', 'acknowledged', 'dead'
                  )
                """,
                (now, now, now, now, row["id"], actor_id, runtime_id),
            ).rowcount
            if updated == 1:
                self._event(
                    connection,
                    "message.handled",
                    "message",
                    str(row["id"]),
                    actor_id,
                    {
                        "evidence_digest": _digest(
                            f"worker-report-incorporated-status-request:{report_kind.value}"
                        )
                    },
                    causation_id=str(row["id"]),
                )

    def request_status(
        self,
        actor: dict[str, Any],
        work_id: str,
        request: StatusRequestInput,
    ) -> dict[str, Any]:
        """Ask the active Worker for liveness without inventing a boundary."""

        self._require_role(actor, PrincipalRole.CAO)
        request_digest = _digest(
            {"work_item_id": work_id, "request": request.model_dump(mode="json")}
        )
        with self.db.transaction() as connection:
            if actor.get("_cao_attachment_id"):
                self._require_current_cao_attachment_actor_tx(connection, actor)
            work = self._require_authorized_work_tx(connection, actor, work_id)
            cached = self._idempotent_get_tx(
                connection,
                actor["id"],
                "request_status",
                request.idempotency_key,
                request_digest,
            )
            if cached is not None:
                return cached
            if int(work["generation"]) != request.expected_generation:
                raise StaleGenerationError(request.expected_generation, int(work["generation"]))
            if (
                work["state"] != WorkState.ACTIVE.value
                or work["attention_owner"] != AttentionOwner.WORKER.value
            ):
                raise ConflictError(
                    "status requests require active Worker-owned Work",
                    work_state=work["state"],
                    attention_owner=work["attention_owner"],
                )
            attempt = self._latest_attempt_tx(connection, work_id)
            if attempt is None or attempt["state"] in {
                AttemptState.COMPLETED.value,
                AttemptState.FAILED.value,
                AttemptState.CANCELED.value,
                AttemptState.SUSPENDED.value,
            }:
                raise ConflictError("status request has no active Attempt")
            try:
                connected_runtime_id = self._bind_ready_worker_runtime_tx(
                    connection,
                    worker_id=str(attempt["worker_id"]),
                    runtime_session_id=str(attempt["runtime_session_id"] or ""),
                )
                connected = connection.execute(
                    """
                    SELECT 1
                    FROM runtime_sessions AS runtime
                    JOIN worker_enrollments AS enrollment
                      ON enrollment.runtime_session_id = runtime.id
                    JOIN runtime_credentials AS credential
                      ON credential.enrollment_id = enrollment.id
                     AND credential.principal_id = enrollment.principal_id
                     AND credential.generation = enrollment.generation
                    WHERE runtime.id = ? AND runtime.principal_id = ?
                      AND runtime.state IN ('ready', 'busy')
                      AND enrollment.state = 'ready'
                      AND credential.state = 'active' AND credential.expires_at >= ?
                    LIMIT 1
                    """,
                    (connected_runtime_id, attempt["worker_id"], utc_now()),
                ).fetchone()
                if connected is None:
                    raise ConflictError("Worker execution connection is pending")
            except (ConflictError, NotFoundError, ValidationError):
                raise ConflictError(
                    "current Worker execution route is not connected for a status request",
                    reason_code="worker_status_runtime_not_connected",
                    retryable=False,
                ) from None
            response_due_at = utc_after(request.response_due_seconds)
            status_payload = {
                "action": "report_status",
                "summary": request.summary,
                "generation": request.expected_generation,
                "response_due_at": response_due_at,
            }
            _require_worker_safe_task_payload(status_payload)
            message = self._message(
                connection,
                sender_id=actor["id"],
                recipient_id=str(attempt["worker_id"]),
                kind=MessageKind.STATUS_REQUEST,
                payload=status_payload,
                work_item_id=work_id,
                attempt_id=str(attempt["id"]),
                goal_version=int(work["goal_version"]),
                idempotency_key=f"status-request:{request.idempotency_key}",
            )
            self._event(
                connection,
                "work.status_requested",
                "work_item",
                work_id,
                actor["id"],
                {
                    "message_id": message["id"],
                    "attempt_id": attempt["id"],
                    "response_due_at": response_due_at,
                },
                causation_id=str(message["id"]),
            )
            result = self._work_bundle_tx(connection, work_id)
            self._idempotent_put(
                connection,
                actor["id"],
                "request_status",
                request.idempotency_key,
                request_digest,
                result,
            )
            return result

    def _current_user_needed_boundary_tx(
        self,
        connection: sqlite3.Connection,
        *,
        actor_id: str,
        work: sqlite3.Row,
        source_attempt: sqlite3.Row,
    ) -> sqlite3.Row | None:
        """Resolve only the typed current WAIT_USER authority, never history."""

        pointer = work["user_needed_boundary_id"]
        if str(work["state"]) != WorkState.USER_NEEDED.value:
            if pointer is not None:
                raise RuntimeError("non-user-needed Work retains a WAIT_USER boundary")
            return None
        if pointer is None:
            raise ConflictError(
                "requester-input authority is unresolved",
                reason_code="worker_command_binding_ambiguous",
                retryable=False,
            )
        row = connection.execute(
            """
            SELECT boundary.*
            FROM boundaries AS boundary
            JOIN boundary_dispositions AS disposition
              ON disposition.boundary_id = boundary.id
             AND disposition.kind = 'wait_user'
            JOIN reasoner_turns AS turn
              ON turn.id = disposition.reasoner_turn_id
             AND turn.boundary_id = boundary.id
             AND turn.work_item_id = boundary.work_item_id
            LEFT JOIN boundary_supersessions AS supersession
              ON supersession.boundary_id = boundary.id
            LEFT JOIN boundary_continuations AS continuation
              ON continuation.boundary_id = boundary.id
            WHERE boundary.id = ? AND boundary.work_item_id = ?
              AND boundary.attempt_id = ? AND boundary.generation = ?
              AND boundary.goal_version = ?
              AND boundary.goal_packet_digest = ?
              AND boundary.task_packet_digest = ?
              AND boundary.source_principal_id = ?
              AND disposition.generation = boundary.generation
              AND disposition.decided_by = ?
              AND turn.supervisor_id = disposition.decided_by
              AND turn.generation = boundary.generation
              AND turn.goal_version = boundary.goal_version
              AND turn.goal_packet_digest = boundary.goal_packet_digest
              AND turn.task_packet_digest = boundary.task_packet_digest
              AND supersession.boundary_id IS NULL
              AND continuation.boundary_id IS NULL
            """,
            (
                pointer,
                work["id"],
                source_attempt["id"],
                work["generation"],
                source_attempt["goal_version"],
                source_attempt["goal_packet_digest"],
                source_attempt["task_packet_digest"],
                source_attempt["worker_id"],
                actor_id,
            ),
        ).fetchone()
        unresolved = connection.execute(
            """
            SELECT boundary.id
            FROM boundaries AS boundary
            LEFT JOIN boundary_dispositions AS disposition
              ON disposition.boundary_id = boundary.id
            LEFT JOIN boundary_supersessions AS supersession
              ON supersession.boundary_id = boundary.id
            WHERE boundary.work_item_id = ? AND boundary.generation = ?
              AND disposition.id IS NULL AND supersession.boundary_id IS NULL
            LIMIT 1
            """,
            (work["id"], work["generation"]),
        ).fetchone()
        if (
            row is None
            or unresolved is not None
            or str(work["attention_owner"]) != AttentionOwner.USER.value
        ):
            raise ConflictError(
                "requester-input continuation contract changed",
                reason_code="worker_command_binding_conflict",
                retryable=False,
            )
        return cast(sqlite3.Row, row)

    def _consume_user_needed_boundary_tx(
        self,
        connection: sqlite3.Connection,
        *,
        actor_id: str,
        work: sqlite3.Row,
        boundary: sqlite3.Row,
        source_attempt: sqlite3.Row,
        successor_attempt: sqlite3.Row,
        successor_generation: int,
        message_id: str,
        now: str,
    ) -> None:
        """Record one exact requester continuation, then clear its Work pointer."""

        connection.execute(
            """
            INSERT INTO boundary_continuations(
                boundary_id, work_item_id, source_attempt_id, source_generation,
                successor_attempt_id, successor_generation, message_id,
                decided_by, created_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                boundary["id"],
                work["id"],
                source_attempt["id"],
                work["generation"],
                successor_attempt["id"],
                successor_generation,
                message_id,
                actor_id,
                now,
            ),
        )
        updated = connection.execute(
            """
            UPDATE work_items
            SET state = 'active', attention_owner = 'worker', generation = ?,
                user_needed_boundary_id = NULL, updated_at = ?
            WHERE id = ? AND state = 'user_needed' AND attention_owner = 'user'
              AND generation = ? AND user_needed_boundary_id = ?
            """,
            (
                successor_generation,
                now,
                work["id"],
                work["generation"],
                boundary["id"],
            ),
        ).rowcount
        if updated != 1:
            raise ConflictError(
                "requester-input continuation lost its Work fence",
                reason_code="worker_command_generation_conflict",
                retryable=False,
            )

    def _reply_user_needed(
        self,
        actor: dict[str, Any],
        work_id: str,
        *,
        boundary_id: str,
        expected_generation: int,
        message_text: str,
        idempotency_key: str,
        request_digest: str,
    ) -> dict[str, Any]:
        """Resume an exact disposed WAIT_USER contract with requester input."""

        _require_worker_safe_task_payload(
            {"action": "correct", "instruction": message_text, "boundary_id": boundary_id}
        )
        with self.db.transaction() as connection:
            if actor.get("_cao_attachment_id"):
                self._require_current_cao_attachment_actor_tx(connection, actor)
            work = self._require_authorized_work_tx(connection, actor, work_id)
            cached = self._idempotent_get_tx(
                connection,
                str(actor["id"]),
                "reply",
                idempotency_key,
                request_digest,
            )
            if cached is not None:
                return cached
            attempt = self._latest_attempt_tx(connection, work_id)
            if (
                attempt is None
                or int(work["generation"]) != expected_generation
                or str(work["state"]) != WorkState.USER_NEEDED.value
                or str(work["attention_owner"]) != AttentionOwner.USER.value
                or str(attempt["state"]) != AttemptState.INPUT_REQUIRED.value
            ):
                raise ConflictError(
                    "requester-input continuation no longer owns the exact Work state",
                    reason_code="worker_command_generation_conflict",
                    retryable=False,
                )
            boundary = self._current_user_needed_boundary_tx(
                connection,
                actor_id=str(actor["id"]),
                work=work,
                source_attempt=attempt,
            )
            if boundary is None or str(boundary["id"]) != boundary_id:
                raise ConflictError(
                    "requester-input continuation contract changed",
                    reason_code="worker_command_binding_conflict",
                    retryable=False,
                )
            admission = self._admit_managed_worker_command_tx(
                connection,
                actor_id=str(actor["id"]),
                kind="correct",
                worker_id=str(attempt["worker_id"]),
                supervisor_attachment_id=(
                    str(work["supervisor_attachment_id"])
                    if work["supervisor_attachment_id"]
                    else None
                ),
                work=work,
                previous_attempt=attempt,
            )
            now = utc_now()
            target_attempt = attempt
            generation = expected_generation
            causation_id = str(attempt["id"])
            if admission is not None and admission.attempt_mode == "new_attempt":
                target_attempt = self._retry_attempt_tx(
                    connection,
                    str(actor["id"]),
                    work,
                    attempt,
                    "Requester supplied the exact WAIT_USER decision",
                    command_kind="correct",
                    admission=admission,
                    command_context={
                        "action": "correct",
                        "reason": "Requester supplied the exact WAIT_USER decision",
                        "instruction": message_text,
                        "source_boundary_id": boundary_id,
                    },
                )
                generation += 1
                causation_id = str(target_attempt["id"])
            else:
                message = self._message(
                    connection,
                    sender_id=str(actor["id"]),
                    recipient_id=str(target_attempt["worker_id"]),
                    kind=MessageKind.INSTRUCTION,
                    payload={
                        "action": "correct",
                        "reason": "Requester supplied the exact WAIT_USER decision",
                        "instruction": message_text,
                        "generation": generation,
                        "continued_from_boundary_id": boundary_id,
                    },
                    work_item_id=work_id,
                    attempt_id=str(target_attempt["id"]),
                    goal_version=int(work["goal_version"]),
                    idempotency_key=f"user-needed-reply:{boundary_id}:{_digest(idempotency_key)}",
                )
                self._consume_user_needed_boundary_tx(
                    connection,
                    actor_id=str(actor["id"]),
                    work=work,
                    boundary=boundary,
                    source_attempt=attempt,
                    successor_attempt=target_attempt,
                    successor_generation=generation,
                    message_id=str(message["id"]),
                    now=now,
                )
                connection.execute(
                    "UPDATE attempts SET state = ?, updated_at = ? WHERE id = ?",
                    (AttemptState.WORKING.value, now, attempt["id"]),
                )
                causation_id = str(message["id"])
            self._event(
                connection,
                "work.user_needed_resumed",
                "work_item",
                work_id,
                str(actor["id"]),
                {
                    "boundary_id": boundary_id,
                    "attempt_id": str(target_attempt["id"]),
                    "generation": generation,
                },
                causation_id=causation_id,
            )
            result = self._work_bundle_tx(connection, work_id)
            self._idempotent_put(
                connection,
                str(actor["id"]),
                "reply",
                idempotency_key,
                request_digest,
                result,
            )
            return result

    def _reply_open_boundary_tx(
        self,
        connection: sqlite3.Connection,
        *,
        actor: dict[str, Any],
        work: sqlite3.Row,
        boundary_id: str,
        expected_generation: int,
        message_text: str,
        turn_idempotency_key: str,
        legacy_context: bool,
    ) -> dict[str, Any]:
        """Own and CORRECT one Boundary inside the caller's transaction."""

        boundary = connection.execute(
            "SELECT * FROM boundaries WHERE id = ? AND work_item_id = ?",
            (boundary_id, work["id"]),
        ).fetchone()
        if boundary is None:
            raise NotFoundError("boundary", boundary_id)
        existing = connection.execute(
            "SELECT * FROM boundary_dispositions WHERE boundary_id = ?",
            (boundary_id,),
        ).fetchone()
        if existing is not None:
            legacy_turn = connection.execute(
                "SELECT * FROM reasoner_turns WHERE id = ? AND boundary_id = ?",
                (existing["reasoner_turn_id"], boundary_id),
            ).fetchone()
            expected_turn_input_digest = _digest(
                {
                    "boundary_id": boundary_id,
                    "boundary_input_digest": boundary["input_digest"],
                    "goal_packet_digest": boundary["goal_packet_digest"],
                    "task_packet_digest": boundary["task_packet_digest"],
                    "generation": expected_generation,
                }
            )
            expected_turn_result_digest = _digest(
                {
                    "boundary_id": boundary_id,
                    "disposition_id": existing["id"],
                    "request_digest": existing["request_digest"],
                    "goal_packet_digest": boundary["goal_packet_digest"],
                    "task_packet_digest": boundary["task_packet_digest"],
                }
            )
            disposed_events = connection.execute(
                "SELECT data_json FROM events WHERE event_type = 'boundary.disposed' "
                "AND aggregate_type = 'work_item' AND aggregate_id = ? AND actor_id = ?",
                (work["id"], actor["id"]),
            ).fetchall()
            matching_events = [
                data
                for row in disposed_events
                if isinstance((data := _load(str(row["data_json"]), None)), Mapping)
                and str(data.get("boundary_id")) == boundary_id
                and str(data.get("disposition_id")) == str(existing["id"])
                and str(data.get("kind")) == BoundaryDispositionKind.CORRECT.value
                and int(data.get("generation", 0)) == expected_generation
            ]
            if not (
                legacy_context
                and int(boundary["generation"]) == expected_generation
                and str(existing["decided_by"]) == str(actor["id"])
                and int(existing["generation"]) == expected_generation
                and str(existing["kind"]) == BoundaryDispositionKind.CORRECT.value
                and str(existing["reason"]) == "Supervisor response to a recorded boundary"
                and str(existing["instruction"]) == message_text
                and not str(existing["resume_condition"] or "")
                and bool(existing["request_digest"])
                and legacy_turn is not None
                and str(legacy_turn["state"]) == ReasonerTurnState.COMPLETED.value
                and str(legacy_turn["supervisor_id"]) == str(actor["id"])
                and str(legacy_turn["work_item_id"]) == str(work["id"])
                and int(legacy_turn["generation"]) == expected_generation
                and str(legacy_turn["goal_version"]) == str(boundary["goal_version"])
                and str(legacy_turn["goal_packet_digest"]) == str(boundary["goal_packet_digest"])
                and str(legacy_turn["task_packet_digest"]) == str(boundary["task_packet_digest"])
                and str(legacy_turn["input_digest"]) == expected_turn_input_digest
                and str(legacy_turn["result_digest"]) == expected_turn_result_digest
                and len(matching_events) == 1
            ):
                raise ConflictError(
                    "boundary was already disposed differently",
                    disposition_id=existing["id"],
                )
            return self._work_bundle_tx(connection, str(work["id"]))

        active_turn = connection.execute(
            "SELECT * FROM reasoner_turns "
            "WHERE supervisor_id = ? AND work_item_id = ? AND state = ?",
            (actor["id"], work["id"], ReasonerTurnState.LEASED.value),
        ).fetchone()
        legacy_lease_token: str | None = None
        if active_turn is not None and legacy_context:
            acquire_digest = _digest(
                {
                    "work_item_id": str(work["id"]),
                    "boundary_id": boundary_id,
                    "expected_generation": expected_generation,
                    "lease_seconds": 180,
                }
            )
            receipt_row = connection.execute(
                "SELECT request_digest, result_json FROM idempotency_results "
                "WHERE actor_id = ? AND operation = 'acquire_reasoner_turn' "
                "AND idempotency_key = ?",
                (actor["id"], turn_idempotency_key),
            ).fetchone()
            receipt = (
                _load(str(receipt_row["result_json"]), None) if receipt_row is not None else None
            )
            if not (
                receipt_row is not None
                and str(receipt_row["request_digest"]) == acquire_digest
                and isinstance(receipt, Mapping)
                and str(receipt.get("id")) == str(active_turn["id"])
                and str(receipt.get("supervisor_id")) == str(actor["id"])
                and str(receipt.get("work_item_id")) == str(work["id"])
                and str(receipt.get("boundary_id")) == boundary_id
                and int(receipt.get("generation", 0)) == expected_generation
                and str(receipt.get("goal_packet_digest")) == str(boundary["goal_packet_digest"])
                and str(receipt.get("task_packet_digest")) == str(boundary["task_packet_digest"])
                and str(receipt.get("input_digest")) == str(active_turn["input_digest"])
                and str(receipt.get("state")) == ReasonerTurnState.LEASED.value
                and isinstance(receipt.get("lease_token"), str)
                and bool(receipt.get("lease_token"))
                and str(receipt.get("lease_expires_at")) == str(active_turn["lease_expires_at"])
                and secrets.compare_digest(
                    str(active_turn["lease_token_digest"]),
                    _digest(str(receipt.get("lease_token"))),
                )
            ):
                raise ConflictError(
                    "legacy reply turn provenance is invalid",
                    reason_code="reply_turn_provenance_conflict",
                    retryable=False,
                )
            if not _is_expired(active_turn["lease_expires_at"]):
                legacy_lease_token = str(receipt["lease_token"])
        elif active_turn is not None and not _is_expired(active_turn["lease_expires_at"]):
            raise ConflictError(
                "the work item already has an active reasoner turn",
                turn_id=active_turn["id"],
                work_item_id=active_turn["work_item_id"],
            )
        now = utc_now()
        if active_turn is not None and legacy_lease_token is None:
            connection.execute(
                "UPDATE reasoner_turns SET state = ?, updated_at = ? WHERE id = ?",
                (ReasonerTurnState.ABANDONED.value, now, active_turn["id"]),
            )
        turn_id = str(active_turn["id"]) if legacy_lease_token is not None else _id("turn")
        lease_token = legacy_lease_token or secrets.token_urlsafe(32)
        stored_turn_idempotency_key = (
            f"reply-resume:{active_turn['id']}"
            if active_turn is not None and legacy_lease_token is None
            else turn_idempotency_key
        )
        turn_input_digest = _digest(
            {
                "boundary_id": boundary_id,
                "boundary_input_digest": boundary["input_digest"],
                "goal_packet_digest": boundary["goal_packet_digest"],
                "task_packet_digest": boundary["task_packet_digest"],
                "generation": expected_generation,
            }
        )
        if legacy_lease_token is None:
            connection.execute(
                """
                INSERT INTO reasoner_turns(
                    id, supervisor_id, work_item_id, boundary_id, generation,
                    goal_version, goal_packet_digest, task_packet_digest,
                    input_digest, result_digest, state, lease_token_digest,
                    lease_expires_at, idempotency_key, created_at, updated_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, '', 'leased', ?, ?, ?, ?, ?)
                """,
                (
                    turn_id,
                    actor["id"],
                    work["id"],
                    boundary_id,
                    expected_generation,
                    boundary["goal_version"],
                    boundary["goal_packet_digest"],
                    boundary["task_packet_digest"],
                    turn_input_digest,
                    _digest(lease_token),
                    utc_after(180),
                    stored_turn_idempotency_key,
                    now,
                    now,
                ),
            )
            self._event(
                connection,
                "reasoner.turn_acquired",
                "work_item",
                str(work["id"]),
                str(actor["id"]),
                {
                    "turn_id": turn_id,
                    "boundary_id": boundary_id,
                    "generation": expected_generation,
                },
            )
        self._dispose_boundary_tx(
            connection,
            actor,
            boundary_id,
            BoundaryDispositionInput(
                turn_id=turn_id,
                lease_token=lease_token,
                expected_generation=expected_generation,
                kind=BoundaryDispositionKind.CORRECT,
                reason="Supervisor response to a recorded boundary",
                instruction=message_text,
            ),
            expected_work_item_id=str(work["id"]),
        )
        return self._work_bundle_tx(connection, str(work["id"]))

    def reply(
        self,
        actor: dict[str, Any],
        work_id: str,
        message_text: str,
        *,
        in_reply_to: str | None = None,
        idempotency_key: str = "",
    ) -> dict[str, Any]:
        """Atomically answer one exact Boundary with a fenced CORRECT command."""

        self._require_role(actor, PrincipalRole.CAO)
        message_text = message_text.strip()
        request_digest = _digest(
            {
                "work_item_id": work_id,
                "message": message_text,
                "in_reply_to": in_reply_to,
            }
        )
        if not message_text:
            raise ValidationError("reply message is required")
        _require_worker_safe_task_payload({"action": "correct", "instruction": message_text})
        context_key = (
            f"provided:{idempotency_key}" if idempotency_key else f"implicit:{request_digest}"
        )
        user_needed: tuple[str, int] | None = None
        with self.db.transaction() as connection:
            if actor.get("_cao_attachment_id"):
                self._require_current_cao_attachment_actor_tx(connection, actor)
            work = connection.execute(
                "SELECT * FROM work_items WHERE id = ?", (work_id,)
            ).fetchone()
            if work is None:
                raise NotFoundError("work item", work_id)
            self._authorize_work_actor(actor, work)
            cached = self._idempotent_get_tx(
                connection,
                actor["id"],
                "reply",
                idempotency_key,
                request_digest,
            )
            if cached is not None:
                return cached
            require_not_paused(work)
            attempt = self._latest_attempt_tx(connection, work_id)
            if attempt is None:
                raise ConflictError("work item has no attempt")
            # Read an old split-facade selection receipt only as compatibility
            # evidence. New replies never create this intermediate receipt.
            context = self._idempotent_get_tx(
                connection,
                actor["id"],
                "reply_context",
                context_key,
                request_digest,
            )
            legacy_context = context is not None
            if context is None:
                boundary_id: str | None = None
                context_kind = "boundary"
                if in_reply_to:
                    replied_message = connection.execute(
                        "SELECT * FROM messages WHERE id = ? AND work_item_id = ?",
                        (in_reply_to, work_id),
                    ).fetchone()
                    if replied_message is None:
                        raise NotFoundError("message", in_reply_to)
                    boundary_id = _load(replied_message["payload_json"], {}).get("boundary_id")
                if str(work["state"]) == WorkState.USER_NEEDED.value:
                    if str(attempt["state"]) != AttemptState.INPUT_REQUIRED.value:
                        raise ConflictError(
                            "requester-input continuation no longer owns the exact Work state",
                            reason_code="worker_command_generation_conflict",
                            retryable=False,
                        )
                    current_wait = self._current_user_needed_boundary_tx(
                        connection,
                        actor_id=str(actor["id"]),
                        work=work,
                        source_attempt=attempt,
                    )
                    assert current_wait is not None
                    current_boundary_id = str(current_wait["id"])
                    if boundary_id and str(boundary_id) != current_boundary_id:
                        raise ConflictError(
                            "reply target is not the current requester-input boundary",
                            reason_code="worker_command_binding_conflict",
                            retryable=False,
                        )
                    boundary_id = current_boundary_id
                    context_kind = "user_needed"
                elif not boundary_id:
                    unresolved = connection.execute(
                        """
                        SELECT b.id
                        FROM boundaries AS b
                        LEFT JOIN boundary_dispositions AS d ON d.boundary_id = b.id
                        LEFT JOIN boundary_supersessions AS s ON s.boundary_id = b.id
                        WHERE b.work_item_id = ? AND d.id IS NULL
                          AND s.boundary_id IS NULL
                        ORDER BY b.created_at DESC
                        LIMIT 1
                        """,
                        (work_id,),
                    ).fetchone()
                    boundary_id = str(unresolved["id"]) if unresolved is not None else None
                if not boundary_id:
                    raise ConflictError(
                        "work item has no unresolved boundary to answer",
                        reason_code="worker_command_generation_conflict",
                        retryable=False,
                    )
                context = {
                    "work_item_id": work_id,
                    "boundary_id": boundary_id,
                    "generation": int(work["generation"]),
                    "kind": context_kind,
                }
            if (
                context.get("work_item_id") != work_id
                or not context.get("boundary_id")
                or isinstance(context.get("generation"), bool)
                or not isinstance(context.get("generation"), int)
            ):
                raise RuntimeError("reply context receipt is invalid")
            boundary_id = str(context["boundary_id"])
            generation = int(context["generation"])
            if context.get("kind") == "user_needed":
                user_needed = (boundary_id, generation)
            else:
                result = self._reply_open_boundary_tx(
                    connection,
                    actor=actor,
                    work=work,
                    boundary_id=boundary_id,
                    expected_generation=generation,
                    message_text=message_text,
                    turn_idempotency_key=(
                        f"reply:{idempotency_key}"
                        if idempotency_key
                        else f"reply:{boundary_id}:{_digest(message_text)}"
                    ),
                    legacy_context=legacy_context,
                )
                self._idempotent_put(
                    connection,
                    str(actor["id"]),
                    "reply",
                    idempotency_key,
                    request_digest,
                    result,
                )
                return result

        assert user_needed is not None
        return self._reply_user_needed(
            actor,
            work_id,
            boundary_id=user_needed[0],
            expected_generation=user_needed[1],
            message_text=message_text,
            idempotency_key=idempotency_key,
            request_digest=request_digest,
        )

    def review(self, actor: dict[str, Any], request: ReviewInput) -> dict[str, Any]:
        self._require_role(actor, PrincipalRole.CAO)

        request_digest = _digest(request.model_dump(mode="json"))
        with self.db.transaction() as connection:
            if actor.get("_cao_attachment_id"):
                self._require_current_cao_attachment_actor_tx(connection, actor)
            attempt = connection.execute(
                "SELECT * FROM attempts WHERE id = ?", (request.attempt_id,)
            ).fetchone()
            if attempt is None:
                raise NotFoundError("attempt", request.attempt_id)
            work = self._require_authorized_work_tx(connection, actor, str(attempt["work_item_id"]))
            if work["supervisor_attachment_id"]:
                attachment_id = str(actor.get("_cao_attachment_id") or "")
                if attachment_id != str(work["supervisor_attachment_id"]):
                    raise AuthorizationError(
                        "attached Work must be reviewed from its originating CAO conversation"
                    )
            cached = self._idempotent_get_tx(
                connection,
                actor["id"],
                "review",
                request.idempotency_key,
                request_digest,
            )
            if cached is not None:
                return cached
            if request.verdict not in {
                ReviewVerdict.OK,
                ReviewVerdict.NEEDS_WORK,
            }:
                raise ValidationError("CAO review verdict must be ok or needs_work")
            open_completion_boundary = connection.execute(
                """
                SELECT b.* FROM boundaries AS b
                LEFT JOIN boundary_dispositions AS d ON d.boundary_id = b.id
                LEFT JOIN boundary_supersessions AS s ON s.boundary_id = b.id
                WHERE b.attempt_id = ? AND b.work_item_id = ?
                  AND b.kind IN ('completion', 'worker_output') AND b.generation = ?
                  AND d.id IS NULL
                  AND s.boundary_id IS NULL
                ORDER BY b.created_at DESC, b.id DESC LIMIT 1
                """,
                (attempt["id"], work["id"], work["generation"]),
            ).fetchone()
            reviews_open_boundary = bool(
                open_completion_boundary is not None
                and work["state"] == WorkState.WAITING_SUPERVISOR.value
                and attempt["state"] == AttemptState.WAITING_SUPERVISOR.value
            )
            reviews_submitted_claim = bool(
                work["state"] == WorkState.WAITING_REVIEW.value
                and attempt["state"] == AttemptState.SUBMITTED.value
            )
            if not reviews_open_boundary and not reviews_submitted_claim:
                raise ConflictError(
                    "CAO review requires an unresolved Worker output or completion claim",
                    work_state=work["state"],
                    attempt_state=attempt["state"],
                )
            goal = self._current_goal_tx(connection, work)
            if (
                int(attempt["goal_version"]) != int(work["goal_version"])
                or str(attempt["goal_packet_digest"]) != str(goal["packet_digest"])
                or not attempt["task_packet_digest"]
            ):
                raise ConflictError("review targets a stale or partial task packet")
            if request.verdict == ReviewVerdict.OK:
                if (
                    open_completion_boundary is not None
                    and open_completion_boundary["kind"] == BoundaryKind.WORKER_OUTPUT.value
                ):
                    captured = require_reviewable_output_tx(
                        self,
                        connection,
                        actor=actor,
                        boundary=open_completion_boundary,
                    )
                    # Only CAO's explicit successful review creates this
                    # completion evidence. Provider capture alone never claims
                    # acceptance, mutates trajectory, or fabricates artifacts.
                    completion_claim = {
                        "source": "cao_reviewed_worker_output",
                        "output_id": str(captured["id"]),
                        "summary": request.summary,
                        "evidence": request.evidence,
                        "artifacts": _load(str(captured["artifact_manifest_json"]), []),
                        "artifact_manifest_scope": "verified_attempt_artifacts_v2",
                        "goal_packet_digest": str(attempt["goal_packet_digest"]),
                        "task_packet_digest": str(attempt["task_packet_digest"]),
                        "claimed_at": utc_now(),
                    }
                    connection.execute(
                        "UPDATE attempts SET completion_claim_json = ? WHERE id = ?",
                        (_json(completion_claim), attempt["id"]),
                    )
                    attempt = connection.execute(
                        "SELECT * FROM attempts WHERE id = ?", (attempt["id"],)
                    ).fetchone()
                    assert attempt is not None
                self._require_completion_delivery_ready_tx(connection, work, attempt)
            if reviews_open_boundary:
                assert open_completion_boundary is not None
                prior_boundary_review = connection.execute(
                    "SELECT id, verdict FROM reviews WHERE boundary_id = ?",
                    (open_completion_boundary["id"],),
                ).fetchone()
                if prior_boundary_review is not None:
                    raise ConflictError(
                        "completion boundary already has a CAO review",
                        review_id=prior_boundary_review["id"],
                        verdict=prior_boundary_review["verdict"],
                    )
            review_id = _id("rev")
            now = utc_now()
            connection.execute(
                """
                INSERT INTO reviews(
                    id, work_item_id, attempt_id, boundary_id,
                    reviewer_id, reviewer_role,
                    supervisor_attachment_id, supervisor_attachment_generation,
                    work_generation,
                    goal_version, goal_packet_digest, task_packet_digest,
                    verdict, summary, evidence_json, created_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    review_id,
                    work["id"],
                    attempt["id"],
                    (
                        str(open_completion_boundary["id"])
                        if reviews_open_boundary and open_completion_boundary is not None
                        else None
                    ),
                    actor["id"],
                    actor["role"],
                    actor.get("_cao_attachment_id"),
                    actor.get("_cao_attachment_generation"),
                    work["generation"],
                    attempt["goal_version"],
                    attempt["goal_packet_digest"],
                    attempt["task_packet_digest"],
                    request.verdict.value,
                    request.summary,
                    _json(request.evidence),
                    now,
                ),
            )
            if reviews_open_boundary:
                assert open_completion_boundary is not None
                self._event(
                    connection,
                    "work.reviewed",
                    "work_item",
                    str(work["id"]),
                    actor["id"],
                    {
                        "review_id": review_id,
                        "verdict": request.verdict.value,
                        "boundary_id": str(open_completion_boundary["id"]),
                        "awaiting_disposition": True,
                    },
                    causation_id=str(open_completion_boundary["id"]),
                )
                result = self._work_bundle_tx(connection, str(work["id"]))
                self._idempotent_put(
                    connection,
                    actor["id"],
                    "review",
                    request.idempotency_key,
                    request_digest,
                    result,
                )
                return result
            recipient_id = attempt["worker_id"]
            boundary: dict[str, Any] | None = None
            if request.verdict == ReviewVerdict.OK:
                connection.execute(
                    "UPDATE attempts SET state = ?, evidence_confidence = ?, updated_at = ? WHERE id = ?",
                    (
                        AttemptState.COMPLETED.value,
                        EvidenceConfidence.VERIFIED.value,
                        now,
                        attempt["id"],
                    ),
                )
                connection.execute(
                    "UPDATE work_items SET state = ?, attention_owner = ?, updated_at = ? WHERE id = ?",
                    (
                        WorkState.WAITING_USER.value,
                        AttentionOwner.USER.value,
                        now,
                        work["id"],
                    ),
                )
                recipient_id = (
                    work["supervisor_id"]
                    if work["supervisor_attachment_id"]
                    else (work["requester_id"] or work["supervisor_id"])
                )
            elif request.verdict == ReviewVerdict.NEEDS_WORK:
                connection.execute(
                    "UPDATE attempts SET state = ?, trajectory = ?, updated_at = ? WHERE id = ?",
                    (
                        AttemptState.WAITING_SUPERVISOR.value,
                        Trajectory.AT_RISK.value,
                        now,
                        attempt["id"],
                    ),
                )
                connection.execute(
                    "UPDATE work_items SET state = ?, attention_owner = ?, updated_at = ? WHERE id = ?",
                    (
                        WorkState.WAITING_SUPERVISOR.value,
                        AttentionOwner.CAO.value,
                        now,
                        work["id"],
                    ),
                )
                recipient_id = work["supervisor_id"] or work["created_by"]
                boundary = self._record_boundary_tx(
                    connection,
                    actor=actor,
                    request=BoundaryInput(
                        source_event_id=f"review:{review_id}:needs-work",
                        work_item_id=str(work["id"]),
                        attempt_id=str(attempt["id"]),
                        expected_goal_version=int(work["goal_version"]),
                        expected_goal_packet_digest=str(attempt["goal_packet_digest"]),
                        expected_task_packet_digest=str(attempt["task_packet_digest"]),
                        expected_generation=int(work["generation"]),
                        kind=BoundaryKind.REVIEW_REJECTED,
                        summary=request.summary,
                        runtime_state=RuntimeState.WAITING,
                        metadata={
                            "review_id": review_id,
                            "evidence": request.evidence,
                        },
                    ),
                )
            msg = self._message(
                connection,
                sender_id=actor["id"],
                recipient_id=recipient_id,
                kind=MessageKind.REVIEW,
                payload={
                    "review_id": review_id,
                    "verdict": request.verdict.value,
                    "summary": request.summary,
                    "evidence": request.evidence,
                    "boundary_id": boundary["id"] if boundary else None,
                },
                work_item_id=work["id"],
                attempt_id=attempt["id"],
                goal_version=work["goal_version"],
                idempotency_key=(
                    f"review:{request.idempotency_key}" if request.idempotency_key else ""
                ),
            )
            self._event(
                connection,
                "work.reviewed",
                "work_item",
                work["id"],
                actor["id"],
                {"review_id": review_id, "verdict": request.verdict.value},
                causation_id=msg["id"],
            )
            result = self._work_bundle_tx(connection, work["id"])
            self._idempotent_put(
                connection,
                actor["id"],
                "review",
                request.idempotency_key,
                request_digest,
                result,
            )
        return result

    def record_requester_decision(
        self,
        actor: dict[str, Any],
        request: RequesterDecisionInput,
    ) -> dict[str, Any]:
        """Record a requester decision observed in this exact CAO conversation."""

        self._require_role(actor, PrincipalRole.CAO)
        attachment_id = str(actor.get("_cao_attachment_id") or "")
        attachment_generation = actor.get("_cao_attachment_generation")
        if not attachment_id or attachment_generation is None:
            raise AuthorizationError("requester decisions require an attached CAO conversation")
        request_payload = request.model_dump(mode="json", exclude_none=True)
        if contains_control_plane_secret(request_payload):
            raise ValidationError("requester decision contains a credential-like secret")
        operation = f"requester_decision:{attachment_id}"

        with self.db.transaction() as connection:
            self._require_current_cao_attachment_actor_tx(connection, actor)
            review = connection.execute(
                "SELECT * FROM reviews WHERE id = ?", (request.review_id,)
            ).fetchone()
            if review is None:
                raise NotFoundError("review", request.review_id)
            work = connection.execute(
                "SELECT * FROM work_items WHERE id = ?", (review["work_item_id"],)
            ).fetchone()
            attempt = connection.execute(
                "SELECT * FROM attempts WHERE id = ?", (review["attempt_id"],)
            ).fetchone()
            assert work is not None and attempt is not None
            self._authorize_work_actor(actor, work)
            requester_id = str(work["requester_id"] or "")
            requester = (
                connection.execute(
                    "SELECT id, role FROM principals WHERE id = ?",
                    (requester_id,),
                ).fetchone()
                if requester_id
                else None
            )
            if (
                requester is None
                or str(requester["id"]) != requester_id
                or str(requester["role"]) != PrincipalRole.USER.value
            ):
                raise ConflictError("review-bound WorkItem requester authority is unavailable")
            if (
                str(review["supervisor_attachment_id"] or "") != attachment_id
                or review["supervisor_attachment_generation"] is None
                or int(review["supervisor_attachment_generation"]) > int(attachment_generation)
            ):
                raise AuthorizationError("review belongs to another CAO conversation generation")
            request_digest = _digest(
                {
                    "attachment_id": attachment_id,
                    "request": request_payload,
                }
            )
            cached = self._idempotent_get_tx(
                connection,
                actor["id"],
                operation,
                request.idempotency_key,
                request_digest,
            )
            if cached is not None:
                return cached
            if review["verdict"] != ReviewVerdict.OK.value:
                raise ConflictError("requester decision requires an OK CAO review")
            goal = self._current_goal_tx(connection, work)
            if (
                str(review["attempt_id"]) != str(attempt["id"])
                or int(review["goal_version"]) != int(work["goal_version"])
                or str(review["goal_packet_digest"]) != str(attempt["goal_packet_digest"])
                or str(review["task_packet_digest"]) != str(attempt["task_packet_digest"])
                or str(goal["packet_digest"]) != str(attempt["goal_packet_digest"])
            ):
                raise ConflictError("requester decision targets a stale review packet")
            if (
                work["state"] != WorkState.WAITING_USER.value
                or attempt["state"] != AttemptState.COMPLETED.value
                or attempt["evidence_confidence"] != EvidenceConfidence.VERIFIED.value
            ):
                raise ConflictError(
                    "requester decision requires a verified result awaiting its requester",
                    work_state=work["state"],
                    attempt_state=attempt["state"],
                )
            if request.verdict == "accepted":
                self._require_completion_delivery_ready_tx(connection, work, attempt)
            existing = connection.execute(
                "SELECT * FROM requester_decisions WHERE review_id = ?",
                (review["id"],),
            ).fetchone()
            if existing is not None:
                if existing["request_digest"] != request_digest:
                    raise ConflictError("CAO review already has a different requester decision")
                return self._work_bundle_tx(connection, str(work["id"]))

            decision_id = _id("rdec")
            now = utc_now()
            final_generation = int(work["generation"])
            boundary: dict[str, Any] | None = None
            if request.verdict == "accepted":
                final_generation += 1
                self._fence_reasoner_turns_tx(connection, str(work["id"]))
                connection.execute(
                    "UPDATE work_items SET state = ?, attention_owner = ?, "
                    "generation = ?, updated_at = ? WHERE id = ?",
                    (
                        WorkState.COMPLETED.value,
                        AttentionOwner.NONE.value,
                        final_generation,
                        now,
                        work["id"],
                    ),
                )
            else:
                connection.execute(
                    "UPDATE attempts SET state = ?, updated_at = ? WHERE id = ?",
                    (AttemptState.WAITING_SUPERVISOR.value, now, attempt["id"]),
                )
                connection.execute(
                    "UPDATE work_items SET state = ?, attention_owner = ?, updated_at = ? "
                    "WHERE id = ?",
                    (
                        WorkState.WAITING_SUPERVISOR.value,
                        AttentionOwner.CAO.value,
                        now,
                        work["id"],
                    ),
                )
                boundary = self._record_boundary_tx(
                    connection,
                    actor=actor,
                    request=BoundaryInput(
                        source_event_id=f"requester-decision:{decision_id}:rejected",
                        work_item_id=str(work["id"]),
                        attempt_id=str(attempt["id"]),
                        expected_goal_version=int(work["goal_version"]),
                        expected_goal_packet_digest=str(attempt["goal_packet_digest"]),
                        expected_task_packet_digest=str(attempt["task_packet_digest"]),
                        expected_generation=int(work["generation"]),
                        kind=BoundaryKind.USER_REJECTION,
                        summary=request.summary,
                        runtime_state=RuntimeState.WAITING,
                        metadata={
                            "requester_decision_id": decision_id,
                            "review_id": str(review["id"]),
                        },
                    ),
                )
            connection.execute(
                """
                INSERT INTO requester_decisions(
                    id, work_item_id, attempt_id, review_id, requester_id,
                    recorded_by, supervisor_attachment_id,
                    supervisor_attachment_generation, goal_version,
                    goal_packet_digest, task_packet_digest, work_generation,
                    verdict, summary, evidence_json, conversation_evidence_id,
                    request_digest, created_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    decision_id,
                    work["id"],
                    attempt["id"],
                    review["id"],
                    requester_id,
                    actor["id"],
                    attachment_id,
                    int(attachment_generation),
                    attempt["goal_version"],
                    attempt["goal_packet_digest"],
                    attempt["task_packet_digest"],
                    final_generation,
                    request.verdict,
                    request.summary,
                    _json(request.evidence),
                    request.conversation_evidence_id,
                    request_digest,
                    now,
                ),
            )
            connection.execute(
                """
                UPDATE message_deliveries
                SET state = 'handled', delivered_at = COALESCE(delivered_at, ?),
                    acknowledged_at = COALESCE(acknowledged_at, ?),
                    handled_at = COALESCE(handled_at, ?), lease_until = NULL,
                    owner_token = '', updated_at = ?
                WHERE recipient_id = ? AND recipient_attachment_id = ?
                  AND state IN ('queued', 'leased', 'dispatched', 'delivered', 'acknowledged')
                  AND message_id IN (
                      SELECT id FROM messages
                      WHERE work_item_id = ? AND kind = 'review'
                        AND json_extract(payload_json, '$.review_id') = ?
                  )
                """,
                (
                    now,
                    now,
                    now,
                    now,
                    actor["id"],
                    attachment_id,
                    work["id"],
                    review["id"],
                ),
            )
            self._event(
                connection,
                "work.requester_decision_recorded",
                "work_item",
                str(work["id"]),
                actor["id"],
                {
                    "requester_decision_id": decision_id,
                    "review_id": str(review["id"]),
                    "verdict": request.verdict,
                    "attachment_generation": int(attachment_generation),
                    "boundary_id": boundary["id"] if boundary else None,
                },
            )
            if request.verdict == "accepted":
                self._resume_interrupted_target_tx(connection, str(work["id"]), actor["id"])
            result = self._work_bundle_tx(connection, str(work["id"]))
            self._idempotent_put(
                connection,
                actor["id"],
                operation,
                request.idempotency_key,
                request_digest,
                result,
            )
            return result

    def close_work(
        self,
        actor: dict[str, Any],
        request: WorkCloseInput,
    ) -> dict[str, Any]:
        """Record an effect-free explicit close receipt for one exact generation."""

        self._require_role(actor, PrincipalRole.CAO)
        attachment_id = str(actor.get("_cao_attachment_id") or "")
        attachment_generation = actor.get("_cao_attachment_generation")
        if not attachment_id or attachment_generation is None:
            raise AuthorizationError("close requires an attached CAO conversation")
        request_payload = request.model_dump(mode="json")
        if contains_control_plane_secret(request_payload):
            raise ValidationError("close plan contains a credential-like secret")
        operation = f"close_work:{attachment_id}"
        request_digest = _digest(
            {
                "attachment_id": attachment_id,
                "request": request_payload,
            }
        )
        with self.db.transaction() as connection:
            self._require_current_cao_attachment_actor_tx(
                connection, actor, allow_runtime_credential=False
            )
            work = self._require_authorized_work_tx(connection, actor, request.work_item_id)
            cached = self._idempotent_get_tx(
                connection,
                actor["id"],
                operation,
                request.idempotency_key,
                request_digest,
            )
            if cached is not None:
                return cached
            attempt = connection.execute(
                "SELECT * FROM attempts WHERE id = ? AND work_item_id = ?",
                (request.attempt_id, work["id"]),
            ).fetchone()
            review = connection.execute(
                "SELECT * FROM reviews WHERE id = ? AND work_item_id = ?",
                (request.review_id, work["id"]),
            ).fetchone()
            decision = connection.execute(
                "SELECT * FROM requester_decisions WHERE id = ? AND work_item_id = ?",
                (request.requester_decision_id, work["id"]),
            ).fetchone()
            if attempt is None or review is None or decision is None:
                raise ConflictError("close references do not belong to the same WorkItem")
            if (
                str(review["attempt_id"]) != str(attempt["id"])
                or str(decision["attempt_id"]) != str(attempt["id"])
                or str(decision["review_id"]) != str(review["id"])
                or str(decision["supervisor_attachment_id"]) != attachment_id
                or int(decision["supervisor_attachment_generation"]) > int(attachment_generation)
            ):
                raise ConflictError("close references cross a packet or conversation boundary")
            existing = connection.execute(
                "SELECT * FROM work_close_receipts WHERE work_item_id = ?",
                (work["id"],),
            ).fetchone()
            if existing is not None:
                if existing["request_digest"] != request_digest:
                    raise ConflictError("WorkItem was already closed with another plan")
                return self._work_bundle_tx(connection, str(work["id"]))

            preparation = connection.execute(
                "SELECT * FROM work_close_preparations WHERE id = ? AND work_item_id = ?",
                (request.close_preparation_id, work["id"]),
            ).fetchone()
            if preparation is None:
                raise ConflictError(
                    "close must reference a server-created preparation for this WorkItem"
                )
            if (
                str(preparation["final_attempt_id"]) != str(attempt["id"])
                or int(preparation["work_generation"]) != int(work["generation"])
                or int(preparation["goal_version"]) != int(work["goal_version"])
                or str(preparation["goal_packet_digest"]) != str(attempt["goal_packet_digest"])
                or str(preparation["task_packet_digest"]) != str(attempt["task_packet_digest"])
                or str(preparation["supervisor_attachment_id"] or "") != attachment_id
                or int(preparation["supervisor_attachment_generation"] or 0)
                > int(attachment_generation)
                or int(decision["supervisor_attachment_generation"])
                > int(preparation["supervisor_attachment_generation"] or 0)
                or request.retention_policy_evidence_id
                != str(preparation["retention_policy_evidence_id"])
                or request.artifact_manifest_evidence_id
                != str(preparation["artifact_manifest_evidence_id"])
                or request.cleanup_inventory_evidence_id != str(preparation["id"])
            ):
                raise ConflictError(
                    "close preparation is stale or does not match the exact close contract"
                )
            prepared_artifacts = _load(str(preparation["artifacts_json"]), None)
            prepared_inventory = _load(str(preparation["inventory_json"]), None)
            if (
                not isinstance(prepared_artifacts, list)
                or not isinstance(prepared_inventory, list)
                or _digest(prepared_inventory) != str(preparation["inventory_digest"])
            ):
                raise ConflictError("stored close preparation is malformed")
            if request.cleanup:
                raise ConflictError(
                    "cleanup outcomes are server-derived; caller cleanup attestation is not accepted"
                )
            required_coverage = {
                CleanupTargetKind.WORKSPACE.value,
                CleanupTargetKind.TEMPORARY.value,
                CleanupTargetKind.LOG.value,
                CleanupTargetKind.BRANCH.value,
            }
            provider_inventory = [
                dict(item)
                for item in prepared_inventory
                if isinstance(item, Mapping) and "coverage" in item
            ]
            provider_coverage = {
                str(item.get("target_kind"))
                for item in provider_inventory
                if str(item.get("coverage")) in {"enumerated", "not-applicable"}
            }
            if (
                provider_coverage != required_coverage
                or not self.owner_private_close_inventory.verify_public_inventory(
                    preparation_id=str(preparation["id"]),
                    work_item_id=str(work["id"]),
                    generation=int(work["generation"]),
                    attachment_id=attachment_id,
                    public_inventory=provider_inventory,
                )
            ):
                raise ConflictError(
                    "cleanup inventory has missing, stale, or untrusted category coverage"
                )

            artifacts = connection.execute(
                "SELECT id, digest FROM artifacts WHERE work_item_id = ? ORDER BY id",
                (work["id"],),
            ).fetchall()
            legacy_artifact_digests = {str(row["id"]): str(row["digest"]) for row in artifacts}
            manifest_scope = str(preparation["artifact_manifest_scope"])
            if manifest_scope == "final_completion_claim_v2":
                self._require_completion_delivery_ready_tx(
                    connection,
                    work,
                    attempt,
                )
                claimed_artifact_rows = self._completion_claim_artifact_rows_tx(connection, attempt)
                if claimed_artifact_rows is None:
                    raise ConflictError("final completion artifact manifest is invalid")
                required_artifact_digests = {
                    str(row["id"]): str(row["digest"]) for row in claimed_artifact_rows
                }
            elif manifest_scope == "work_history_v1":
                required_artifact_digests = legacy_artifact_digests
            else:
                raise ConflictError("stored close preparation is malformed")
            prepared_artifact_digests = {
                str(item.get("id")): str(item.get("digest"))
                for item in prepared_artifacts
                if isinstance(item, Mapping)
                and set(item) == {"id", "digest"}
                and isinstance(item.get("id"), str)
                and isinstance(item.get("digest"), str)
            }
            requested_artifact_digests = {
                item.artifact_id: item.digest for item in request.artifacts
            }
            if (
                len(prepared_artifact_digests) != len(prepared_artifacts)
                or len(requested_artifact_digests) != len(request.artifacts)
                or prepared_artifact_digests != required_artifact_digests
                or requested_artifact_digests != prepared_artifact_digests
            ):
                raise ConflictError(
                    "artifact preservation evidence does not match the canonical artifact set"
                )
            effective_artifact_rows = [item.model_dump(mode="json") for item in request.artifacts]
            external_cleanup = [
                item
                for item in prepared_inventory
                if isinstance(item, Mapping)
                and item.get("coverage") == "enumerated"
                and str(item.get("target_kind")) in {"workspace", "temporary", "log", "branch"}
            ]
            if external_cleanup:
                preserved_artifacts = _load(
                    str(preparation["artifact_preservations_json"] or "[]"), None
                )
                if (
                    not preparation["cleanup_executed_at"]
                    or not isinstance(preserved_artifacts, list)
                    or _digest(preserved_artifacts)
                    != str(preparation["artifact_preservations_digest"])
                    or not self.owner_private_artifact_preservation.verify_public_receipt_set(
                        work_item_id=str(work["id"]),
                        preparation_id=str(preparation["id"]),
                        attachment_id=attachment_id,
                        attachment_generation=int(preparation["supervisor_attachment_generation"]),
                        public_receipts=preserved_artifacts,
                    )
                ):
                    raise ConflictError(
                        "destructive cleanup requires exact artifact preservation evidence sealed before execution"
                    )
                effective_artifact_rows = [
                    {
                        "artifact_id": str(item.get("artifact_id")),
                        "digest": str(item.get("digest")),
                        "evidence_id": str(item.get("provider_evidence_id")),
                    }
                    for item in preserved_artifacts
                    if isinstance(item, Mapping)
                ]
                if effective_artifact_rows != [
                    item.model_dump(mode="json") for item in request.artifacts
                ]:
                    raise ConflictError(
                        "close must use the exact owner-private artifact preservation receipts"
                    )
            open_deliveries = connection.execute(
                """
                SELECT COUNT(*) AS count
                FROM message_deliveries AS d
                JOIN messages AS m ON m.id = d.message_id
                WHERE m.work_item_id = ?
                  AND d.state IN ('queued', 'leased', 'dispatched', 'delivered', 'acknowledged')
                """,
                (work["id"],),
            ).fetchone()
            expected_cleanup = {
                (
                    str(item.get("target_kind")),
                    str(item.get("target_fingerprint")),
                    str(item.get("action")),
                )
                for item in prepared_inventory
                if isinstance(item, Mapping)
                and item.get("coverage", "enumerated") == "enumerated"
                and all(
                    isinstance(item.get(key), str) and item.get(key)
                    for key in ("target_kind", "target_fingerprint", "action")
                )
            }
            active_runtime_count = connection.execute(
                """
                SELECT COUNT(*) AS count FROM runtime_sessions
                WHERE id IN (SELECT DISTINCT runtime_session_id FROM attempts WHERE work_item_id = ? AND runtime_session_id IS NOT NULL)
                  AND state NOT IN ('stopped', 'failed', 'missing')
                """,
                (work["id"],),
            ).fetchone()["count"]
            nonterminal_enrollments = connection.execute(
                """
                SELECT COUNT(*) AS count FROM worker_enrollments
                WHERE runtime_session_id IN (SELECT DISTINCT runtime_session_id FROM attempts WHERE work_item_id = ? AND runtime_session_id IS NOT NULL)
                  AND state NOT IN ('revoked', 'failed')
                """,
                (work["id"],),
            ).fetchone()["count"]
            if nonterminal_enrollments:
                active_runtime_count += int(nonterminal_enrollments)
            unresolved_effect_count = connection.execute(
                """
                SELECT COUNT(*) AS count FROM effect_operations
                WHERE cleanup_work_item_id = ? AND cleanup_generation = ?
                  AND status NOT IN ('succeeded', 'not_applied')
                """,
                (work["id"], work["generation"]),
            ).fetchone()["count"]
            internal_kinds = {
                CleanupTargetKind.RUNTIME.value,
                CleanupTargetKind.SUPERVISION_REGISTRATION.value,
            }
            derived_cleanup: list[CleanupRecord] = []
            for target_kind, fingerprint, action in sorted(expected_cleanup):
                if target_kind in internal_kinds:
                    derived_cleanup.append(
                        CleanupRecord(
                            CleanupTargetKind(target_kind),
                            fingerprint,
                            CleanupAction(action),
                            CleanupOutcome.SUCCEEDED,
                            "canonical-terminal-state",
                        )
                    )
                    continue
                effect = connection.execute(
                    "SELECT * FROM effect_operations WHERE cleanup_work_item_id = ? AND cleanup_generation = ? AND cleanup_preparation_id = ? AND cleanup_target_kind = ? AND cleanup_target_fingerprint = ? AND action = ?",
                    (
                        work["id"],
                        work["generation"],
                        preparation["id"],
                        target_kind,
                        fingerprint,
                        action,
                    ),
                ).fetchone()
                if (
                    effect is None
                    or str(effect["principal_id"]) != str(actor["id"])
                    or str(effect["status"])
                    not in {EffectStatus.SUCCEEDED.value, EffectStatus.NOT_APPLIED.value}
                ):
                    raise ConflictError(
                        "cleanup effect is not immutably bound to the prepared work inventory"
                    )
                if action in {"trash", "delete"} and (
                    str(effect["kind"]) != EffectKind.DESTRUCTIVE.value or not effect["grant_id"]
                ):
                    raise ConflictError("destructive cleanup is not bound to its authority grant")
                outcome = (
                    CleanupOutcome.SUCCEEDED
                    if str(effect["status"]) == EffectStatus.SUCCEEDED.value
                    else CleanupOutcome.NOT_APPLIED
                )
                derived_cleanup.append(
                    CleanupRecord(
                        CleanupTargetKind(target_kind),
                        fingerprint,
                        CleanupAction(action),
                        outcome,
                        str(effect["evidence"]),
                        effect_operation_id=str(effect["id"]),
                        destructive_authority_evidence_id=str(effect["grant_id"] or ""),
                    )
                )

            plan = ClosePlan(
                work_item_id=request.work_item_id,
                attempt_id=request.attempt_id,
                review_id=request.review_id,
                requester_decision_id=request.requester_decision_id,
                expected_goal_version=request.expected_goal_version,
                expected_goal_packet_digest=request.expected_goal_packet_digest,
                expected_task_packet_digest=request.expected_task_packet_digest,
                expected_generation=request.expected_generation,
                retention_policy_evidence_id=request.retention_policy_evidence_id,
                artifact_manifest_evidence_id=request.artifact_manifest_evidence_id,
                cleanup_inventory_evidence_id=request.cleanup_inventory_evidence_id,
                artifacts=tuple(
                    ArtifactPreservation(
                        str(artifact["artifact_id"]),
                        str(artifact["digest"]),
                        str(artifact["evidence_id"]),
                    )
                    for artifact in effective_artifact_rows
                ),
                cleanup=tuple(derived_cleanup),
                close_preparation_id=request.close_preparation_id,
            )
            readiness = CloseReadiness(
                work_state=str(work["state"]),
                attempt_state=str(attempt["state"]),
                review_verdict=str(review["verdict"]),
                requester_decision_verdict=str(decision["verdict"]),
                goal_version=int(work["goal_version"]),
                goal_packet_digest=str(attempt["goal_packet_digest"]),
                task_packet_digest=str(attempt["task_packet_digest"]),
                generation=int(work["generation"]),
                artifact_ids=tuple(sorted(prepared_artifact_digests)),
                open_delivery_count=int(open_deliveries["count"]),
                active_runtime_count=active_runtime_count,
                unresolved_effect_count=unresolved_effect_count,
            )
            try:
                plan_digest = require_close_ready(plan, readiness)
            except CloseContractError as error:
                raise ConflictError("close readiness failed", reason=str(error)) from error
            receipt_id = _id("close")
            now = utc_now()
            connection.execute(
                """
                INSERT INTO work_close_receipts(
                    id, work_item_id, attempt_id, review_id,
                    requester_decision_id, closed_by, supervisor_attachment_id,
                    supervisor_attachment_generation, goal_version,
                    goal_packet_digest, task_packet_digest, work_generation,
                    plan_digest, retention_policy_evidence_id,
                    artifact_manifest_evidence_id, cleanup_inventory_evidence_id,
                    close_preparation_id, artifacts_json, cleanup_json, request_digest, created_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    receipt_id,
                    work["id"],
                    attempt["id"],
                    review["id"],
                    decision["id"],
                    actor["id"],
                    attachment_id,
                    int(preparation["supervisor_attachment_generation"]),
                    work["goal_version"],
                    attempt["goal_packet_digest"],
                    attempt["task_packet_digest"],
                    work["generation"],
                    plan_digest,
                    request.retention_policy_evidence_id,
                    request.artifact_manifest_evidence_id,
                    request.cleanup_inventory_evidence_id,
                    request.close_preparation_id,
                    _json(effective_artifact_rows),
                    _json(
                        [
                            {
                                "target_kind": item.target_kind.value,
                                "target_fingerprint": item.target_fingerprint,
                                "action": item.action.value,
                                "outcome": item.outcome.value,
                                "evidence_id": item.evidence_id,
                                "effect_operation_id": item.effect_operation_id,
                                "destructive_authority_evidence_id": item.destructive_authority_evidence_id,
                            }
                            for item in derived_cleanup
                        ]
                    ),
                    request_digest,
                    now,
                ),
            )
            self._event(
                connection,
                "work.closed",
                "work_item",
                str(work["id"]),
                actor["id"],
                {
                    "close_receipt_id": receipt_id,
                    "plan_digest": plan_digest,
                    "attachment_generation": int(attachment_generation),
                },
            )
            result = self._work_bundle_tx(connection, str(work["id"]))
            self._idempotent_put(
                connection,
                actor["id"],
                operation,
                request.idempotency_key,
                request_digest,
                result,
            )
            return result

    # ------------------------------------------------------------------
    # Events
    # ------------------------------------------------------------------
    def list_events(
        self,
        *,
        after: int = 0,
        limit: int = 100,
        aggregate_type: str | None = None,
        aggregate_id: str | None = None,
        actor: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        if actor is not None:
            self._require_role(actor, PrincipalRole.CAO)
        clauses = ["sequence > ?"]
        params: list[Any] = [after]
        if aggregate_type:
            clauses.append("aggregate_type = ?")
            params.append(aggregate_type)
        if aggregate_id:
            clauses.append("aggregate_id = ?")
            params.append(aggregate_id)
        effective_limit = min(max(limit, 1), 1000)
        params.append(effective_limit + 1)
        rows = self.db.fetchall(
            f"SELECT * FROM events WHERE {' AND '.join(clauses)} ORDER BY sequence ASC LIMIT ?",
            params,
        )
        has_more = len(rows) > effective_limit
        rows = rows[:effective_limit]
        items = [self._event_view(row) for row in rows]
        return {
            "items": items,
            "next_cursor": items[-1]["sequence"] if has_more and items else None,
        }

    def get_consumer_cursor(self, name: str) -> int:
        row = self.db.fetchone("SELECT cursor FROM event_consumers WHERE name = ?", (name,))
        return int(row["cursor"]) if row else 0

    def set_consumer_cursor(self, name: str, cursor: int) -> None:
        with self.db.transaction() as connection:
            connection.execute(
                """
                INSERT INTO event_consumers(name, cursor, updated_at)
                VALUES(?, ?, ?)
                ON CONFLICT(name) DO UPDATE
                SET cursor = excluded.cursor, updated_at = excluded.updated_at
                """,
                (name, cursor, utc_now()),
            )

    # ------------------------------------------------------------------
    # Effect authority
    # ------------------------------------------------------------------
    def grant_effect(self, actor: dict[str, Any], request: EffectGrantInput) -> dict[str, Any]:
        self._require_role(actor, PrincipalRole.CAO)
        self.get_principal(request.principal_id)
        grant_id = _id("grant")
        with self.db.transaction() as connection:
            connection.execute(
                """
                INSERT INTO effect_grants(
                    id, principal_id, kind, target_pattern, action_pattern,
                    content_digest, argv_digest, workdir_digest, expires_at,
                    standing, consumed_at, created_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?)
                """,
                (
                    grant_id,
                    request.principal_id,
                    request.kind.value,
                    request.target_pattern,
                    request.action_pattern,
                    request.content_digest,
                    request.argv_digest,
                    request.workdir_digest,
                    request.expires_at,
                    1 if request.standing else 0,
                    utc_now(),
                ),
            )
            self._event(
                connection,
                "effect.granted",
                "effect_grant",
                grant_id,
                actor["id"],
                request.model_dump(mode="json"),
            )
        return self.get_effect_grant(grant_id)

    def get_effect_grant(self, grant_id: str) -> dict[str, Any]:
        row = self.db.fetchone("SELECT * FROM effect_grants WHERE id = ?", (grant_id,))
        if row is None:
            raise NotFoundError("effect grant", grant_id)
        value = dict(row)
        value["standing"] = bool(value["standing"])
        return value

    def revoke_effect_grant(self, actor: dict[str, Any], grant_id: str) -> dict[str, Any]:
        self._require_role(actor, PrincipalRole.CAO)
        grant = self.get_effect_grant(grant_id)
        with self.db.transaction() as connection:
            connection.execute("DELETE FROM effect_grants WHERE id = ?", (grant_id,))
            self._event(
                connection,
                "effect.grant_revoked",
                "effect_grant",
                grant_id,
                actor["id"],
                {},
            )
        return grant

    def check_effect(self, request: EffectCheckInput) -> dict[str, Any]:
        with self.db.connection_scope() as connection:
            return self._effect_decision_tx(connection, request)

    def _effect_decision_tx(
        self, connection: sqlite3.Connection, request: EffectCheckInput
    ) -> dict[str, Any]:
        principal = connection.execute(
            "SELECT id FROM principals WHERE id = ? AND enabled = 1",
            (request.principal_id,),
        ).fetchone()
        if principal is None:
            raise NotFoundError("enabled principal", request.principal_id)
        unresolved = connection.execute(
            """
            SELECT * FROM effect_operations
            WHERE principal_id = ? AND target = ? AND action = ?
              AND status IN (?, ?)
            ORDER BY created_at DESC LIMIT 1
            """,
            (
                request.principal_id,
                request.target,
                request.action,
                EffectStatus.STARTED.value,
                EffectStatus.UNKNOWN.value,
            ),
        ).fetchone()
        if unresolved:
            return {
                "decision": "verify_remote",
                "operation_id": unresolved["id"],
                "reason": "a previous operation has an unresolved outcome",
            }
        if request.kind == EffectKind.LOCAL:
            return {"decision": "allow", "grant_id": None, "reason": "local reversible effect"}
        rows = connection.execute(
            "SELECT * FROM effect_grants WHERE principal_id = ? AND kind = ? ORDER BY created_at",
            (request.principal_id, request.kind.value),
        ).fetchall()
        for row in rows:
            if row["consumed_at"] and not row["standing"]:
                continue
            if _is_expired(row["expires_at"]):
                continue
            if not matches(row["target_pattern"], request.target):
                continue
            if not matches(row["action_pattern"], request.action):
                continue
            if row["content_digest"] and row["content_digest"] != request.content_digest:
                continue
            if row["argv_digest"] and row["argv_digest"] != request.argv_digest:
                continue
            if row["workdir_digest"] and row["workdir_digest"] != request.workdir_digest:
                continue
            return {"decision": "allow", "grant_id": row["id"], "reason": "matching authority"}
        return {
            "decision": "approval_required",
            "grant_id": None,
            "reason": "no matching authority",
        }

    def start_effect(self, actor: dict[str, Any], request: EffectCheckInput) -> dict[str, Any]:
        if actor["id"] != request.principal_id:
            self._require_role(actor, PrincipalRole.CAO)
        operation_id = _id("op")
        now = utc_now()
        with self.db.transaction() as connection:
            if request.cleanup_work_item_id:
                preparation = connection.execute(
                    "SELECT id, inventory_json, inventory_digest FROM work_close_preparations WHERE work_item_id = ? AND work_generation = ?",
                    (request.cleanup_work_item_id, request.cleanup_generation),
                ).fetchone()
                inventory = _load(str(preparation["inventory_json"]), None) if preparation else None
                expected = (
                    {
                        (
                            str(item.get("target_kind")),
                            str(item.get("target_fingerprint")),
                            str(item.get("action")),
                        )
                        for item in inventory
                        if isinstance(item, Mapping)
                    }
                    if isinstance(inventory, list)
                    else set()
                )
                if (
                    preparation is None
                    or str(preparation["id"]) != request.cleanup_preparation_id
                    or _digest(inventory) != str(preparation["inventory_digest"])
                    or (
                        request.cleanup_target_kind,
                        request.cleanup_target_fingerprint,
                        request.action,
                    )
                    not in expected
                    or request.target != request.cleanup_target_fingerprint
                    or request.content_digest != request.cleanup_execution_digest
                ):
                    raise ConflictError(
                        "cleanup effect does not target a prepared close inventory item"
                    )
            decision = self._effect_decision_tx(connection, request)
            if decision["decision"] != "allow":
                raise AuthorizationError(
                    "effect is not authorized",
                    decision=decision["decision"],
                    reason=decision["reason"],
                    operation_id=decision.get("operation_id"),
                )
            grant_id = decision.get("grant_id")
            if grant_id:
                grant = connection.execute(
                    "SELECT * FROM effect_grants WHERE id = ?", (grant_id,)
                ).fetchone()
                if grant is None:
                    raise ConflictError("effect grant disappeared before reservation")
                if not grant["standing"]:
                    if grant["consumed_at"]:
                        raise ConflictError("one-time effect grant has already been consumed")
                    connection.execute(
                        "UPDATE effect_grants SET consumed_at = ? WHERE id = ?",
                        (now, grant_id),
                    )
            try:
                connection.execute(
                    """
                    INSERT INTO effect_operations(
                        id, principal_id, kind, target, action, content_digest,
                        argv_digest, workdir_digest, status, evidence, grant_id,
                        cleanup_work_item_id, cleanup_generation, cleanup_preparation_id,
                        cleanup_target_kind, cleanup_target_fingerprint,
                        cleanup_execution_digest, created_at, updated_at
                    ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, '', ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        operation_id,
                        request.principal_id,
                        request.kind.value,
                        request.target,
                        request.action,
                        request.content_digest,
                        request.argv_digest,
                        request.workdir_digest,
                        EffectStatus.STARTED.value,
                        grant_id,
                        request.cleanup_work_item_id or None,
                        request.cleanup_generation,
                        request.cleanup_preparation_id,
                        request.cleanup_target_kind,
                        request.cleanup_target_fingerprint,
                        request.cleanup_execution_digest,
                        now,
                        now,
                    ),
                )
            except sqlite3.IntegrityError as error:
                unresolved = connection.execute(
                    """
                    SELECT id FROM effect_operations
                    WHERE principal_id = ? AND kind = ? AND target = ? AND action = ?
                      AND content_digest = ? AND argv_digest = ? AND workdir_digest = ?
                      AND cleanup_work_item_id IS ? AND cleanup_generation IS ?
                      AND cleanup_target_kind = ? AND cleanup_target_fingerprint = ?
                      AND status IN (?, ?)
                    LIMIT 1
                    """,
                    (
                        request.principal_id,
                        request.kind.value,
                        request.target,
                        request.action,
                        request.content_digest,
                        request.argv_digest,
                        request.workdir_digest,
                        request.cleanup_work_item_id or None,
                        request.cleanup_generation,
                        request.cleanup_target_kind,
                        request.cleanup_target_fingerprint,
                        EffectStatus.STARTED.value,
                        EffectStatus.UNKNOWN.value,
                    ),
                ).fetchone()
                if unresolved is not None:
                    raise AuthorizationError(
                        "effect outcome must be verified before another reservation",
                        decision="verify_remote",
                        operation_id=unresolved["id"],
                    ) from error
                raise
            self._event(
                connection,
                "effect.started",
                "effect_operation",
                operation_id,
                actor["id"],
                request.model_dump(mode="json"),
            )
        return self.get_effect_operation(operation_id)

    def resolve_effect(
        self,
        actor: dict[str, Any],
        operation_id: str,
        request: EffectResolveInput,
    ) -> dict[str, Any]:
        operation = self.get_effect_operation(operation_id)
        if actor["id"] != operation["principal_id"]:
            self._require_role(actor, PrincipalRole.CAO)
        if operation["status"] in {
            EffectStatus.SUCCEEDED.value,
            EffectStatus.NOT_APPLIED.value,
            EffectStatus.FAILED.value,
        }:
            raise ConflictError("effect operation is already resolved", status=operation["status"])
        if request.status == EffectStatus.STARTED:
            raise ValidationError("effect cannot be resolved back to started")
        now = utc_now()
        with self.db.transaction() as connection:
            connection.execute(
                "UPDATE effect_operations SET status = ?, evidence = ?, updated_at = ? WHERE id = ?",
                (request.status.value, request.evidence, now, operation_id),
            )
            self._event(
                connection,
                "effect.resolved",
                "effect_operation",
                operation_id,
                actor["id"],
                {"status": request.status.value, "evidence": request.evidence},
            )
        return self.get_effect_operation(operation_id)

    def get_effect_operation(self, operation_id: str) -> dict[str, Any]:
        row = self.db.fetchone("SELECT * FROM effect_operations WHERE id = ?", (operation_id,))
        if row is None:
            raise NotFoundError("effect operation", operation_id)
        return dict(row)

    # ------------------------------------------------------------------
    # A2A task and callback configuration
    # ------------------------------------------------------------------
    def task_mapping(self, task_id: str) -> dict[str, Any]:
        row = self.db.fetchone("SELECT * FROM a2a_task_map WHERE task_id = ?", (task_id,))
        if row is None:
            raise NotFoundError("A2A task", task_id)
        return dict(row)

    def task_for_work(self, work_id: str) -> dict[str, Any]:
        row = self.db.fetchone("SELECT * FROM a2a_task_map WHERE work_item_id = ?", (work_id,))
        if row is None:
            raise NotFoundError("A2A task mapping", work_id)
        return dict(row)

    def create_push_config(
        self,
        actor: dict[str, Any],
        task_id: str,
        url: str,
        token: str = "",
        authentication_scheme: str = "Bearer",
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        self.task_mapping(task_id)
        require_loopback_url(url, allow_remote=self.settings.allow_remote_callbacks)
        config_id = _id("push")
        now = utc_now()
        encrypted = encrypt_secret(token, self.callback_key_path)
        with self.db.transaction() as connection:
            connection.execute(
                """
                INSERT INTO a2a_push_configs(
                    id, task_id, url, token_encrypted, authentication_scheme,
                    metadata_json, created_at, updated_at
                ) VALUES(?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    config_id,
                    task_id,
                    url,
                    encrypted,
                    authentication_scheme,
                    _json(metadata or {}),
                    now,
                    now,
                ),
            )
            self._event(
                connection,
                "a2a.push_config_created",
                "a2a_task",
                task_id,
                actor["id"],
                {"config_id": config_id, "url": url},
            )
        return self.get_push_config(task_id, config_id)

    def get_push_config(
        self, task_id: str, config_id: str, *, include_secret: bool = False
    ) -> dict[str, Any]:
        row = self.db.fetchone(
            "SELECT * FROM a2a_push_configs WHERE task_id = ? AND id = ?",
            (task_id, config_id),
        )
        if row is None:
            raise NotFoundError("push notification config", config_id)
        value = dict(row)
        encrypted = value.pop("token_encrypted")
        value["token"] = decrypt_secret(encrypted, self.callback_key_path) if include_secret else ""
        value["metadata"] = _load(value.pop("metadata_json"), {})
        return value

    def list_push_configs(self, task_id: str) -> list[dict[str, Any]]:
        self.task_mapping(task_id)
        rows = self.db.fetchall(
            "SELECT id FROM a2a_push_configs WHERE task_id = ? ORDER BY created_at",
            (task_id,),
        )
        return [self.get_push_config(task_id, row["id"]) for row in rows]

    def delete_push_config(
        self, actor: dict[str, Any], task_id: str, config_id: str
    ) -> dict[str, Any]:
        value = self.get_push_config(task_id, config_id)
        with self.db.transaction() as connection:
            connection.execute(
                "DELETE FROM a2a_push_configs WHERE task_id = ? AND id = ?",
                (task_id, config_id),
            )
            self._event(
                connection,
                "a2a.push_config_deleted",
                "a2a_task",
                task_id,
                actor["id"],
                {"config_id": config_id},
            )
        return value

    def enqueue_push_for_event(self, event_sequence: int, work_id: str) -> int:
        mapping = self.db.fetchone(
            "SELECT task_id FROM a2a_task_map WHERE work_item_id = ?", (work_id,)
        )
        if mapping is None:
            return 0
        configs = self.db.fetchall(
            "SELECT id FROM a2a_push_configs WHERE task_id = ?", (mapping["task_id"],)
        )
        now = utc_now()
        with self.db.transaction() as connection:
            count = 0
            for config in configs:
                try:
                    connection.execute(
                        """
                        INSERT INTO a2a_push_deliveries(
                            id, config_id, event_sequence, state, attempts,
                            next_attempt_at, created_at, updated_at
                        ) VALUES(?, ?, ?, 'queued', 0, ?, ?, ?)
                        """,
                        (_id("pushd"), config["id"], event_sequence, now, now, now),
                    )
                    count += 1
                except sqlite3.IntegrityError:
                    pass
        return count

    @staticmethod
    def _encode_work_cursor(row: Mapping[str, Any] | sqlite3.Row) -> str:
        payload = _json(
            {
                "priority": int(row["priority"]),
                "updated_at": str(row["updated_at"]),
                "id": str(row["id"]),
            }
        ).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    @staticmethod
    def _decode_work_cursor(cursor: str) -> tuple[int, str, str]:
        try:
            padding = "=" * (-len(cursor) % 4)
            payload = json.loads(base64.urlsafe_b64decode(cursor + padding).decode("utf-8"))
            priority = int(payload["priority"])
            updated_at = str(payload["updated_at"])
            work_id = str(payload["id"])
        except (KeyError, TypeError, ValueError, UnicodeError, json.JSONDecodeError) as error:
            raise ValidationError("invalid work query cursor") from error
        if not updated_at or not work_id:
            raise ValidationError("invalid work query cursor")
        return priority, updated_at, work_id

    def _resolve_requester_id(self, requested: str | None) -> str | None:
        with self.db.connection_scope() as connection:
            return self._resolve_requester_id_tx(connection, requested)

    @staticmethod
    def _resolve_requester_id_tx(
        connection: sqlite3.Connection, requested: str | None
    ) -> str | None:
        if requested:
            principal = connection.execute(
                "SELECT role, enabled FROM principals WHERE id = ?", (requested,)
            ).fetchone()
            if (
                principal is None
                or principal["role"] != PrincipalRole.USER.value
                or not bool(principal["enabled"])
            ):
                raise ValidationError("requester_id must identify an enabled user principal")
            return requested
        rows = connection.execute(
            "SELECT id FROM principals WHERE role = ? AND enabled = 1 ORDER BY id",
            (PrincipalRole.USER.value,),
        ).fetchall()
        if not rows:
            raise ValidationError("at least one enabled user principal is required")
        if len(rows) > 1:
            raise ValidationError(
                "requester_id is required when multiple user principals are enabled",
                enabled_user_count=len(rows),
            )
        return str(rows[0]["id"])

    @staticmethod
    def _authorize_work_actor(actor: dict[str, Any], work: Mapping[str, Any] | sqlite3.Row) -> None:
        role = actor["role"]
        if role == PrincipalRole.CAO.value:
            attachment_id = actor.get("_cao_attachment_id")
            if attachment_id and work["supervisor_attachment_id"] != attachment_id:
                raise AuthorizationError("work item belongs to another CAO conversation")
            return
        if role == PrincipalRole.USER.value and work["requester_id"] == actor["id"]:
            return
        if role == PrincipalRole.WORKER.value and work["assigned_worker_id"] == actor["id"]:
            return
        raise AuthorizationError("work item is outside this principal's scope")

    def _require_authorized_work_tx(
        self,
        connection: sqlite3.Connection,
        actor: dict[str, Any],
        work_id: str,
    ) -> sqlite3.Row:
        """Load and authorize an exact Work before any cached result is returned."""

        work = connection.execute("SELECT * FROM work_items WHERE id = ?", (work_id,)).fetchone()
        if work is None:
            raise NotFoundError("work item", work_id)
        self._authorize_work_actor(actor, work)
        return cast(sqlite3.Row, work)

    def _authorize_cached_work_result_tx(
        self,
        connection: sqlite3.Connection,
        actor: dict[str, Any],
        *,
        operation: str,
        idempotency_key: str,
    ) -> None:
        """Preauthorize a creation receipt whose cached result is a Work bundle."""

        if not idempotency_key:
            return
        receipt = connection.execute(
            "SELECT result_json FROM idempotency_results "
            "WHERE actor_id = ? AND operation = ? AND idempotency_key = ?",
            (actor["id"], operation, idempotency_key),
        ).fetchone()
        if receipt is None:
            return
        result = _load(str(receipt["result_json"]), None)
        work_id = result.get("id") if isinstance(result, Mapping) else None
        if not isinstance(work_id, str) or not work_id:
            raise RuntimeError("cached Work result is malformed")
        self._require_authorized_work_tx(connection, actor, work_id)

    # ------------------------------------------------------------------
    # Internal views/helpers
    # ------------------------------------------------------------------
    def _record_boundary_tx(
        self,
        connection: sqlite3.Connection,
        *,
        actor: dict[str, Any],
        request: BoundaryInput,
    ) -> dict[str, Any]:
        input_digest = _digest(request.model_dump(mode="json"))
        existing = connection.execute(
            "SELECT * FROM boundaries WHERE source_principal_id = ? AND source_event_id = ?",
            (actor["id"], request.source_event_id),
        ).fetchone()
        if existing is not None:
            if existing["input_digest"] != input_digest:
                raise ConflictError("boundary source identity was reused with different data")
            if request.metadata.get("runtime_recovery") is True:
                _backfill_managed_worker_recovery_actions(connection, self.settings)
                existing = connection.execute(
                    "SELECT * FROM boundaries WHERE id = ?", (existing["id"],)
                ).fetchone()
                assert existing is not None
            return self._boundary_view(existing)
        work = connection.execute(
            "SELECT * FROM work_items WHERE id = ?", (request.work_item_id,)
        ).fetchone()
        if work is None:
            raise NotFoundError("work item", request.work_item_id)
        attempt = connection.execute(
            "SELECT * FROM attempts WHERE id = ?", (request.attempt_id,)
        ).fetchone()
        if attempt is None or attempt["work_item_id"] != work["id"]:
            raise ValidationError("boundary attempt does not belong to the work item")
        if actor["role"] == PrincipalRole.WORKER.value and attempt["worker_id"] != actor["id"]:
            raise AuthorizationError("Worker cannot record another Worker's boundary")
        if int(work["goal_version"]) != request.expected_goal_version:
            raise StaleGoalError(request.expected_goal_version, int(work["goal_version"]))
        if (
            str(attempt["goal_packet_digest"]) != request.expected_goal_packet_digest
            or str(attempt["task_packet_digest"]) != request.expected_task_packet_digest
            or int(attempt["goal_version"]) != request.expected_goal_version
        ):
            raise ConflictError("boundary targets a stale or partial task packet")
        if int(work["generation"]) != request.expected_generation:
            raise StaleGenerationError(request.expected_generation, int(work["generation"]))
        latest_attempt = self._latest_attempt_tx(connection, str(work["id"]))
        if latest_attempt is None or latest_attempt["id"] != attempt["id"]:
            raise ConflictError("boundary targets a superseded attempt")
        require_not_paused(work)
        boundary_id = _id("bnd")
        now = utc_now()
        connection.execute(
            """
            INSERT INTO boundaries(
                id, source_principal_id, source_event_id, work_item_id,
                attempt_id, goal_version, generation, goal_packet_digest,
                task_packet_digest, kind, summary,
                runtime_state, metadata_json, recovery_action,
                input_digest, created_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                boundary_id,
                actor["id"],
                request.source_event_id,
                work["id"],
                attempt["id"],
                request.expected_goal_version,
                request.expected_generation,
                request.expected_goal_packet_digest,
                request.expected_task_packet_digest,
                request.kind.value,
                request.summary,
                request.runtime_state.value,
                _json(request.metadata),
                _boundary_recovery_action(request.metadata),
                input_digest,
                now,
            ),
        )
        self._event(
            connection,
            "boundary.recorded",
            "work_item",
            str(work["id"]),
            actor["id"],
            {
                "boundary_id": boundary_id,
                "kind": request.kind.value,
                "runtime_state": request.runtime_state.value,
                "generation": request.expected_generation,
            },
        )
        if request.metadata.get("runtime_recovery") is True:
            _backfill_managed_worker_recovery_actions(connection, self.settings)
        row = connection.execute("SELECT * FROM boundaries WHERE id = ?", (boundary_id,)).fetchone()
        assert row is not None
        return self._boundary_view(row)

    def _record_submitted_intent_tx(
        self,
        connection: sqlite3.Connection,
        *,
        source_principal_id: str,
        source_id: str,
        payload: dict[str, Any],
    ) -> tuple[sqlite3.Row, sqlite3.Row]:
        payload_digest = _digest(payload)
        existing = connection.execute(
            "SELECT * FROM source_receipts WHERE source_principal_id = ? AND source_id = ?",
            (source_principal_id, source_id),
        ).fetchone()
        if existing is not None:
            if existing["payload_digest"] != payload_digest:
                raise ConflictError(
                    "source identity was already used for a different submitted payload",
                    source_id=source_id,
                )
            intent = connection.execute(
                """
                SELECT * FROM submitted_intents
                WHERE source_receipt_id = ? AND ordinal = 0
                """,
                (existing["id"],),
            ).fetchone()
            if intent is None:
                raise RuntimeError("source receipt is missing its submitted intent")
            return existing, intent
        receipt_id = _id("src")
        intent_id = _id("int")
        now = utc_now()
        connection.execute(
            """
            INSERT INTO source_receipts(
                id, source_principal_id, source_id, payload_json,
                payload_digest, received_at
            ) VALUES(?, ?, ?, ?, ?, ?)
            """,
            (
                receipt_id,
                source_principal_id,
                source_id,
                _json(payload),
                payload_digest,
                now,
            ),
        )
        connection.execute(
            """
            INSERT INTO submitted_intents(
                id, source_receipt_id, ordinal, submitter_id,
                content_json, content_digest, correlation_id, created_at
            ) VALUES(?, ?, 0, ?, ?, ?, ?, ?)
            """,
            (
                intent_id,
                receipt_id,
                source_principal_id,
                _json(payload),
                payload_digest,
                receipt_id,
                now,
            ),
        )
        self._event(
            connection,
            "intent.received",
            "source_receipt",
            receipt_id,
            source_principal_id,
            {"payload_digest": payload_digest},
        )
        self._event(
            connection,
            "intent.submitted",
            "submitted_intent",
            intent_id,
            source_principal_id,
            {"source_receipt_id": receipt_id, "ordinal": 0},
            correlation_id=receipt_id,
        )
        receipt = connection.execute(
            "SELECT * FROM source_receipts WHERE id = ?", (receipt_id,)
        ).fetchone()
        intent = connection.execute(
            "SELECT * FROM submitted_intents WHERE id = ?", (intent_id,)
        ).fetchone()
        assert receipt is not None and intent is not None
        return receipt, intent

    def _store_intent_disposition_tx(
        self,
        connection: sqlite3.Connection,
        *,
        actor_id: str,
        intent: sqlite3.Row,
        receipt: sqlite3.Row,
        kind: IntentKind,
        relation: IntentRelation | None,
        target_work_item_id: str | None,
        result_work_item_id: str | None,
        result_directive_id: str | None,
        reason: str,
        request_digest: str,
        result: dict[str, Any],
    ) -> dict[str, Any]:
        """Persist the one authoritative classification of a submitted intent."""

        existing = connection.execute(
            "SELECT * FROM intent_dispositions WHERE submitted_intent_id = ?",
            (intent["id"],),
        ).fetchone()
        if existing is not None:
            if existing["request_digest"] != request_digest:
                raise ConflictError("submitted intent was already classified differently")
            return cast(dict[str, Any], _load(existing["result_json"], {}))

        disposition_id = _id("disp")
        now = utc_now()
        stored_result = {
            **result,
            "disposition_id": disposition_id,
            "reason": reason,
        }
        connection.execute(
            """
            INSERT INTO intent_dispositions(
                id, submitted_intent_id, source_receipt_id,
                decided_by, kind, relation,
                target_work_item_id, result_work_item_id,
                result_directive_id, reason, request_digest,
                result_json, created_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                disposition_id,
                intent["id"],
                receipt["id"],
                actor_id,
                kind.value,
                relation.value if relation else None,
                target_work_item_id,
                result_work_item_id,
                result_directive_id,
                reason,
                request_digest,
                _json(stored_result),
                now,
            ),
        )
        self._event(
            connection,
            "intent.classified",
            "submitted_intent",
            str(intent["id"]),
            actor_id,
            {
                "kind": kind.value,
                "relation": relation.value if relation else None,
                "work_item_id": result_work_item_id,
                "directive_id": result_directive_id,
            },
        )
        return stored_result

    def _create_directive_tx(
        self,
        connection: sqlite3.Connection,
        *,
        actor_id: str,
        intent: sqlite3.Row,
        receipt: sqlite3.Row,
        relation: IntentRelation | None,
        content: str,
        reason: str,
        target_work_item_id: str | None,
        created_work_item_id: str | None,
        expected_goal_version: int,
        materialized: bool = False,
    ) -> dict[str, Any]:
        if relation is None:
            raise ValidationError("directive relation is required")
        directive_id = _id("dir")
        now = utc_now()
        bound_work_id = target_work_item_id or created_work_item_id
        goal = (
            connection.execute(
                "SELECT packet_digest FROM goal_revisions WHERE work_item_id = ? AND version = ?",
                (bound_work_id, expected_goal_version),
            ).fetchone()
            if bound_work_id
            else None
        )
        if bound_work_id and goal is None:
            raise ConflictError("directive cannot bind a missing goal packet")
        expected_goal_packet_digest = str(goal["packet_digest"]) if goal else ""
        connection.execute(
            """
            INSERT INTO directives(
                id, submitted_intent_id, source_receipt_id, issuer_id,
                target_work_item_id, created_work_item_id, relation,
                expected_goal_version, expected_goal_packet_digest,
                state, content, reason,
                created_at, updated_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                directive_id,
                intent["id"],
                receipt["id"],
                actor_id,
                target_work_item_id,
                created_work_item_id,
                relation.value,
                expected_goal_version,
                expected_goal_packet_digest,
                (DirectiveState.HANDLED.value if materialized else DirectiveState.PENDING.value),
                content,
                reason,
                now,
                now,
            ),
        )
        if materialized:
            connection.execute(
                """
                UPDATE directives
                SET handled_by = ?, handled_at = ?
                WHERE id = ?
                """,
                (actor_id, now, directive_id),
            )
        aggregate_id = target_work_item_id or created_work_item_id or directive_id
        self._event(
            connection,
            "directive.created",
            "work_item" if target_work_item_id or created_work_item_id else "directive",
            aggregate_id,
            actor_id,
            {
                "directive_id": directive_id,
                "relation": relation.value,
                "expected_goal_version": expected_goal_version,
                "expected_goal_packet_digest": expected_goal_packet_digest,
                "created_work_item_id": created_work_item_id,
            },
        )
        row = connection.execute(
            "SELECT * FROM directives WHERE id = ?", (directive_id,)
        ).fetchone()
        assert row is not None
        return dict(row)

    def _attachment_packet_tx(
        self, connection: sqlite3.Connection, attachment_id: str
    ) -> dict[str, Any]:
        """Return the immutable identity captured in goal/task packet digests."""

        row = connection.execute(
            """
            SELECT a.id, a.principal_id, a.runtime_session_id, a.native_thread_id,
                   a.project_digest, a.generation
            FROM cao_session_attachments AS a
            WHERE a.id = ?
            """,
            (attachment_id,),
        ).fetchone()
        if row is None:
            raise ConflictError(
                "WorkItem CAO attachment no longer exists", attachment_id=attachment_id
            )
        return {
            "attachment_id": str(row["id"]),
            "supervisor_id": str(row["principal_id"]),
            "runtime_session_id": str(row["runtime_session_id"]),
            "native_thread_id": str(row["native_thread_id"]),
            "project_digest": str(row["project_digest"]),
            "generation": int(row["generation"]),
        }

    def _bind_cao_attachment_tx(
        self,
        connection: sqlite3.Connection,
        *,
        supervisor_id: str,
        request: WorkAssignment,
    ) -> dict[str, Any] | None:
        """Validate the explicit CAO thread selected when Work is delegated."""

        if not request.supervisor_attachment_id:
            if self.settings.require_cao_attachment_for_work:
                raise ValidationError("new WorkItem requires an explicit CAO session attachment")
            return None
        row = connection.execute(
            """
            SELECT a.*
            FROM cao_session_attachments AS a
            WHERE a.id = ? AND a.principal_id = ?
              AND a.state = 'active'
            """,
            (request.supervisor_attachment_id, supervisor_id),
        ).fetchone()
        if row is None:
            raise ConflictError("CAO attachment is not active and owned by this supervisor")
        if request.supervisor_project_digest != str(row["project_digest"]):
            raise ConflictError("CAO attachment project digest does not match WorkItem binding")
        return self._attachment_packet_tx(connection, str(row["id"]))

    @staticmethod
    def _provider_instruction_source_boundary_tx(
        connection: sqlite3.Connection,
        runtime_id: str,
    ) -> str:
        """Bind an explicit assignment event to the current typed 429 epoch.

        This marker is provenance, not authority by itself.  Candidate
        validation independently re-proves the boundary, target, attachment,
        instruction sequence, and one-shot circuit CAS.
        """

        rows = connection.execute(
            """
            SELECT circuit.source_boundary_id
            FROM managed_worker_specs AS spec
            JOIN provider_runtime_circuits AS circuit
              ON circuit.scope_digest = spec.provider_scope_digest
            WHERE spec.runtime_session_id = ?
              AND spec.adapter = 'claude'
              AND spec.state = 'enabled'
              AND spec.catalog_target_id <> ''
              AND circuit.state = 'open'
              AND circuit.probe_outcome_state = 'none'
              AND circuit.source_boundary_id IS NOT NULL
              AND circuit.source_boundary_id <> ''
            """,
            (runtime_id,),
        ).fetchall()
        if len(rows) != 1:
            return ""
        return str(rows[0]["source_boundary_id"])

    def _replace_goal_tx(
        self,
        connection: sqlite3.Connection,
        *,
        actor_id: str,
        target: sqlite3.Row,
        request: WorkAssignment,
        reason: str,
        directive_id: str,
        admission: _ManagedWorkerCommandAdmission | None = None,
    ) -> dict[str, Any]:
        require_not_paused(target)
        worker = connection.execute(
            "SELECT * FROM principals WHERE id = ?", (request.worker_id,)
        ).fetchone()
        if (
            worker is None
            or worker["role"] != PrincipalRole.WORKER.value
            or not bool(worker["enabled"])
        ):
            raise ValidationError("replacement worker must be an enabled Worker")
        if str(worker["operator_scope"]) != str(target["operator_scope"]):
            raise ConflictError("replacement Worker operator scope does not match WorkItem")
        existing_attachment_id = target["supervisor_attachment_id"]
        if existing_attachment_id:
            existing_attachment = self._attachment_packet_tx(
                connection, str(existing_attachment_id)
            )
            if request.supervisor_attachment_id and (
                request.supervisor_attachment_id != existing_attachment["attachment_id"]
                or request.supervisor_project_digest != existing_attachment["project_digest"]
            ):
                raise ConflictError("a WorkItem CAO attachment binding is immutable")
            request = request.model_copy(
                update={
                    "supervisor_attachment_id": existing_attachment["attachment_id"],
                    "supervisor_project_digest": existing_attachment["project_digest"],
                }
            )
        elif request.supervisor_attachment_id:
            raise ConflictError(
                "a legacy unbound WorkItem cannot gain a CAO attachment by revision"
            )
        previous = self._latest_attempt_tx(connection, str(target["id"]))
        continuation_boundary = (
            self._current_user_needed_boundary_tx(
                connection,
                actor_id=actor_id,
                work=target,
                source_attempt=previous,
            )
            if previous is not None
            else None
        )
        if previous is None and str(target["state"]) == WorkState.USER_NEEDED.value:
            raise ConflictError(
                "requester-input authority has no source Attempt",
                reason_code="worker_command_binding_ambiguous",
                retryable=False,
            )
        if admission is None:
            admission = self._admit_managed_worker_command_tx(
                connection,
                actor_id=actor_id,
                kind="replace_goal",
                worker_id=request.worker_id,
                supervisor_attachment_id=(
                    str(existing_attachment_id) if existing_attachment_id else None
                ),
                work=target,
                previous_attempt=previous,
                worker_thread_id=request.managed_worker_thread_id,
                expected_worker_thread_generation=(request.managed_worker_thread_generation),
            )
        runtime_session_id = (
            admission.runtime_session_id
            if admission is not None
            else self._bind_ready_worker_runtime_tx(
                connection,
                worker_id=request.worker_id,
                runtime_session_id=request.runtime_session_id,
            )
        )
        request = request.model_copy(update={"runtime_session_id": runtime_session_id})
        self._require_managed_worker_work_attachment_tx(
            connection,
            supervisor_id=actor_id,
            worker_id=request.worker_id,
            runtime_session_id=str(request.runtime_session_id),
            supervisor_attachment_id=(
                str(existing_attachment_id) if existing_attachment_id else None
            ),
        )
        provider_source_boundary_id = self._provider_instruction_source_boundary_tx(
            connection, str(request.runtime_session_id)
        )
        next_version = int(target["goal_version"]) + 1
        next_generation = int(target["generation"]) + 1
        preserve_suspension = target["state"] == WorkState.SUSPENDED.value
        acceptance = [item.strip() for item in request.acceptance if item.strip()]
        non_goals = [item.strip() for item in request.non_goals if item.strip()]
        now = utc_now()
        directive = connection.execute(
            "SELECT submitted_intent_id, source_receipt_id FROM directives WHERE id = ?",
            (directive_id,),
        ).fetchone()
        if directive is None:
            raise NotFoundError("directive", directive_id)
        prior_goal = self._current_goal_tx(connection, target)
        prior_goal_packet = _load(str(prior_goal["packet_json"]), {})
        if not isinstance(prior_goal_packet, Mapping):
            raise ConflictError("current goal packet is malformed")
        managed_task_policy = prior_goal_packet.get("managed_task_policy")
        if managed_task_policy is not None and not isinstance(managed_task_policy, Mapping):
            raise ConflictError("current goal task policy binding is malformed")
        goal_packet = build_goal_packet(
            work_item_id=str(target["id"]),
            version=next_version,
            title=request.title,
            objective=request.objective,
            maturity=request.maturity.value,
            acceptance=acceptance,
            non_goals=non_goals,
            priority=request.priority,
            requester_id=(str(target["requester_id"]) if target["requester_id"] else None),
            supervisor_id=(str(target["supervisor_id"]) if target["supervisor_id"] else None),
            metadata=request.metadata,
            reason=reason,
            created_by=actor_id,
            source_intent_id=str(directive["submitted_intent_id"]),
            source_directive_id=directive_id,
            correlation_id=str(directive["source_receipt_id"]),
            prior_version=int(target["goal_version"]),
            completion_contract=request.completion_contract.value,
            supervisor_attachment=(
                self._attachment_packet_tx(connection, str(existing_attachment_id))
                if existing_attachment_id
                else None
            ),
            dependencies=[item.value for item in request.dependencies],
            managed_task_policy=managed_task_policy,
        )
        goal_digest = goal_packet_digest(goal_packet)
        self._fence_reasoner_turns_tx(connection, str(target["id"]))
        connection.execute(
            """
            INSERT INTO goal_revisions(
                work_item_id, version, title, objective, maturity,
                acceptance_json, non_goals_json, priority, requester_id,
                supervisor_id, metadata_json, packet_json, packet_digest,
                reason, created_by, source_intent_id, source_directive_id,
                correlation_id, prior_version,
                supervisor_attachment_generation,
                supervisor_runtime_session_id, created_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                target["id"],
                next_version,
                request.title,
                request.objective,
                request.maturity.value,
                _json(acceptance),
                _json(non_goals),
                request.priority,
                target["requester_id"],
                target["supervisor_id"],
                _json(request.metadata),
                _json(goal_packet),
                goal_digest,
                reason,
                actor_id,
                directive["submitted_intent_id"],
                directive_id,
                directive["source_receipt_id"],
                target["goal_version"],
                (
                    int(goal_packet["supervisor_attachment"]["generation"])
                    if "supervisor_attachment" in goal_packet
                    else None
                ),
                (
                    str(goal_packet["supervisor_attachment"]["runtime_session_id"])
                    if "supervisor_attachment" in goal_packet
                    else None
                ),
                now,
            ),
        )
        number = int(previous["attempt_number"]) + 1 if previous else 1
        if previous and previous["state"] not in {
            AttemptState.COMPLETED.value,
            AttemptState.FAILED.value,
            AttemptState.CANCELED.value,
        }:
            connection.execute(
                "UPDATE attempts SET state = ?, updated_at = ? WHERE id = ?",
                (AttemptState.CANCELED.value, now, previous["id"]),
            )
        attempt_id = _id("att")
        task_packet = build_task_packet(
            goal_packet_digest_value=goal_digest,
            work_item_id=str(target["id"]),
            goal_version=next_version,
            attempt_id=attempt_id,
            attempt_number=number,
            worker_id=request.worker_id,
            runtime_session_id=request.runtime_session_id,
            supervisor_attachment=(
                self._attachment_packet_tx(connection, str(existing_attachment_id))
                if existing_attachment_id
                else None
            ),
            dependencies=[item.value for item in request.dependencies],
        )
        task_digest = task_packet_digest(task_packet)
        next_thread_id = (
            admission.worker_thread_id
            if admission is not None
            else (
                target["managed_worker_thread_id"]
                if str(target["assigned_worker_id"]) == request.worker_id
                else None
            )
        )
        next_thread_generation = (
            admission.thread_generation
            if admission is not None
            else (
                target["managed_worker_thread_generation"]
                if str(target["assigned_worker_id"]) == request.worker_id
                else None
            )
        )
        if continuation_boundary is not None:
            prepared = connection.execute(
                """
                UPDATE work_items
                SET title = ?, goal_version = ?, assigned_worker_id = ?,
                    managed_worker_thread_id = ?, managed_worker_thread_generation = ?,
                    priority = ?, metadata_json = ?, suspended_by_work_item_id = NULL,
                    updated_at = ?
                WHERE id = ? AND state = 'user_needed' AND attention_owner = 'user'
                  AND generation = ? AND user_needed_boundary_id = ?
                """,
                (
                    request.title,
                    next_version,
                    request.worker_id,
                    next_thread_id,
                    next_thread_generation,
                    request.priority,
                    _json(request.metadata),
                    now,
                    target["id"],
                    target["generation"],
                    continuation_boundary["id"],
                ),
            ).rowcount
            if prepared != 1:
                raise ConflictError(
                    "requester-input revision lost its preparation fence",
                    reason_code="worker_command_generation_conflict",
                    retryable=False,
                )
        else:
            connection.execute(
                """
                UPDATE work_items
                SET title = ?, goal_version = ?, assigned_worker_id = ?,
                    managed_worker_thread_id = ?, managed_worker_thread_generation = ?,
                    priority = ?, metadata_json = ?,
                    state = ?, attention_owner = ?, generation = ?,
                    suspended_by_work_item_id = ?, updated_at = ?
                WHERE id = ?
                """,
                (
                    request.title,
                    next_version,
                    request.worker_id,
                    next_thread_id,
                    next_thread_generation,
                    request.priority,
                    _json(request.metadata),
                    (WorkState.SUSPENDED.value if preserve_suspension else WorkState.ACTIVE.value),
                    (
                        AttentionOwner.NONE.value
                        if preserve_suspension
                        else AttentionOwner.WORKER.value
                    ),
                    next_generation,
                    target["suspended_by_work_item_id"] if preserve_suspension else None,
                    now,
                    target["id"],
                ),
            )
        connection.execute(
            """
            INSERT INTO attempts(
                id, work_item_id, attempt_number, worker_id,
                runtime_session_id, goal_version, goal_packet_digest,
                task_packet_digest, state, trajectory, evidence_confidence,
                stage, next_boundary, completion_claim_json, created_at, updated_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, '', '', '{}', ?, ?)
            """,
            (
                attempt_id,
                target["id"],
                number,
                request.worker_id,
                request.runtime_session_id,
                next_version,
                goal_digest,
                task_digest,
                (
                    AttemptState.SUSPENDED.value
                    if preserve_suspension
                    else AttemptState.ASSIGNED.value
                ),
                Trajectory.UNTRACKED.value,
                EvidenceConfidence.UNKNOWN.value,
                now,
                now,
            ),
        )
        connection.execute(
            """
            UPDATE directives
            SET state = ?, handled_by = ?, handled_at = ?, updated_at = ?
            WHERE id = ?
            """,
            (DirectiveState.HANDLED.value, actor_id, now, now, directive_id),
        )
        message = self._message(
            connection,
            sender_id=actor_id,
            recipient_id=request.worker_id,
            kind=MessageKind.ASSIGNMENT,
            payload={
                "work_item_id": target["id"],
                "attempt_id": attempt_id,
                "goal_version": next_version,
                "generation": next_generation,
                "title": request.title,
                "objective": request.objective,
                "maturity": request.maturity.value,
                "acceptance": acceptance,
                "non_goals": non_goals,
                "completion_contract": request.completion_contract.value,
                **(
                    {"dependencies": [item.value for item in request.dependencies]}
                    if request.dependencies
                    else {}
                ),
                "reason": reason,
                "directive_id": directive_id,
                **(
                    {"managed_task_policy": dict(managed_task_policy)}
                    if isinstance(managed_task_policy, Mapping)
                    else {}
                ),
                "goal_packet_digest": goal_digest,
                "task_packet_digest": task_digest,
            },
            work_item_id=target["id"],
            attempt_id=attempt_id,
            goal_version=next_version,
            idempotency_key=f"replace:{directive_id}",
        )
        if continuation_boundary is not None:
            assert previous is not None
            successor_attempt = connection.execute(
                "SELECT * FROM attempts WHERE id = ?", (attempt_id,)
            ).fetchone()
            assert successor_attempt is not None
            self._consume_user_needed_boundary_tx(
                connection,
                actor_id=actor_id,
                work=target,
                boundary=continuation_boundary,
                source_attempt=previous,
                successor_attempt=successor_attempt,
                successor_generation=next_generation,
                message_id=str(message["id"]),
                now=now,
            )
        goal_replaced_sequence = self._event(
            connection,
            "work.goal_replaced",
            "work_item",
            str(target["id"]),
            actor_id,
            {
                "directive_id": directive_id,
                "version": next_version,
                "generation": next_generation,
                "attempt_id": attempt_id,
                **(
                    {"provider_source_boundary_id": provider_source_boundary_id}
                    if provider_source_boundary_id
                    else {}
                ),
            },
            causation_id=message["id"],
        )
        stale_boundaries = connection.execute(
            """
            SELECT boundary.id, boundary_event.sequence AS boundary_event_sequence
            FROM boundaries AS boundary
            JOIN events AS boundary_event
              ON boundary_event.event_type = 'boundary.recorded'
             AND boundary_event.aggregate_type = 'work_item'
             AND boundary_event.aggregate_id = boundary.work_item_id
             AND json_extract(boundary_event.data_json, '$.boundary_id') = boundary.id
            LEFT JOIN boundary_dispositions AS disposition
              ON disposition.boundary_id = boundary.id
            LEFT JOIN boundary_supersessions AS supersession
              ON supersession.boundary_id = boundary.id
            WHERE boundary.work_item_id = ?
              AND boundary.goal_version = ?
              AND boundary.generation = ?
              AND disposition.id IS NULL
              AND supersession.boundary_id IS NULL
              AND (
                  SELECT COUNT(*) FROM events AS exact_boundary_event
                  WHERE exact_boundary_event.event_type = 'boundary.recorded'
                    AND exact_boundary_event.aggregate_type = 'work_item'
                    AND exact_boundary_event.aggregate_id = boundary.work_item_id
                    AND json_extract(
                          exact_boundary_event.data_json, '$.boundary_id'
                        ) = boundary.id
              ) = 1
            ORDER BY boundary.id
            """,
            (target["id"], target["goal_version"], target["generation"]),
        ).fetchall()
        for boundary in stale_boundaries:
            connection.execute(
                """
                INSERT INTO boundary_supersessions(
                    boundary_id, boundary_event_sequence,
                    superseding_event_sequence, reason, created_at
                ) VALUES(?, ?, ?, 'goal_replaced', ?)
                """,
                (
                    boundary["id"],
                    boundary["boundary_event_sequence"],
                    goal_replaced_sequence,
                    now,
                ),
            )
            self._supersede_boundary_deliveries_tx(
                connection,
                boundary_id=str(boundary["id"]),
                recipient_id=actor_id,
                reason="goal_replaced",
            )
        return self._work_bundle_tx(connection, str(target["id"]))

    def _create_work_tx(
        self,
        connection: sqlite3.Connection,
        *,
        actor_id: str,
        request: WorkAssignment,
        requester_id: str | None,
        source_receipt_id: str = "",
        source_intent_id: str | None = None,
        relation: IntentRelation | None = None,
        target: sqlite3.Row | None = None,
        managed_task_policy: Mapping[str, Any] | None = None,
        worker_thread_id: str | None = None,
        expected_worker_thread_generation: int | None = None,
        admission: _ManagedWorkerCommandAdmission | None = None,
    ) -> dict[str, Any]:
        if (
            relation == IntentRelation.INTERRUPT
            and target is not None
            and (
                str(target["state"]) == WorkState.USER_NEEDED.value
                or target["user_needed_boundary_id"] is not None
            )
        ):
            raise ConflictError(
                "requester-input Work cannot be interrupted before its exact decision",
                reason_code="worker_command_outcome_unsettled",
                blocker_kind="requester_input_pending",
                retryable=False,
            )
        worker = connection.execute(
            "SELECT * FROM principals WHERE id = ?", (request.worker_id,)
        ).fetchone()
        if (
            worker is None
            or worker["role"] != PrincipalRole.WORKER.value
            or not bool(worker["enabled"])
        ):
            raise ValidationError("assigned principal must be an enabled Worker")
        if request.managed_worker_thread_id is not None:
            if worker_thread_id is not None and (
                worker_thread_id != request.managed_worker_thread_id
                or expected_worker_thread_generation != request.managed_worker_thread_generation
            ):
                raise ConflictError(
                    "managed Worker assignment supplied conflicting logical authority",
                    reason_code="worker_command_binding_conflict",
                    retryable=False,
                )
            worker_thread_id = request.managed_worker_thread_id
            expected_worker_thread_generation = request.managed_worker_thread_generation
        if admission is None:
            admission = self._admit_managed_worker_command_tx(
                connection,
                actor_id=actor_id,
                kind="create_work",
                worker_id=request.worker_id,
                supervisor_attachment_id=request.supervisor_attachment_id,
                worker_thread_id=worker_thread_id,
                expected_worker_thread_generation=expected_worker_thread_generation,
            )
        if (
            admission is not None
            and request.runtime_session_id is not None
            and request.runtime_session_id != admission.runtime_session_id
        ):
            historical_route = connection.execute(
                "SELECT 1 FROM managed_worker_thread_epochs "
                "WHERE thread_id = ? AND runtime_session_id = ?",
                (admission.worker_thread_id, request.runtime_session_id),
            ).fetchone()
            if historical_route is None:
                raise ValidationError(
                    "managed runtime selection does not match the exact admitted route",
                    reason_code="managed_runtime_selection_conflict",
                )
        runtime_session_id = (
            admission.runtime_session_id
            if admission is not None
            else self._bind_ready_worker_runtime_tx(
                connection,
                worker_id=request.worker_id,
                runtime_session_id=request.runtime_session_id,
            )
        )
        request = request.model_copy(update={"runtime_session_id": runtime_session_id})
        supervisor_attachment = self._bind_cao_attachment_tx(
            connection, supervisor_id=actor_id, request=request
        )
        self._require_managed_worker_work_attachment_tx(
            connection,
            supervisor_id=actor_id,
            worker_id=request.worker_id,
            runtime_session_id=str(request.runtime_session_id),
            supervisor_attachment_id=(
                str(supervisor_attachment["attachment_id"])
                if supervisor_attachment is not None
                else None
            ),
        )
        provider_source_boundary_id = self._provider_instruction_source_boundary_tx(
            connection, str(request.runtime_session_id)
        )

        work_id = _id("wrk")
        attempt_id = _id("att")
        task_id = _id("task")
        context_id = _id("ctx")
        now = utc_now()
        acceptance = [item.strip() for item in request.acceptance if item.strip()]
        non_goals = [item.strip() for item in request.non_goals if item.strip()]
        goal_packet = build_goal_packet(
            work_item_id=work_id,
            version=1,
            title=request.title,
            objective=request.objective,
            maturity=request.maturity.value,
            acceptance=acceptance,
            non_goals=non_goals,
            priority=request.priority,
            requester_id=requester_id,
            supervisor_id=actor_id,
            metadata=request.metadata,
            reason="initial assignment",
            created_by=actor_id,
            source_intent_id=source_intent_id,
            source_directive_id=None,
            correlation_id=source_receipt_id,
            prior_version=None,
            completion_contract=request.completion_contract.value,
            supervisor_attachment=supervisor_attachment,
            dependencies=[item.value for item in request.dependencies],
            managed_task_policy=managed_task_policy,
        )
        goal_digest = goal_packet_digest(goal_packet)
        task_packet = build_task_packet(
            goal_packet_digest_value=goal_digest,
            work_item_id=work_id,
            goal_version=1,
            attempt_id=attempt_id,
            attempt_number=1,
            worker_id=request.worker_id,
            runtime_session_id=request.runtime_session_id,
            supervisor_attachment=supervisor_attachment,
            dependencies=[item.value for item in request.dependencies],
        )
        task_digest = task_packet_digest(task_packet)
        assignment_payload = {
            "work_item_id": work_id,
            "attempt_id": attempt_id,
            "goal_version": 1,
            "generation": 1,
            "title": request.title,
            "objective": request.objective,
            "maturity": request.maturity.value,
            "acceptance": acceptance,
            "non_goals": non_goals,
            "completion_contract": request.completion_contract.value,
            **(
                {"dependencies": [item.value for item in request.dependencies]}
                if request.dependencies
                else {}
            ),
            "priority": request.priority,
            "requester_id": requester_id,
            "supervisor_id": actor_id,
            "metadata": request.metadata,
            **(
                {"managed_task_policy": dict(managed_task_policy)}
                if managed_task_policy is not None
                else {}
            ),
            "goal_packet_digest": goal_digest,
            "task_packet_digest": task_digest,
        }
        connection.execute(
            """
            INSERT INTO work_items(
                id, title, goal_version, state, priority,
                created_by, requester_id, supervisor_id, assigned_worker_id,
                supervisor_attachment_id, managed_worker_thread_id,
                managed_worker_thread_generation, operator_scope, attention_owner,
                generation, suspended_by_work_item_id,
                metadata_json, created_at, updated_at
            ) VALUES(?, ?, 1, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, NULL, ?, ?, ?)
            """,
            (
                work_id,
                request.title,
                WorkState.ACTIVE.value,
                request.priority,
                actor_id,
                requester_id,
                actor_id,
                request.worker_id,
                supervisor_attachment["attachment_id"] if supervisor_attachment else None,
                admission.worker_thread_id if admission is not None else None,
                admission.thread_generation if admission is not None else None,
                str(worker["operator_scope"]),
                AttentionOwner.WORKER.value,
                _json(request.metadata),
                now,
                now,
            ),
        )
        connection.execute(
            """
            INSERT INTO goal_revisions(
                work_item_id, version, title, objective, maturity,
                acceptance_json, non_goals_json, priority, requester_id,
                supervisor_id, metadata_json, packet_json, packet_digest,
                reason, created_by, source_intent_id, source_directive_id,
                correlation_id, prior_version,
                supervisor_attachment_generation,
                supervisor_runtime_session_id, created_at
            ) VALUES(?, 1, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                     'initial assignment', ?, ?, NULL, ?, NULL, ?, ?, ?)
            """,
            (
                work_id,
                request.title,
                request.objective,
                request.maturity.value,
                _json(acceptance),
                _json(non_goals),
                request.priority,
                requester_id,
                actor_id,
                _json(request.metadata),
                _json(goal_packet),
                goal_digest,
                actor_id,
                source_intent_id,
                source_receipt_id,
                (
                    int(goal_packet["supervisor_attachment"]["generation"])
                    if "supervisor_attachment" in goal_packet
                    else None
                ),
                (
                    str(goal_packet["supervisor_attachment"]["runtime_session_id"])
                    if "supervisor_attachment" in goal_packet
                    else None
                ),
                now,
            ),
        )
        connection.execute(
            """
            INSERT INTO attempts(
                id, work_item_id, attempt_number, worker_id,
                runtime_session_id, goal_version, goal_packet_digest,
                task_packet_digest, state, trajectory, evidence_confidence,
                stage, next_boundary, completion_claim_json, created_at, updated_at
            ) VALUES(?, ?, 1, ?, ?, 1, ?, ?, ?, ?, ?, '', '', '{}', ?, ?)
            """,
            (
                attempt_id,
                work_id,
                request.worker_id,
                request.runtime_session_id,
                goal_digest,
                task_digest,
                AttemptState.ASSIGNED.value,
                Trajectory.UNTRACKED.value,
                EvidenceConfidence.UNKNOWN.value,
                now,
                now,
            ),
        )
        connection.execute(
            "INSERT INTO a2a_task_map(task_id, work_item_id, context_id, created_at) "
            "VALUES(?, ?, ?, ?)",
            (task_id, work_id, context_id, now),
        )

        if source_receipt_id and relation == IntentRelation.INTERRUPT:
            assert target is not None
            self._fence_reasoner_turns_tx(connection, str(target["id"]))
            connection.execute(
                """
                    UPDATE work_items
                    SET state = ?, attention_owner = ?, generation = generation + 1,
                        suspended_by_work_item_id = ?, updated_at = ?
                    WHERE id = ?
                    """,
                (
                    WorkState.SUSPENDED.value,
                    AttentionOwner.NONE.value,
                    work_id,
                    now,
                    target["id"],
                ),
            )
            target_attempt = self._latest_attempt_tx(connection, str(target["id"]))
            if target_attempt and target_attempt["state"] not in {
                AttemptState.COMPLETED.value,
                AttemptState.FAILED.value,
                AttemptState.CANCELED.value,
            }:
                connection.execute(
                    "UPDATE attempts SET state = ?, updated_at = ? WHERE id = ?",
                    (AttemptState.SUSPENDED.value, now, target_attempt["id"]),
                )

        message = self._message(
            connection,
            sender_id=actor_id,
            recipient_id=request.worker_id,
            kind=MessageKind.ASSIGNMENT,
            payload=assignment_payload,
            work_item_id=work_id,
            attempt_id=attempt_id,
            goal_version=1,
        )
        self._event(
            connection,
            "work.assigned",
            "work_item",
            work_id,
            actor_id,
            {
                "worker_id": request.worker_id,
                "attempt_id": attempt_id,
                "relation": relation.value if relation else None,
                "source_receipt_id": source_receipt_id or None,
                **(
                    {"provider_source_boundary_id": provider_source_boundary_id}
                    if provider_source_boundary_id
                    else {}
                ),
            },
            causation_id=message["id"],
        )
        return self._work_bundle_tx(connection, work_id)

    def _resume_interrupted_target_tx(
        self,
        connection: sqlite3.Connection,
        completed_work_id: str,
        actor_id: str,
    ) -> dict[str, Any] | None:
        relation = connection.execute(
            """
            SELECT * FROM directives
            WHERE created_work_item_id = ? AND relation = ?
            """,
            (completed_work_id, IntentRelation.INTERRUPT.value),
        ).fetchone()
        if relation is None or not relation["target_work_item_id"]:
            return None
        target = connection.execute(
            "SELECT * FROM work_items WHERE id = ?", (relation["target_work_item_id"],)
        ).fetchone()
        if (
            target is None
            or target["state"] != WorkState.SUSPENDED.value
            or target["suspended_by_work_item_id"] != completed_work_id
        ):
            return None
        now = utc_now()
        self._fence_reasoner_turns_tx(connection, str(target["id"]))
        attempt = self._latest_attempt_tx(connection, str(target["id"]))
        admission: _ManagedWorkerCommandAdmission | None = None
        if attempt is not None:
            try:
                admission = self._admit_managed_worker_command_tx(
                    connection,
                    actor_id=actor_id,
                    kind="resume_interrupted",
                    worker_id=str(attempt["worker_id"]),
                    supervisor_attachment_id=(
                        str(target["supervisor_attachment_id"])
                        if target["supervisor_attachment_id"]
                        else None
                    ),
                    work=target,
                    previous_attempt=attempt,
                )
            except ConflictError as error:
                self._event(
                    connection,
                    "work.resume_deferred",
                    "work_item",
                    str(target["id"]),
                    actor_id,
                    {
                        "after_interrupt": completed_work_id,
                        "reason_code": str((error.details or {}).get("reason_code") or "conflict"),
                    },
                )
                return self._work_bundle_tx(connection, str(target["id"]))

        if (
            admission is not None
            and admission.attempt_mode == "new_attempt"
            and attempt is not None
        ):
            attempt = self._retry_attempt_tx(
                connection,
                actor_id,
                target,
                attempt,
                "Resume exact Work after interrupt completion",
                command_kind="resume_interrupted",
                admission=admission,
            )
            connection.execute(
                "UPDATE work_items SET suspended_by_work_item_id = NULL, updated_at = ? "
                "WHERE id = ?",
                (now, target["id"]),
            )
        else:
            connection.execute(
                """
                UPDATE work_items
                SET state = ?, attention_owner = ?, generation = generation + 1,
                    suspended_by_work_item_id = NULL, updated_at = ?
                WHERE id = ?
                """,
                (
                    WorkState.ACTIVE.value,
                    AttentionOwner.WORKER.value,
                    now,
                    target["id"],
                ),
            )
            if attempt and attempt["state"] == AttemptState.SUSPENDED.value:
                connection.execute(
                    "UPDATE attempts SET state = ?, updated_at = ? WHERE id = ?",
                    (AttemptState.WORKING.value, now, attempt["id"]),
                )
        refreshed = connection.execute(
            "SELECT * FROM work_items WHERE id = ?", (target["id"],)
        ).fetchone()
        assert refreshed is not None
        if attempt and not (admission is not None and admission.attempt_mode == "new_attempt"):
            self._message(
                connection,
                sender_id=actor_id,
                recipient_id=attempt["worker_id"],
                kind=MessageKind.INSTRUCTION,
                payload={
                    "action": "resume",
                    "work_item_id": target["id"],
                    "attempt_id": attempt["id"],
                    "goal_version": target["goal_version"],
                    "generation": refreshed["generation"],
                },
                work_item_id=target["id"],
                attempt_id=attempt["id"],
                goal_version=target["goal_version"],
                idempotency_key=f"resume:{completed_work_id}:{target['id']}",
            )
        self._event(
            connection,
            "work.resumed",
            "work_item",
            str(target["id"]),
            actor_id,
            {"after_interrupt": completed_work_id, "generation": refreshed["generation"]},
        )
        return self._work_bundle_tx(connection, str(target["id"]))

    @staticmethod
    def _source_receipt_view(row: sqlite3.Row) -> dict[str, Any]:
        value = dict(row)
        value["payload"] = _load(value.pop("payload_json"), {})
        return value

    @staticmethod
    def _submitted_intent_view(row: sqlite3.Row) -> dict[str, Any]:
        value = dict(row)
        value["content"] = _load(value.pop("content_json"), {})
        return value

    def _receipt_bundle_tx(self, connection: sqlite3.Connection, receipt_id: str) -> dict[str, Any]:
        receipt = connection.execute(
            "SELECT * FROM source_receipts WHERE id = ?", (receipt_id,)
        ).fetchone()
        if receipt is None:
            raise NotFoundError("source receipt", receipt_id)
        value = self._source_receipt_view(receipt)
        intents = connection.execute(
            "SELECT * FROM submitted_intents WHERE source_receipt_id = ? ORDER BY ordinal",
            (receipt_id,),
        ).fetchall()
        value["intents"] = [self._submitted_intent_view(row) for row in intents]
        value["intent"] = value["intents"][0] if value["intents"] else None
        return value

    @staticmethod
    def _boundary_view(row: sqlite3.Row) -> dict[str, Any]:
        value = dict(row)
        value["metadata"] = _load(value.pop("metadata_json"), {})
        return value

    @staticmethod
    def _fence_reasoner_turns_tx(
        connection: sqlite3.Connection,
        work_id: str,
    ) -> None:
        """Invalidate every decision lease from the generation being replaced."""

        now = utc_now()
        connection.execute(
            """
            UPDATE reasoner_turns
            SET state = ?, updated_at = ?
            WHERE work_item_id = ? AND state = ?
            """,
            (
                ReasonerTurnState.ABANDONED.value,
                now,
                work_id,
                ReasonerTurnState.LEASED.value,
            ),
        )

    def _cancel_work_tx(
        self,
        connection: sqlite3.Connection,
        *,
        actor_id: str,
        work: sqlite3.Row,
        reason: str,
        directive_id: str | None = None,
        close_request_digest: str = "",
        close_attachment_generation: int | None = None,
    ) -> dict[str, Any]:
        if work["state"] == WorkState.COMPLETED.value:
            raise ConflictError("completed work cannot be canceled")
        if work["state"] == WorkState.CANCELED.value:
            return self._work_bundle_tx(connection, str(work["id"]))
        attempt = self._latest_attempt_tx(connection, str(work["id"]))
        now = utc_now()
        self._fence_reasoner_turns_tx(connection, str(work["id"]))
        connection.execute(
            """
            UPDATE work_items
            SET state = ?, attention_owner = ?,
                generation = generation + 1,
                user_needed_boundary_id = NULL, paused_boundary_id = NULL, updated_at = ?
            WHERE id = ?
            """,
            (WorkState.CANCELED.value, AttentionOwner.NONE.value, now, work["id"]),
        )
        message: dict[str, Any] | None = None
        if attempt:
            connection.execute(
                "UPDATE attempts SET state = ?, updated_at = ? WHERE id = ?",
                (AttemptState.CANCELED.value, now, attempt["id"]),
            )
            runtime = (
                connection.execute(
                    """
                    SELECT r.id
                    FROM runtime_sessions AS r
                    JOIN principals AS p ON p.id = r.principal_id
                    WHERE r.id = ? AND r.principal_id = ? AND p.enabled = 1
                      AND r.state NOT IN (?, ?, ?)
                    """,
                    (
                        attempt["runtime_session_id"],
                        attempt["worker_id"],
                        RuntimeState.STOPPED.value,
                        RuntimeState.MISSING.value,
                        RuntimeState.FAILED.value,
                    ),
                ).fetchone()
                if attempt["runtime_session_id"]
                else None
            )
            if runtime is not None:
                message = self._message(
                    connection,
                    sender_id=actor_id,
                    recipient_id=attempt["worker_id"],
                    kind=MessageKind.CANCEL,
                    payload={"reason": reason, "directive_id": directive_id},
                    work_item_id=work["id"],
                    attempt_id=attempt["id"],
                    goal_version=work["goal_version"],
                    idempotency_key=f"cancel:{directive_id}" if directive_id else "",
                )
            else:
                # Cancellation is authoritative even when the Worker has
                # already stopped.  Do not resurrect it merely to deliver an
                # informational cancel packet; terminalize any unresolved
                # delivery for this Attempt with a fixed, non-conversational
                # outcome instead.
                connection.execute(
                    """
                    UPDATE message_deliveries
                    SET state = ?, next_attempt_at = ?, lease_until = NULL,
                        owner_token = '', last_error = ?, updated_at = ?
                    WHERE message_id IN (
                        SELECT id FROM messages WHERE attempt_id = ?
                    ) AND state IN (?, ?, ?, ?, ?)
                    """,
                    (
                        DeliveryState.DEAD.value,
                        now,
                        "work_canceled",
                        now,
                        attempt["id"],
                        DeliveryState.QUEUED.value,
                        DeliveryState.LEASED.value,
                        DeliveryState.DISPATCHED.value,
                        DeliveryState.DELIVERED.value,
                        DeliveryState.ACKNOWLEDGED.value,
                    ),
                )
                self._event(
                    connection,
                    "work.cancel_notification_skipped",
                    "work_item",
                    str(work["id"]),
                    actor_id,
                    {
                        "attempt_id": str(attempt["id"]),
                        "reason_code": "runtime_unavailable",
                    },
                )
        if directive_id:
            connection.execute(
                """
                UPDATE directives
                SET state = ?, handled_by = ?, handled_at = ?, updated_at = ?
                WHERE id = ?
                """,
                (DirectiveState.HANDLED.value, actor_id, now, now, directive_id),
            )
        event_data: dict[str, Any] = {
            "reason": reason,
            "directive_id": directive_id,
        }
        if close_request_digest:
            event_data["close_request_digest"] = close_request_digest
            event_data["closed_generation"] = close_attachment_generation
        canceled_sequence = self._event(
            connection,
            "work.canceled",
            "work_item",
            str(work["id"]),
            actor_id,
            event_data,
            causation_id=message["id"] if message else "",
        )
        # Cancellation is terminal task authority, not a fabricated CAO
        # review.  Bind every still-open Boundary to the exact cancellation
        # event so it remains visible as history but can no longer be selected
        # as actionable work or poison readiness after the Worker lifecycle
        # has ended.
        connection.execute(
            """
            INSERT INTO boundary_supersessions(
                boundary_id, boundary_event_sequence,
                superseding_event_sequence, reason, created_at
            )
            SELECT boundary.id, boundary_event.sequence, ?, 'work_canceled', ?
            FROM boundaries AS boundary
            JOIN events AS boundary_event
              ON boundary_event.event_type = 'boundary.recorded'
             AND boundary_event.aggregate_type = 'work_item'
             AND boundary_event.aggregate_id = boundary.work_item_id
             AND json_extract(boundary_event.data_json, '$.boundary_id') = boundary.id
            LEFT JOIN boundary_dispositions AS disposition
              ON disposition.boundary_id = boundary.id
            LEFT JOIN boundary_supersessions AS supersession
              ON supersession.boundary_id = boundary.id
            WHERE boundary.work_item_id = ?
              AND disposition.id IS NULL
              AND supersession.boundary_id IS NULL
              AND boundary.generation < (
                    SELECT generation FROM work_items WHERE id = ?
                  )
              AND (
                  SELECT COUNT(*) FROM events AS exact_boundary_event
                  WHERE exact_boundary_event.event_type = 'boundary.recorded'
                    AND exact_boundary_event.aggregate_type = 'work_item'
                    AND exact_boundary_event.aggregate_id = boundary.work_item_id
                    AND json_extract(
                          exact_boundary_event.data_json, '$.boundary_id'
                        ) = boundary.id
              ) = 1
            """,
            (canceled_sequence, now, work["id"], work["id"]),
        )
        self._resume_interrupted_target_tx(connection, str(work["id"]), actor_id)
        return self._work_bundle_tx(connection, str(work["id"]))

    def _runtime_recovery_retry_target_tx(
        self,
        connection: sqlite3.Connection,
        *,
        work: sqlite3.Row,
        attempt: sqlite3.Row,
        boundary: sqlite3.Row,
        reconcile_unknown: bool = False,
    ) -> _ManagedWorkerCommandAdmission:
        """Advance one active logical thread after a fenced runtime failure.

        A normal recovery requires proven non-delivery before Worker MCP.  An
        explicit reconciliation instead preserves the old unknown outcome and
        appends one inspect-first continuation to the same Codex native thread.
        Neither path changes Worker identity or reactivates an old enrollment.
        """

        def outcome_unknown(message: str) -> NoReturn:
            raise ConflictError(
                message,
                reason_code="worker_instruction_outcome_unknown",
                recovery_state="system_reconciliation_required",
                retryable=False,
            )

        metadata = _load(boundary["metadata_json"], {})
        reason = str(metadata.get("reason", ""))
        old_spec = connection.execute(
            """
            SELECT spec.*, thread.id AS worker_thread_id,
                   thread.state AS thread_state,
                   thread.generation AS thread_generation,
                   epoch.id AS epoch_id,
                   epoch.connection_generation AS epoch_connection_generation,
                   epoch.runtime_session_id AS epoch_runtime_session_id,
                   epoch.enrollment_id AS epoch_enrollment_id,
                   runtime.adapter AS runtime_adapter,
                   runtime.endpoint AS runtime_endpoint,
                   runtime.native_session_id AS runtime_native_session_id,
                   runtime.metadata_json AS runtime_metadata_json
            FROM managed_worker_specs AS spec
            JOIN managed_worker_threads AS thread
              ON thread.managed_spec_id = spec.id
            JOIN managed_worker_thread_epochs AS epoch
              ON epoch.thread_id = thread.id
             AND epoch.generation = thread.generation
             AND epoch.retired_at IS NULL
            JOIN runtime_sessions AS runtime
              ON runtime.id = spec.runtime_session_id
             AND runtime.principal_id = spec.principal_id
            JOIN cao_session_attachments AS source_attachment
              ON source_attachment.id = spec.attachment_id
            JOIN cao_session_attachments AS supervisor_attachment
              ON supervisor_attachment.id = ?
             AND supervisor_attachment.principal_id = source_attachment.principal_id
             AND supervisor_attachment.project_digest = source_attachment.project_digest
            WHERE spec.runtime_session_id = ?
              AND spec.enrollment_id = epoch.enrollment_id
              AND epoch.runtime_session_id = spec.runtime_session_id
              AND spec.principal_id = ?
              AND spec.state = 'enabled'
              AND thread.state = 'active'
            ORDER BY spec.created_at DESC, spec.id DESC
            LIMIT 2
            """,
            (
                work["supervisor_attachment_id"],
                attempt["runtime_session_id"],
                attempt["worker_id"],
            ),
        ).fetchall()
        if len(old_spec) != 1:
            outcome_unknown("managed runtime recovery provenance is unavailable")
        source = old_spec[0]
        pre_dispatch_timeout = bool(
            isinstance(metadata, Mapping) and metadata.get("pre_dispatch_timeout") is True
        )
        proof = connection.execute(
            """
            SELECT boundary.id, boundary.metadata_json,
                   boundary.work_item_id, boundary.attempt_id,
                   boundary.generation AS boundary_generation,
                   attempt.worker_id, attempt.runtime_session_id,
                   attempt.state AS attempt_state,
                   work.goal_version, work.state AS work_state,
                   work.attention_owner,
                   work.generation AS work_generation,
                   work.managed_worker_thread_id,
                   work.managed_worker_thread_generation
            FROM boundaries AS boundary
            JOIN attempts AS attempt ON attempt.id = boundary.attempt_id
            JOIN work_items AS work ON work.id = boundary.work_item_id
            WHERE boundary.id = ? AND boundary.work_item_id = ?
              AND boundary.attempt_id = ?
            """,
            (boundary["id"], work["id"], attempt["id"]),
        ).fetchone()
        assignment_not_submitted = bool(
            proof is not None and _exact_assignment_not_submitted_is_proven(connection, proof)
        )
        if reconcile_unknown:
            if (
                str(boundary["recovery_action"] or "") != "reconcile_continue_same_thread"
                or proof is None
                or not _same_thread_reconciliation_is_executable(
                    connection,
                    proof,
                    reason=reason,
                )
            ):
                outcome_unknown("post-MCP reconciliation proof no longer matches")
        elif (
            str(boundary["recovery_action"] or "") != "dispose_continue_or_correct"
            or proof is None
            or not _same_thread_recovery_is_executable(
                connection,
                proof,
                reason=reason,
            )
        ):
            outcome_unknown("same-thread recovery proof no longer matches")

        unsafe_activity = connection.execute(
            """
            SELECT 1
            WHERE (
                ? = 0 AND (
                    EXISTS (
                        SELECT 1 FROM messages
                        WHERE attempt_id = ? AND sender_id = ?
                          AND kind IN (
                            'question', 'blocker', 'progress', 'artifact',
                            'completion_claim'
                          )
                    ) OR EXISTS (
                        SELECT 1 FROM artifacts WHERE attempt_id = ?
                    )
                )
            ) OR EXISTS (
                SELECT 1 FROM effect_operations
                WHERE principal_id = ? AND status IN ('started', 'unknown')
            )
            LIMIT 1
            """,
            (
                int(reason == "worker_turn_completed_without_terminal_report"),
                attempt["id"],
                attempt["worker_id"],
                attempt["id"],
                attempt["worker_id"],
            ),
        ).fetchone()
        if unsafe_activity is not None:
            outcome_unknown("failed runtime has durable Worker activity")

        sibling_work = connection.execute(
            """
            SELECT 1 FROM work_items
            WHERE assigned_worker_id = ? AND id <> ?
              AND state NOT IN ('completed', 'canceled', 'failed')
              AND NOT (
                state = 'waiting_user'
                AND EXISTS (
                    SELECT 1 FROM attempts AS latest
                    WHERE latest.work_item_id = work_items.id
                      AND latest.state = 'completed'
                      AND latest.attempt_number = (
                          SELECT MAX(candidate.attempt_number)
                          FROM attempts AS candidate
                          WHERE candidate.work_item_id = work_items.id
                      )
                )
                AND NOT EXISTS (
                    SELECT 1 FROM boundaries AS open_boundary
                    LEFT JOIN boundary_dispositions AS disposition
                      ON disposition.boundary_id = open_boundary.id
                    LEFT JOIN boundary_supersessions AS supersession
                      ON supersession.boundary_id = open_boundary.id
                    WHERE open_boundary.work_item_id = work_items.id
                      AND disposition.id IS NULL
                      AND supersession.boundary_id IS NULL
                )
              )
            LIMIT 1
            """,
            (attempt["worker_id"], work["id"]),
        ).fetchone()
        if sibling_work is not None:
            outcome_unknown("managed Worker has another unsettled Work")

        delivery_rows = connection.execute(
            """
            SELECT delivery.message_id, delivery.recipient_id, delivery.state,
                   delivery.generation, delivery.runtime_session_id,
                   delivery.last_error, message.kind AS message_kind
            FROM message_deliveries AS delivery
            JOIN messages AS message ON message.id = delivery.message_id
            WHERE message.attempt_id = ? AND delivery.recipient_id = ?
            ORDER BY message.sequence, delivery.recipient_id
            """,
            (attempt["id"], attempt["worker_id"]),
        ).fetchall()
        assignment_deliveries = [
            delivery
            for delivery in delivery_rows
            if str(delivery["message_kind"]) == MessageKind.ASSIGNMENT.value
        ]
        if len(assignment_deliveries) != 1:
            outcome_unknown("failed runtime Assignment delivery proof is unavailable")
        if not reconcile_unknown:
            for delivery in delivery_rows:
                delivery_state = str(delivery["state"])
                if delivery_state in {
                    DeliveryState.QUEUED.value,
                    DeliveryState.LEASED.value,
                }:
                    if str(delivery["runtime_session_id"] or "") != str(
                        attempt["runtime_session_id"]
                    ):
                        outcome_unknown("failed runtime delivery ownership is ambiguous")
                    continue
                if (
                    pre_dispatch_timeout
                    and delivery_state == DeliveryState.DEAD.value
                    and str(delivery["last_error"] or "") == "runtime_dispatch_failed"
                    and str(delivery["runtime_session_id"] or "")
                    == str(attempt["runtime_session_id"])
                ):
                    continue
                if (
                    assignment_not_submitted
                    and delivery_state == DeliveryState.DEAD.value
                    and str(delivery["last_error"] or "") == "runtime_dispatch_pre_submit_failed"
                    and str(delivery["runtime_session_id"] or "")
                    == str(attempt["runtime_session_id"])
                ):
                    continue
                if _has_exact_pre_mcp_closed_delivery_event(
                    connection,
                    boundary_id=str(boundary["id"]),
                    message_id=str(delivery["message_id"]),
                    recipient_id=str(delivery["recipient_id"]),
                    runtime_session_id=str(delivery["runtime_session_id"] or ""),
                    delivery_generation=int(delivery["generation"]),
                    boundary_reason=reason,
                    delivery_state=delivery_state,
                    last_error=str(delivery["last_error"] or ""),
                ) and str(delivery["runtime_session_id"] or "") == str(
                    attempt["runtime_session_id"]
                ):
                    continue
                outcome_unknown("failed runtime has an unresolved delivery outcome")

        competing_enrollment = connection.execute(
            """
            SELECT enrollment.id
            FROM worker_enrollments AS enrollment
            WHERE enrollment.principal_id = ? AND enrollment.id <> ?
              AND (
                enrollment.state IN ('awaiting_handshake', 'ready', 'stale')
                OR EXISTS (
                    SELECT 1 FROM runtime_credentials AS credential
                    WHERE credential.enrollment_id = enrollment.id
                      AND credential.state = 'active'
                )
                OR EXISTS (
                    SELECT 1 FROM runtime_enrollment_tickets AS ticket
                    WHERE ticket.enrollment_id = enrollment.id
                      AND ticket.state = 'pending'
                )
              )
            LIMIT 1
            """,
            (attempt["worker_id"], source["epoch_enrollment_id"]),
        ).fetchone()
        if competing_enrollment is not None:
            outcome_unknown("managed Worker has another live enrollment")

        # Exhaustion is intentionally evaluated only after every unknown-
        # outcome fence. A second failed epoch that crossed the Worker or
        # effect boundary must remain a manual-reconciliation case; it is not
        # safely reducible to ordinary launch exhaustion.
        prior_recovery = connection.execute(
            """
            SELECT 1 FROM events
            WHERE event_type = 'managed_worker_thread.recovery_epoch_advanced'
              AND aggregate_type = 'managed_worker_thread'
              AND aggregate_id = ?
              AND json_extract(data_json, '$.work_item_id') = ?
            LIMIT 1
            """,
            (source["worker_thread_id"], work["id"]),
        ).fetchone()
        if prior_recovery is not None and not reconcile_unknown and not assignment_not_submitted:
            raise ConflictError(
                "managed Worker launch recovery is exhausted",
                reason_code="worker_launch_recovery_exhausted",
                recovery_state="system_unavailable",
            )

        now = utc_now()
        if reason == "worker_turn_completed_without_terminal_report":
            # The provider turn ended authoritatively, but the task outcome did
            # not. Retire only that spent connection route before creating the
            # inspect-first continuation. The provider-native thread remains
            # the continuation target and every Worker report/artifact remains
            # durable evidence on the source Attempt.
            connection.execute(
                """
                UPDATE runtime_credentials
                SET state = 'revoked', revoked_at = ?, updated_at = ?
                WHERE enrollment_id = ? AND state = 'active'
                """,
                (now, now, source["epoch_enrollment_id"]),
            )
            connection.execute(
                """
                UPDATE worker_enrollments
                SET state = 'revoked', revoked_at = ?, updated_at = ?
                WHERE id = ? AND state IN ('awaiting_handshake', 'ready', 'stale')
                """,
                (now, now, source["epoch_enrollment_id"]),
            )
            connection.execute(
                """
                UPDATE runtime_sessions
                SET state = 'stopped', updated_at = ?
                WHERE id = ? AND state NOT IN ('failed', 'missing', 'stopped')
                """,
                (now, source["epoch_runtime_session_id"]),
            )
        runtime_id, enrollment_id, epoch_id = _id("run"), _id("enr"), _id("mwe")
        next_connection_generation = int(source["epoch_connection_generation"]) + 1
        if (
            connection.execute(
                """
            UPDATE managed_worker_thread_epochs
            SET retired_at = ?
            WHERE id = ? AND thread_id = ? AND generation = ?
              AND connection_generation = ?
              AND retired_at IS NULL
            """,
                (
                    now,
                    source["epoch_id"],
                    source["worker_thread_id"],
                    source["thread_generation"],
                    source["epoch_connection_generation"],
                ),
            ).rowcount
            != 1
        ):
            outcome_unknown("managed Worker recovery epoch changed")
        connection.execute(
            """
            INSERT INTO runtime_sessions(
                id, principal_id, adapter, endpoint, native_session_id, state,
                lease_expires_at, heartbeat_at, metadata_json,
                created_at, updated_at
            ) VALUES(?, ?, ?, ?, ?, 'starting', ?, ?, ?, ?, ?)
            """,
            (
                runtime_id,
                attempt["worker_id"],
                source["runtime_adapter"],
                source["runtime_endpoint"],
                (
                    source["runtime_native_session_id"]
                    if pre_dispatch_timeout or assignment_not_submitted or reconcile_unknown
                    else ""
                ),
                utc_after(86400),
                now,
                source["runtime_metadata_json"],
                now,
                now,
            ),
        )
        connection.execute(
            """
            INSERT INTO worker_enrollments(
                id, principal_id, runtime_session_id, state, generation, managed,
                required_tools_digest, discovered_tools_digest, protocol_version,
                heartbeat_sequence, discovered_at, heartbeat_at, lease_expires_at,
                revoked_at, created_at, updated_at
            ) VALUES(?, ?, ?, 'awaiting_handshake', 0, 1, ?, '', '', 0,
                     NULL, NULL, ?, NULL, ?, ?)
            """,
            (
                enrollment_id,
                attempt["worker_id"],
                runtime_id,
                worker_mcp_tool_contract_digest(),
                utc_after(86400),
                now,
                now,
            ),
        )
        if (
            connection.execute(
                """
            UPDATE managed_worker_specs
            SET runtime_session_id = ?, enrollment_id = ?, updated_at = ?
            WHERE id = ? AND state = 'enabled'
              AND runtime_session_id = ? AND enrollment_id = ?
            """,
                (
                    runtime_id,
                    enrollment_id,
                    now,
                    source["id"],
                    source["epoch_runtime_session_id"],
                    source["epoch_enrollment_id"],
                ),
            ).rowcount
            != 1
        ):
            outcome_unknown("managed Worker recovery spec changed")
        connection.execute(
            """
            INSERT INTO managed_worker_thread_epochs(
                id, thread_id, generation, connection_generation,
                runtime_session_id,
                enrollment_id, created_at, retired_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, NULL)
            """,
            (
                epoch_id,
                source["worker_thread_id"],
                source["thread_generation"],
                next_connection_generation,
                runtime_id,
                enrollment_id,
                now,
            ),
        )
        self._event(
            connection,
            (
                "managed_worker_thread.reconciliation_epoch_advanced"
                if reconcile_unknown
                else "managed_worker_thread.recovery_epoch_advanced"
            ),
            "managed_worker_thread",
            str(source["worker_thread_id"]),
            str(work["supervisor_id"] or work["created_by"]),
            {
                "thread_generation": int(source["thread_generation"]),
                "connection_generation": next_connection_generation,
                "work_item_id": str(work["id"]),
                "source_attempt_id": str(attempt["id"]),
                "source_boundary_id": str(boundary["id"]),
                **({"preserved_unknown_outcome": True} if reconcile_unknown else {}),
            },
        )
        return _ManagedWorkerCommandAdmission(
            worker_thread_id=str(source["worker_thread_id"]),
            thread_generation=int(source["thread_generation"]),
            connection_generation=next_connection_generation,
            runtime_session_id=runtime_id,
            enrollment_id=enrollment_id,
            route="advanced",
            attempt_mode="new_attempt",
        )

    def _retry_attempt_tx(
        self,
        connection: sqlite3.Connection,
        actor_id: str,
        work: sqlite3.Row,
        previous: sqlite3.Row,
        reason: str,
        *,
        worker_id: str | None = None,
        runtime_session_id: str | None = None,
        command_kind: _ManagedWorkerCommandKind = "retry",
        admission: _ManagedWorkerCommandAdmission | None = None,
        command_context: Mapping[str, Any] | None = None,
    ) -> sqlite3.Row:
        if command_kind != "resume_paused":
            require_not_paused(work)
        goal = self._current_goal_tx(connection, work)
        continuation_boundary = self._current_user_needed_boundary_tx(
            connection,
            actor_id=actor_id,
            work=work,
            source_attempt=previous,
        )
        target_worker = worker_id or str(previous["worker_id"])
        target_runtime = (
            runtime_session_id
            if runtime_session_id is not None
            else (
                previous["runtime_session_id"] if target_worker == previous["worker_id"] else None
            )
        )
        worker = connection.execute(
            "SELECT * FROM principals WHERE id = ?", (target_worker,)
        ).fetchone()
        if (
            worker is None
            or worker["role"] != PrincipalRole.WORKER.value
            or not bool(worker["enabled"])
        ):
            raise ValidationError("retry worker must be an enabled Worker")
        if str(worker["operator_scope"]) != str(work["operator_scope"]):
            raise ConflictError("retry Worker operator scope does not match WorkItem")
        if admission is None:
            admission = self._admit_managed_worker_command_tx(
                connection,
                actor_id=actor_id,
                kind=command_kind,
                worker_id=target_worker,
                supervisor_attachment_id=(
                    str(work["supervisor_attachment_id"])
                    if work["supervisor_attachment_id"]
                    else None
                ),
                work=work,
                previous_attempt=previous,
            )
        target_runtime = (
            admission.runtime_session_id
            if admission is not None
            else self._bind_ready_worker_runtime_tx(
                connection,
                worker_id=target_worker,
                runtime_session_id=(str(target_runtime) if target_runtime else None),
            )
        )
        self._require_managed_worker_work_attachment_tx(
            connection,
            supervisor_id=actor_id,
            worker_id=target_worker,
            runtime_session_id=target_runtime,
            supervisor_attachment_id=(
                str(work["supervisor_attachment_id"]) if work["supervisor_attachment_id"] else None
            ),
        )
        provider_source_boundary_id = self._provider_instruction_source_boundary_tx(
            connection, target_runtime
        )
        number = int(previous["attempt_number"]) + 1
        now = utc_now()
        self._fence_reasoner_turns_tx(connection, str(work["id"]))
        if previous["state"] not in {
            AttemptState.COMPLETED.value,
            AttemptState.FAILED.value,
            AttemptState.CANCELED.value,
        }:
            connection.execute(
                "UPDATE attempts SET state = ?, updated_at = ? WHERE id = ?",
                (AttemptState.CANCELED.value, now, previous["id"]),
            )
        attempt_id = _id("att")
        goal_digest = str(goal["packet_digest"])
        goal_packet = _load(goal["packet_json"], {})
        if not isinstance(goal_packet, Mapping):
            raise RuntimeError("work item goal packet is invalid")
        sealed_supervisor_attachment = goal_packet.get("supervisor_attachment")
        if sealed_supervisor_attachment is not None and not isinstance(
            sealed_supervisor_attachment, Mapping
        ):
            raise RuntimeError("work item goal attachment packet is invalid")
        task_packet = build_task_packet(
            goal_packet_digest_value=goal_digest,
            work_item_id=str(work["id"]),
            goal_version=int(work["goal_version"]),
            attempt_id=attempt_id,
            attempt_number=number,
            worker_id=target_worker,
            runtime_session_id=(str(target_runtime) if target_runtime else None),
            # A retry is another Attempt under the same immutable Goal
            # revision.  The CAO bridge runtime may have been replaced since
            # that Goal was sealed, so using the attachment's current runtime
            # here makes the Task digest impossible to reconstruct.  Reuse the
            # exact attachment packet already committed into the Goal packet.
            supervisor_attachment=sealed_supervisor_attachment,
            dependencies=[str(item) for item in goal_packet.get("dependencies", [])],
        )
        task_digest = task_packet_digest(task_packet)
        next_thread_id = (
            admission.worker_thread_id
            if admission is not None
            else (
                work["managed_worker_thread_id"]
                if str(work["assigned_worker_id"]) == target_worker
                else None
            )
        )
        next_thread_generation = (
            admission.thread_generation
            if admission is not None
            else (
                work["managed_worker_thread_generation"]
                if str(work["assigned_worker_id"]) == target_worker
                else None
            )
        )
        if continuation_boundary is not None:
            prepared = connection.execute(
                """
                UPDATE work_items
                SET assigned_worker_id = ?, managed_worker_thread_id = ?,
                    managed_worker_thread_generation = ?, updated_at = ?
                WHERE id = ? AND state = 'user_needed' AND attention_owner = 'user'
                  AND generation = ? AND user_needed_boundary_id = ?
                """,
                (
                    target_worker,
                    next_thread_id,
                    next_thread_generation,
                    now,
                    work["id"],
                    work["generation"],
                    continuation_boundary["id"],
                ),
            ).rowcount
            if prepared != 1:
                raise ConflictError(
                    "requester-input continuation lost its preparation fence",
                    reason_code="worker_command_generation_conflict",
                    retryable=False,
                )
        else:
            connection.execute(
                """
                UPDATE work_items
                SET assigned_worker_id = ?, managed_worker_thread_id = ?,
                    managed_worker_thread_generation = ?, state = ?, attention_owner = ?,
                    paused_boundary_id = CASE WHEN ? THEN NULL ELSE paused_boundary_id END,
                    generation = generation + 1, updated_at = ?
                WHERE id = ?
                """,
                (
                    target_worker,
                    next_thread_id,
                    next_thread_generation,
                    WorkState.ACTIVE.value,
                    AttentionOwner.WORKER.value,
                    command_kind == "resume_paused",
                    now,
                    work["id"],
                ),
            )
        connection.execute(
            """
            INSERT INTO attempts(
                id, work_item_id, attempt_number, worker_id,
                runtime_session_id, goal_version, goal_packet_digest,
                task_packet_digest, state, trajectory, evidence_confidence,
                stage, next_boundary, completion_claim_json, created_at, updated_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, '', '', '{}', ?, ?)
            """,
            (
                attempt_id,
                work["id"],
                number,
                target_worker,
                target_runtime,
                work["goal_version"],
                goal_digest,
                task_digest,
                AttemptState.ASSIGNED.value,
                Trajectory.UNTRACKED.value,
                EvidenceConfidence.UNKNOWN.value,
                now,
                now,
            ),
        )
        sealed_command_context = dict(command_context or {})
        if sealed_command_context:
            allowed_command_fields = {
                "action",
                "reason",
                "instruction",
                "source_boundary_id",
                "directive_id",
            }
            if set(sealed_command_context) - allowed_command_fields or any(
                not isinstance(value, str) for value in sealed_command_context.values()
            ):
                raise ValidationError("replacement Assignment command context is invalid")
            _require_worker_safe_task_payload({"command": sealed_command_context})
        message = self._message(
            connection,
            sender_id=actor_id,
            recipient_id=target_worker,
            kind=MessageKind.ASSIGNMENT,
            payload={
                "work_item_id": work["id"],
                "attempt_id": attempt_id,
                "goal_version": work["goal_version"],
                "generation": int(work["generation"]) + 1,
                "objective": goal["objective"],
                "maturity": goal["maturity"],
                "acceptance": _load(goal["acceptance_json"], []),
                "non_goals": _load(goal["non_goals_json"], []),
                "completion_contract": str(
                    goal_packet.get(
                        "completion_contract",
                        CompletionContract.LEGACY_UNCLASSIFIED.value,
                    )
                ),
                **(
                    {"dependencies": [str(item) for item in goal_packet.get("dependencies", [])]}
                    if goal_packet.get("dependencies")
                    else {}
                ),
                **(
                    {"managed_task_policy": goal_packet["managed_task_policy"]}
                    if "managed_task_policy" in goal_packet
                    else {}
                ),
                "reason": reason,
                **({"command": sealed_command_context} if sealed_command_context else {}),
                "goal_packet_digest": goal_digest,
                "task_packet_digest": task_digest,
            },
            work_item_id=work["id"],
            attempt_id=attempt_id,
            goal_version=work["goal_version"],
            idempotency_key=f"retry:{previous['id']}",
        )
        row: sqlite3.Row | None = connection.execute(
            "SELECT * FROM attempts WHERE id = ?", (attempt_id,)
        ).fetchone()
        assert row is not None
        if continuation_boundary is not None:
            self._consume_user_needed_boundary_tx(
                connection,
                actor_id=actor_id,
                work=work,
                boundary=continuation_boundary,
                source_attempt=previous,
                successor_attempt=row,
                successor_generation=int(work["generation"]) + 1,
                message_id=str(message["id"]),
                now=now,
            )
        self._event(
            connection,
            "attempt.created",
            "attempt",
            attempt_id,
            actor_id,
            {
                "work_item_id": work["id"],
                "number": number,
                "reason": reason,
                **(
                    {"provider_source_boundary_id": provider_source_boundary_id}
                    if provider_source_boundary_id
                    else {}
                ),
            },
            causation_id=str(message["id"]),
        )
        return row

    def _work_bundle_tx(self, connection: sqlite3.Connection, work_id: str) -> dict[str, Any]:
        work = connection.execute("SELECT * FROM work_items WHERE id = ?", (work_id,)).fetchone()
        if work is None:
            return {}
        value = dict(work)
        value.pop("acceptance_json", None)
        value.pop("non_goals_json", None)
        value.pop("user_needed_boundary_id", None)
        value["metadata"] = _load(value.pop("metadata_json"), {})
        value["supervision_pause"] = pause_view_tx(connection, work)
        revisions = connection.execute(
            "SELECT * FROM goal_revisions WHERE work_item_id = ? ORDER BY version",
            (work_id,),
        ).fetchall()
        value["goal_history"] = [
            {
                **dict(row),
                "acceptance": _load(row["acceptance_json"], []),
                "non_goals": _load(row["non_goals_json"], []),
                "packet": _load(row["packet_json"], {}),
            }
            for row in revisions
        ]
        for revision in value["goal_history"]:
            revision.pop("acceptance_json", None)
            revision.pop("non_goals_json", None)
            revision.pop("packet_json", None)
            if goal_packet_digest(revision["packet"]) != revision["packet_digest"]:
                raise RuntimeError("work item goal packet digest is invalid")
        value["goal_revisions"] = list(value["goal_history"])
        current_goal = next(
            (
                revision
                for revision in value["goal_history"]
                if int(revision["version"]) == int(value["goal_version"])
            ),
            None,
        )
        if current_goal is None:
            raise RuntimeError("work item current goal pointer is invalid")
        value["objective"] = current_goal["objective"]
        value["maturity"] = current_goal["maturity"]
        value["acceptance"] = list(current_goal["acceptance"])
        value["non_goals"] = list(current_goal["non_goals"])
        completion_contract = str(
            current_goal["packet"].get(
                "completion_contract",
                CompletionContract.LEGACY_UNCLASSIFIED.value,
            )
        )
        try:
            CompletionContract(completion_contract)
        except ValueError as error:
            raise RuntimeError("work item completion contract is invalid") from error
        value["completion_contract"] = completion_contract
        value["current_goal_revision"] = dict(current_goal)
        attempts = connection.execute(
            "SELECT * FROM attempts WHERE work_item_id = ? ORDER BY attempt_number",
            (work_id,),
        ).fetchall()
        value["attempts"] = [self._attempt_view(row) for row in attempts]
        value["current_attempt"] = value["attempts"][-1] if value["attempts"] else None
        value["worker_outputs"] = [
            output_view(row)
            for row in connection.execute(
                "SELECT * FROM worker_output_receipts WHERE work_item_id = ? ORDER BY sequence",
                (work_id,),
            ).fetchall()
        ]
        value["delivery_state"] = self._completion_delivery_state_tx(
            connection,
            contract=completion_contract,
            attempt=(attempts[-1] if attempts else None),
        )
        directives = connection.execute(
            """
            SELECT * FROM directives
            WHERE target_work_item_id = ? OR created_work_item_id = ?
            ORDER BY created_at, id
            """,
            (work_id, work_id),
        ).fetchall()
        value["directives"] = [dict(row) for row in directives]
        artifacts = connection.execute(
            "SELECT * FROM artifacts WHERE work_item_id = ? ORDER BY created_at", (work_id,)
        ).fetchall()
        value["artifacts"] = [self._artifact_view(row) for row in artifacts]
        if attempts and value["current_attempt"] is not None:
            value["current_attempt"]["activity"] = self._attempt_activity_tx(
                connection, attempts[-1]
            )
        reviews = connection.execute(
            "SELECT * FROM reviews WHERE work_item_id = ? ORDER BY created_at", (work_id,)
        ).fetchall()
        value["reviews"] = [self._review_view(row) for row in reviews]
        requester_decisions = connection.execute(
            "SELECT * FROM requester_decisions WHERE work_item_id = ? ORDER BY created_at",
            (work_id,),
        ).fetchall()
        value["requester_decisions"] = [
            self._requester_decision_view(row) for row in requester_decisions
        ]
        close_receipt = connection.execute(
            "SELECT * FROM work_close_receipts WHERE work_item_id = ?",
            (work_id,),
        ).fetchone()
        if close_receipt is None:
            value["closure"] = {
                "state": (
                    "awaiting-explicit-close"
                    if value["state"] == WorkState.COMPLETED.value
                    else "open"
                ),
                "open_delivery_count": connection.execute(
                    """
                    SELECT COUNT(*) AS count
                    FROM message_deliveries AS d
                    JOIN messages AS m ON m.id = d.message_id
                    WHERE m.work_item_id = ?
                      AND d.state IN ('queued', 'leased', 'dispatched', 'delivered', 'acknowledged')
                    """,
                    (work_id,),
                ).fetchone()["count"],
            }
        else:
            value["closure"] = self._close_receipt_view(close_receipt)
        boundaries = connection.execute(
            "SELECT * FROM boundaries WHERE work_item_id = ? ORDER BY created_at, id",
            (work_id,),
        ).fetchall()
        boundary_views: list[dict[str, Any]] = []
        for boundary in boundaries:
            boundary_view = self._boundary_view(boundary)
            disposition = connection.execute(
                "SELECT * FROM boundary_dispositions WHERE boundary_id = ?",
                (boundary["id"],),
            ).fetchone()
            supersession = connection.execute(
                "SELECT reason, created_at FROM boundary_supersessions WHERE boundary_id = ?",
                (boundary["id"],),
            ).fetchone()
            boundary_view["disposition"] = dict(disposition) if disposition else None
            boundary_view["supersession"] = dict(supersession) if supersession else None
            boundary_views.append(boundary_view)
        value["boundaries"] = boundary_views
        value["open_boundaries"] = [
            boundary
            for boundary in boundary_views
            if boundary["disposition"] is None and boundary["supersession"] is None
        ]
        if attempts and value["current_attempt"] is not None:
            value["current_attempt"]["assignment_delivery"] = (
                self._assignment_delivery_recovery_evidence_tx(connection, attempts[-1])
            )
        value["user_needed"] = None
        if value["state"] == WorkState.USER_NEEDED.value:
            user_needed = connection.execute(
                """
                SELECT b.id AS boundary_id, d.reason, d.instruction,
                       d.resume_condition, d.created_at
                FROM boundary_dispositions AS d
                JOIN boundaries AS b ON b.id = d.boundary_id
                JOIN work_items AS current_work
                  ON current_work.id = b.work_item_id
                 AND current_work.user_needed_boundary_id = b.id
                LEFT JOIN boundary_continuations AS continuation
                  ON continuation.boundary_id = b.id
                WHERE current_work.id = ? AND d.kind = 'wait_user'
                  AND continuation.boundary_id IS NULL
                """,
                (work_id,),
            ).fetchone()
            if (
                user_needed is None
                or not str(user_needed["instruction"]).strip()
                or not str(user_needed["resume_condition"]).strip()
            ):
                raise RuntimeError(
                    "user-needed Work lacks a structured requester decision contract"
                )
            value["user_needed"] = {
                "decision": str(user_needed["instruction"]),
                "reason": str(user_needed["reason"]),
                "resume_condition": str(user_needed["resume_condition"]),
                "boundary_id": str(user_needed["boundary_id"]),
                "requested_at": str(user_needed["created_at"]),
            }
        task = connection.execute(
            "SELECT task_id, context_id FROM a2a_task_map WHERE work_item_id = ?", (work_id,)
        ).fetchone()
        value["a2a"] = dict(task) if task else None
        return value

    @staticmethod
    def _assignment_delivery_recovery_evidence_tx(
        connection: sqlite3.Connection, attempt: sqlite3.Row
    ) -> dict[str, Any]:
        """Project bounded facts needed to judge one Assignment outcome safely."""

        delivery = connection.execute(
            """
            SELECT delivery.state, delivery.last_error, message.id AS message_id
            FROM message_deliveries AS delivery
            JOIN messages AS message ON message.id = delivery.message_id
            WHERE message.attempt_id = ? AND message.kind = 'assignment'
              AND delivery.recipient_id = ?
            ORDER BY message.sequence, delivery.recipient_id
            LIMIT 1
            """,
            (attempt["id"], attempt["worker_id"]),
        ).fetchone()
        ticket = connection.execute(
            """
            SELECT ticket.enrollment_id, ticket.generation, ticket.consumed_at,
                   enrollment.discovered_at, enrollment.heartbeat_at
            FROM runtime_enrollment_tickets AS ticket
            JOIN worker_enrollments AS enrollment
              ON enrollment.id = ticket.enrollment_id
            WHERE ticket.attempt_id = ?
              AND enrollment.runtime_session_id = ?
            ORDER BY ticket.generation DESC, ticket.created_at DESC
            LIMIT 1
            """,
            (attempt["id"], attempt["runtime_session_id"]),
        ).fetchone()
        consumed_at = str(ticket["consumed_at"] or "") if ticket is not None else ""
        launch_ticket_consumed = bool(consumed_at)
        credential_issued = bool(
            ticket is not None
            and connection.execute(
                "SELECT 1 FROM runtime_credentials "
                "WHERE enrollment_id = ? AND generation = ? LIMIT 1",
                (ticket["enrollment_id"], ticket["generation"]),
            ).fetchone()
            is not None
        )
        mcp_tools_discovered = bool(
            consumed_at and ticket is not None and str(ticket["discovered_at"] or "") >= consumed_at
        )
        heartbeat_observed = bool(
            consumed_at
            and ticket is not None
            and str(ticket["heartbeat_at"] or "") >= consumed_at
            and connection.execute(
                "SELECT 1 FROM events WHERE event_type = 'runtime.heartbeat' "
                "AND aggregate_type = 'runtime' AND aggregate_id = ? "
                "AND actor_id = ? AND created_at >= ? LIMIT 1",
                (attempt["runtime_session_id"], attempt["worker_id"], consumed_at),
            ).fetchone()
            is not None
        )
        worker_report_observed = (
            connection.execute(
                "SELECT 1 FROM messages WHERE attempt_id = ? AND sender_id = ? "
                "AND kind IN ('progress', 'question', 'blocker', 'artifact', "
                "'completion_claim') LIMIT 1",
                (attempt["id"], attempt["worker_id"]),
            ).fetchone()
            is not None
        )
        runtime_metadata: Mapping[str, Any] = {}
        if attempt["runtime_session_id"]:
            runtime = connection.execute(
                "SELECT metadata_json FROM runtime_sessions WHERE id = ?",
                (attempt["runtime_session_id"],),
            ).fetchone()
            loaded_runtime_metadata = (
                _load(str(runtime["metadata_json"]), {}) if runtime is not None else {}
            )
            if isinstance(loaded_runtime_metadata, Mapping):
                runtime_metadata = loaded_runtime_metadata
        assignment_acceptance = "not_observed"
        if delivery is not None and str(
            runtime_metadata.get("last_dispatch_message_id") or ""
        ) == str(delivery["message_id"]):
            last_dispatch = runtime_metadata.get("last_dispatch")
            diagnostics = (
                last_dispatch.get("diagnostics") if isinstance(last_dispatch, Mapping) else None
            )
            observed_acceptance = (
                diagnostics.get("delivery_acceptance") if isinstance(diagnostics, Mapping) else None
            )
            if observed_acceptance in {
                "not_submitted",
                "submitted",
                "queued",
                "started",
                "completed",
            }:
                assignment_acceptance = str(observed_acceptance)
        recovery = connection.execute(
            """
            SELECT boundary.recovery_action
            FROM boundaries AS boundary
            LEFT JOIN boundary_dispositions AS disposition
              ON disposition.boundary_id = boundary.id
            LEFT JOIN boundary_supersessions AS supersession
              ON supersession.boundary_id = boundary.id
            WHERE boundary.attempt_id = ? AND disposition.id IS NULL
              AND supersession.boundary_id IS NULL
              AND boundary.recovery_action IN (
                  'dispose_continue_or_correct',
                  'reconcile_continue_same_thread',
                  'system_reconciliation'
              )
            ORDER BY boundary.created_at DESC, boundary.id DESC
            LIMIT 1
            """,
            (attempt["id"],),
        ).fetchone()
        state = str(delivery["state"] or "") if delivery is not None else "missing"
        last_error = str(delivery["last_error"] or "") if delivery is not None else ""
        if state == DeliveryState.DISPATCHED.value and last_error:
            outcome = "unknown"
        elif state in {
            DeliveryState.DELIVERED.value,
            DeliveryState.ACKNOWLEDGED.value,
            DeliveryState.HANDLED.value,
        }:
            outcome = "delivered"
        elif state in {DeliveryState.QUEUED.value, DeliveryState.LEASED.value}:
            outcome = "pending"
        elif state == DeliveryState.DEAD.value:
            outcome = "closed"
        else:
            outcome = "not_observed"
        mcp_crossed = credential_issued or mcp_tools_discovered or heartbeat_observed
        recovery_action = str(recovery["recovery_action"] or "") if recovery else ""
        safe_to_redeliver = bool(
            recovery_action == "dispose_continue_or_correct"
            and (not mcp_crossed or assignment_acceptance == "not_submitted")
        )
        safe_to_reconcile = recovery_action == "reconcile_continue_same_thread"
        if outcome == "unknown" and mcp_crossed:
            safety_reason = "unknown_after_mcp_authority"
        elif safe_to_redeliver and assignment_acceptance == "not_submitted":
            safety_reason = "assignment_not_submitted"
        elif safe_to_redeliver:
            safety_reason = "proven_pre_mcp"
        else:
            safety_reason = "not_authorized"
        return {
            "state": state,
            "outcome": outcome,
            "mcp_authority_boundary": "crossed" if mcp_crossed else "not_crossed",
            "launch_ticket_consumed": launch_ticket_consumed,
            "credential_issued": credential_issued,
            "mcp_tools_discovered": mcp_tools_discovered,
            "heartbeat_observed": heartbeat_observed,
            "worker_report_observed": worker_report_observed,
            "assignment_delivery_boundary": assignment_acceptance,
            "safe_to_redeliver": safe_to_redeliver,
            "safe_to_reconcile": safe_to_reconcile,
            "recovery_action": recovery_action or None,
            "safety_reason": safety_reason,
        }

    @staticmethod
    def _attempt_activity_tx(
        connection: sqlite3.Connection, attempt: sqlite3.Row
    ) -> dict[str, Any]:
        runtime = (
            connection.execute(
                """
                SELECT enrollment.heartbeat_at
                FROM worker_enrollments AS enrollment
                WHERE enrollment.runtime_session_id = ?
                  AND enrollment.managed = 1
                  AND enrollment.heartbeat_at IS NOT NULL
                  AND enrollment.heartbeat_at >= ?
                  AND EXISTS (
                      SELECT 1 FROM runtime_enrollment_tickets AS ticket
                      WHERE ticket.enrollment_id = enrollment.id
                        AND ticket.attempt_id = ?
                        AND ticket.state = 'consumed'
                        AND ticket.generation = enrollment.generation
                        AND ticket.created_at >= ?
                        AND ticket.consumed_at >= ?
                  )
                """,
                (
                    attempt["runtime_session_id"],
                    attempt["created_at"],
                    attempt["id"],
                    attempt["created_at"],
                    attempt["created_at"],
                ),
            ).fetchone()
            if attempt["runtime_session_id"]
            else None
        )
        activity = connection.execute(
            """
            SELECT created_at FROM messages
            WHERE attempt_id = ? AND sender_id = ?
              AND kind IN ('progress', 'question', 'blocker', 'completion_claim')
            ORDER BY sequence DESC LIMIT 1
            """,
            (attempt["id"], attempt["worker_id"]),
        ).fetchone()
        artifact = connection.execute(
            "SELECT created_at FROM artifacts WHERE attempt_id = ? "
            "ORDER BY created_at DESC, id DESC LIMIT 1",
            (attempt["id"],),
        ).fetchone()
        status_message = connection.execute(
            "SELECT sequence, id, payload_json, created_at FROM messages "
            "WHERE attempt_id = ? AND kind = 'status_request' "
            "ORDER BY sequence DESC LIMIT 1",
            (attempt["id"],),
        ).fetchone()
        status_request: dict[str, Any] | None = None
        if status_message is not None:
            payload = _load(status_message["payload_json"], {})
            response_due_at = str(payload.get("response_due_at", ""))
            response = connection.execute(
                """
                SELECT created_at FROM messages
                WHERE attempt_id = ? AND sender_id = ? AND sequence > ?
                  AND kind IN ('progress', 'question', 'blocker', 'completion_claim')
                ORDER BY sequence ASC LIMIT 1
                """,
                (
                    attempt["id"],
                    attempt["worker_id"],
                    status_message["sequence"],
                ),
            ).fetchone()
            status_request = {
                "message_id": str(status_message["id"]),
                "state": (
                    "responded"
                    if response is not None
                    else ("overdue" if _is_expired(response_due_at) else "pending")
                ),
                "requested_at": str(status_message["created_at"]),
                "response_due_at": response_due_at,
                "responded_at": (str(response["created_at"]) if response is not None else ""),
            }
        return {
            "runtime_heartbeat_at": (
                str(runtime["heartbeat_at"] or "") if runtime is not None else ""
            ),
            "last_worker_activity_at": (
                str(activity["created_at"]) if activity is not None else ""
            ),
            "last_artifact_at": (str(artifact["created_at"]) if artifact is not None else ""),
            "status_request": status_request,
        }

    @staticmethod
    def _completion_claim_artifact_rows_tx(
        connection: sqlite3.Connection,
        attempt: Mapping[str, Any] | sqlite3.Row,
    ) -> list[sqlite3.Row] | None:
        """Resolve the artifact manifest sealed by the current completion claim.

        New claims bind their exact artifact ids.  An empty legacy manifest
        keeps the original "artifact report, then claim" contract by freezing
        every artifact already registered on that Attempt.  A non-empty
        malformed or substituted manifest fails closed.
        """

        claim = _load(attempt["completion_claim_json"], {})
        if not isinstance(claim, Mapping) or not claim:
            return None
        manifest = claim.get("artifacts", [])
        if not isinstance(manifest, list):
            return None
        manifest_scope = claim.get("artifact_manifest_scope")
        if manifest_scope not in {None, "verified_attempt_artifacts_v2"}:
            return None
        is_verified_v2 = manifest_scope == "verified_attempt_artifacts_v2"
        if not manifest:
            if is_verified_v2:
                return []
            return list(
                connection.execute(
                    "SELECT * FROM artifacts WHERE attempt_id = ? ORDER BY created_at, id",
                    (attempt["id"],),
                ).fetchall()
            )

        rows: list[sqlite3.Row] = []
        seen: set[str] = set()
        for item in manifest:
            if not isinstance(item, Mapping):
                return None
            artifact_id = item.get("id")
            if not isinstance(artifact_id, str) or not artifact_id or artifact_id in seen:
                return None
            row = connection.execute(
                "SELECT * FROM artifacts WHERE id = ? AND attempt_id = ?",
                (artifact_id, attempt["id"]),
            ).fetchone()
            item_digest = item.get("digest", "")
            item_uri = item.get("uri", "")
            row_digest = str(row["digest"]) if row is not None else ""
            row_uri = str(row["uri"]) if row is not None else ""
            digest_matches = isinstance(item_digest, str) and (
                item_digest == row_digest
                or (not is_verified_v2 and _canonical_artifact_digest(item_digest) == row_digest)
            )
            if (
                row is None
                or not digest_matches
                or not isinstance(item_uri, str)
                or item_uri != row_uri
                or (
                    is_verified_v2
                    and (
                        re.fullmatch(r"[0-9a-f]{64}", row_digest) is None
                        or row_uri != f"owner-private-artifact:{row_digest}"
                    )
                )
            ):
                return None
            seen.add(artifact_id)
            rows.append(row)
        return rows

    @classmethod
    def _completion_delivery_state_tx(
        cls,
        connection: sqlite3.Connection,
        *,
        contract: str,
        attempt: sqlite3.Row | None,
    ) -> str:
        """Derive the completion delivery gate from canonical durable facts.

        The value is deliberately not persisted: review and requester acceptance
        re-evaluate the same evidence so deleted or corrupted artifact records
        cannot leave a stale green flag behind.
        """

        if attempt is None or not _load(attempt["completion_claim_json"], {}):
            return "pending"
        if contract == CompletionContract.NO_ARTIFACT_EXPECTED.value:
            return "not_required"
        if contract == CompletionContract.LEGACY_UNCLASSIFIED.value:
            return "legacy_unclassified"
        if contract != CompletionContract.COMPLETION_REQUIRED.value:
            raise RuntimeError("work item completion contract is invalid")
        artifacts = cls._completion_claim_artifact_rows_tx(connection, attempt)
        if not artifacts:
            return "delivery_missing"
        digest_pattern = re.compile(r"^[0-9a-f]{64}$")
        if any(
            str(artifact["uri"]) != f"owner-private-artifact:{artifact['digest']}"
            or digest_pattern.fullmatch(str(artifact["digest"])) is None
            for artifact in artifacts
        ):
            return "delivery_missing"
        return "ready"

    def _require_completion_delivery_ready_tx(
        self,
        connection: sqlite3.Connection,
        work: Mapping[str, Any] | sqlite3.Row,
        attempt: sqlite3.Row,
    ) -> str:
        pending_input = connection.execute(
            """SELECT 1 FROM messages message JOIN message_deliveries delivery
                 ON delivery.message_id = message.id
               WHERE message.attempt_id = ? AND delivery.recipient_id = ?
                 AND delivery.runtime_session_id = ?
                 AND delivery.state IN ('queued', 'leased', 'dispatched', 'delivered', 'acknowledged')
               LIMIT 1""",
            (attempt["id"], attempt["worker_id"], attempt["runtime_session_id"]),
        ).fetchone()
        if pending_input is not None:
            raise ConflictError(
                "completion has unsettled Worker commands",
                reason_code="completion_worker_input_pending",
            )
        goal = self._current_goal_tx(connection, work)
        packet = _load(goal["packet_json"], {})
        contract = str(
            packet.get(
                "completion_contract",
                CompletionContract.LEGACY_UNCLASSIFIED.value,
            )
        )
        state = self._completion_delivery_state_tx(
            connection,
            contract=contract,
            attempt=attempt,
        )
        if state == "delivery_missing":
            raise ConflictError(
                "completion-required Work has no verified artifact delivery",
                completion_contract=contract,
                delivery_state=state,
            )
        if state == "pending":
            raise ConflictError(
                "completion delivery cannot be reviewed before a completion claim",
                completion_contract=contract,
                delivery_state=state,
            )
        return state

    @staticmethod
    def _current_goal_tx(
        connection: sqlite3.Connection, work: Mapping[str, Any] | sqlite3.Row
    ) -> sqlite3.Row:
        row: sqlite3.Row | None = connection.execute(
            """
            SELECT * FROM goal_revisions
            WHERE work_item_id = ? AND version = ?
            """,
            (work["id"], work["goal_version"]),
        ).fetchone()
        if row is None:
            raise RuntimeError("work item current goal pointer is invalid")
        return row

    def _attempt_view(self, row: sqlite3.Row) -> dict[str, Any]:
        value = dict(row)
        value["completion_claim"] = _load(value.pop("completion_claim_json"), {})
        return value

    def _artifact_view(self, row: sqlite3.Row) -> dict[str, Any]:
        value = dict(row)
        value["metadata"] = _load(value.pop("metadata_json"), {})
        return value

    def _review_view(self, row: sqlite3.Row) -> dict[str, Any]:
        value = dict(row)
        value["evidence"] = _load(value.pop("evidence_json"), [])
        return value

    @staticmethod
    def _requester_decision_view(row: sqlite3.Row) -> dict[str, Any]:
        value = dict(row)
        value["evidence"] = _load(value.pop("evidence_json"), [])
        return value

    def _close_receipt_view(self, row: sqlite3.Row) -> dict[str, Any]:
        value = dict(row)
        artifacts = _load(value.pop("artifacts_json"), None)
        cleanup = _load(value.pop("cleanup_json"), None)
        preparation = self.db.fetchone(
            "SELECT * FROM work_close_preparations WHERE id = ? AND work_item_id = ?",
            (value.get("close_preparation_id"), value["work_item_id"]),
        )
        if preparation is None:
            raise RuntimeError("stored close receipt is malformed")
        prepared_artifacts = _load(str(preparation["artifacts_json"]), None)
        inventory = _load(str(preparation["inventory_json"]), None)
        if (
            not isinstance(artifacts, list)
            or not isinstance(cleanup, list)
            or not isinstance(prepared_artifacts, list)
            or not isinstance(inventory, list)
            or _digest(inventory) != str(preparation["inventory_digest"])
            or value.get("cleanup_inventory_evidence_id") != value.get("close_preparation_id")
        ):
            raise RuntimeError("stored close receipt is malformed")
        expected_cleanup = {
            (
                str(item.get("target_kind")),
                str(item.get("target_fingerprint")),
                str(item.get("action")),
            )
            for item in inventory
            if isinstance(item, Mapping) and item.get("coverage", "enumerated") == "enumerated"
        }
        actual_cleanup = {
            (
                str(item.get("target_kind")),
                str(item.get("target_fingerprint")),
                str(item.get("action")),
            )
            for item in cleanup
            if isinstance(item, Mapping)
        }
        if (
            len(actual_cleanup) != len(cleanup)
            or actual_cleanup != expected_cleanup
            or {
                str(item.get("artifact_id")): str(item.get("digest"))
                for item in artifacts
                if isinstance(item, Mapping)
            }
            != {
                str(item.get("id")): str(item.get("digest"))
                for item in prepared_artifacts
                if isinstance(item, Mapping)
            }
        ):
            raise RuntimeError("stored close receipt does not match its preparation")
        try:
            plan = ClosePlan(
                work_item_id=str(value["work_item_id"]),
                attempt_id=str(value["attempt_id"]),
                review_id=str(value["review_id"]),
                requester_decision_id=str(value["requester_decision_id"]),
                expected_goal_version=int(value["goal_version"]),
                expected_goal_packet_digest=str(value["goal_packet_digest"]),
                expected_task_packet_digest=str(value["task_packet_digest"]),
                expected_generation=int(value["work_generation"]),
                retention_policy_evidence_id=str(value["retention_policy_evidence_id"]),
                artifact_manifest_evidence_id=str(value["artifact_manifest_evidence_id"]),
                cleanup_inventory_evidence_id=str(value["cleanup_inventory_evidence_id"]),
                artifacts=tuple(
                    ArtifactPreservation(
                        str(item["artifact_id"]), str(item["digest"]), str(item["evidence_id"])
                    )
                    for item in artifacts
                ),
                cleanup=tuple(
                    CleanupRecord(
                        CleanupTargetKind(item["target_kind"]),
                        str(item["target_fingerprint"]),
                        CleanupAction(item["action"]),
                        CleanupOutcome(item["outcome"]),
                        str(item["evidence_id"]),
                        str(item.get("effect_operation_id", "")),
                        str(item.get("destructive_authority_evidence_id", "")),
                    )
                    for item in cleanup
                ),
                close_preparation_id=str(value["close_preparation_id"]),
            )
        except (KeyError, TypeError, ValueError) as error:
            raise RuntimeError("stored close receipt is malformed") from error
        if plan.digest() != str(value["plan_digest"]):
            raise RuntimeError("stored close receipt plan digest is invalid")
        value["state"] = "closed"
        value["artifact_ids"] = [
            str(item.get("artifact_id", "")) for item in artifacts if isinstance(item, Mapping)
        ]
        value["cleanup_target_fingerprints"] = [
            str(item.get("target_fingerprint", "")) for item in cleanup if isinstance(item, Mapping)
        ]
        value["open_delivery_count"] = 0
        value["active_scoped_runtime_count"] = 0
        value["unresolved_effect_count"] = 0
        return value

    def _message_view(
        self,
        row: sqlite3.Row,
        *,
        connection: sqlite3.Connection | None = None,
    ) -> dict[str, Any]:
        value = dict(row)
        value["payload"] = _load(value.pop("payload_json"), {})
        payload = value["payload"]
        if connection is not None and isinstance(payload, dict) and payload.get("boundary_id"):
            route = connection.execute(
                "SELECT recovery_action, recovery_target, recovery_model, "
                "recovery_reasoning_effort FROM boundaries WHERE id = ?",
                (str(payload["boundary_id"]),),
            ).fetchone()
            recovery_action = str(route["recovery_action"] or "") if route is not None else ""
            if recovery_action not in {
                "",
                "dispose_continue_or_correct",
                "reconcile_continue_same_thread",
                "system_reconciliation",
            }:
                recovery_action = "system_reconciliation"
            if recovery_action:
                # This is a projection field, not a mutation of the sealed
                # payload.  In particular, migrated v30 messages retain the
                # exact payload whose payload_digest they expose.
                value["recovery_action"] = recovery_action
        value["acknowledged"] = bool(value.get("acknowledged_at"))
        if value.get("recipient_delivery_state"):
            value["delivery_state"] = value.pop("recipient_delivery_state")
        return value

    def _message_bundle_tx(self, connection: sqlite3.Connection, message_id: str) -> dict[str, Any]:
        row = connection.execute("SELECT * FROM messages WHERE id = ?", (message_id,)).fetchone()
        if row is None:
            raise NotFoundError("message", message_id)
        value = self._message_view(row, connection=connection)
        deliveries = connection.execute(
            """
            SELECT * FROM message_deliveries
            WHERE message_id = ? ORDER BY recipient_id
            """,
            (message_id,),
        ).fetchall()
        value["deliveries"] = [dict(delivery) for delivery in deliveries]
        return value

    def _event_view(self, row: sqlite3.Row) -> dict[str, Any]:
        value = dict(row)
        value["data"] = _load(value.pop("data_json"), {})
        return value

    def _latest_attempt_tx(
        self, connection: sqlite3.Connection, work_id: str
    ) -> sqlite3.Row | None:
        row: sqlite3.Row | None = connection.execute(
            "SELECT * FROM attempts WHERE work_item_id = ? ORDER BY attempt_number DESC LIMIT 1",
            (work_id,),
        ).fetchone()
        return row

    def _create_artifact_tx(
        self,
        connection: sqlite3.Connection,
        *,
        actor: Mapping[str, Any],
        work: sqlite3.Row,
        attempt: sqlite3.Row,
        artifact: ArtifactInput,
    ) -> dict[str, Any]:
        artifact_id = _id("art")
        artifact_uri = artifact.uri
        artifact_digest = _canonical_artifact_digest(artifact.digest)
        verified_digest = re.fullmatch(r"[0-9a-f]{64}", artifact_digest) is not None
        parsed_uri = urlsplit(artifact_uri)
        if not verified_digest:
            artifact_uri = f"unverified-artifact:{artifact_id}"
        elif parsed_uri.scheme == "file" or not parsed_uri.scheme:
            try:
                artifact_uri = self.owner_private_artifact_preservation.stage_file(
                    digest=artifact_digest,
                    locator=self._owner_private_artifact_source(artifact_uri),
                )
            except ArtifactPreservationProviderError as error:
                raise ValidationError(
                    "local artifact could not be staged in owner-private storage"
                ) from error
        elif parsed_uri.scheme == "data":
            try:
                artifact_uri = self.owner_private_artifact_preservation.stage_bytes(
                    digest=artifact_digest,
                    content=_decode_inline_artifact(artifact_uri),
                )
            except ArtifactPreservationProviderError as error:
                raise ValidationError(
                    "inline artifact could not be staged in owner-private storage"
                ) from error
        elif parsed_uri.scheme == "workspace":
            workspace_fd: int | None = None
            try:
                if parsed_uri.netloc or parsed_uri.query or parsed_uri.fragment:
                    raise ArtifactPreservationProviderError(
                        "artifact_preservation_workspace_locator_invalid"
                    )
                workspace_fd = self._acquire_report_workspace_tx(
                    connection,
                    actor=actor,
                    work=work,
                    attempt=attempt,
                )
                if workspace_fd is None:
                    artifact_uri = f"unverified-artifact:{artifact_id}"
                else:
                    artifact_uri = self.owner_private_artifact_preservation.stage_workspace_file(
                        digest=artifact_digest,
                        workspace_fd=workspace_fd,
                        relative_locator=unquote(parsed_uri.path),
                    )
            except (ArtifactPreservationProviderError, PrivatePolicyError) as error:
                raise ValidationError(
                    "workspace artifact could not be staged in owner-private storage"
                ) from error
            finally:
                if workspace_fd is not None:
                    os.close(workspace_fd)
        elif artifact_uri.startswith("owner-private-artifact:"):
            raise ValidationError(
                "owner-private artifact references are issued only by the control plane"
            )
        else:
            artifact_uri = f"unverified-artifact:{artifact_id}"
        now = utc_now()
        connection.execute(
            """
            INSERT INTO artifacts(
                id, work_item_id, attempt_id, producer_id, name, uri,
                media_type, digest, metadata_json, created_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                artifact_id,
                work["id"],
                attempt["id"],
                actor["id"],
                artifact.name,
                artifact_uri,
                artifact.media_type,
                artifact_digest,
                _json(artifact.metadata),
                now,
            ),
        )
        row = connection.execute("SELECT * FROM artifacts WHERE id = ?", (artifact_id,)).fetchone()
        assert row is not None
        return self._artifact_view(row)

    def _boundary_delivery_rows_tx(
        self,
        connection: sqlite3.Connection,
        *,
        boundary_id: str,
        recipient_id: str,
    ) -> list[sqlite3.Row]:
        return connection.execute(
            """
            SELECT message.id, message.payload_json, delivery.state
            FROM boundaries AS boundary
            JOIN work_items AS work ON work.id = boundary.work_item_id
            JOIN messages AS message
              ON message.work_item_id = boundary.work_item_id
             AND message.attempt_id = boundary.attempt_id
             AND message.goal_version = boundary.goal_version
             AND message.goal_packet_digest = boundary.goal_packet_digest
             AND message.task_packet_digest = boundary.task_packet_digest
            JOIN message_deliveries AS delivery ON delivery.message_id = message.id
            WHERE boundary.id = ?
              AND delivery.recipient_id = ?
              AND delivery.recipient_attachment_id IS work.supervisor_attachment_id
              AND json_valid(message.payload_json)
              AND json_extract(message.payload_json, '$.boundary_id') = boundary.id
            ORDER BY message.sequence, message.id
            """,
            (boundary_id, recipient_id),
        ).fetchall()

    def _handle_intent_deliveries_tx(
        self,
        connection: sqlite3.Connection,
        *,
        intent_id: str,
        actor_id: str,
        evidence: str,
    ) -> None:
        """Settle every CAO wake-up once the intent disposition is durable.

        A submitted intent is broadcast to all enabled CAO principals so that
        the control plane does not depend on one ephemeral runtime.  The first
        valid classifier commits the disposition and atomically handles every
        copy of that wake-up; another runtime can therefore replay safely
        without producing a second task or directive.
        """

        rows = connection.execute(
            """
            SELECT m.id, m.payload_json, d.recipient_id, d.state
            FROM messages AS m
            JOIN message_deliveries AS d ON d.message_id = m.id
            JOIN principals AS p ON p.id = d.recipient_id
            WHERE m.causation_id = ? AND m.kind = ? AND p.role = ?
            ORDER BY m.sequence, d.recipient_id
            """,
            (
                intent_id,
                MessageKind.SYSTEM.value,
                PrincipalRole.CAO.value,
            ),
        ).fetchall()
        now = utc_now()
        for row in rows:
            payload = _load(row["payload_json"], {})
            if (
                payload.get("action") != "classify_submitted_intent"
                or str(payload.get("intent_id", "")) != intent_id
            ):
                continue
            if row["state"] in {DeliveryState.HANDLED.value, DeliveryState.DEAD.value}:
                continue
            connection.execute(
                """
                UPDATE message_deliveries
                SET state = ?, delivered_at = COALESCE(delivered_at, ?),
                    acknowledged_at = COALESCE(acknowledged_at, ?), handled_at = ?,
                    lease_until = NULL, owner_token = '', updated_at = ?
                WHERE message_id = ? AND recipient_id = ? AND state <> ?
                """,
                (
                    DeliveryState.HANDLED.value,
                    now,
                    now,
                    now,
                    now,
                    row["id"],
                    row["recipient_id"],
                    DeliveryState.DEAD.value,
                ),
            )
            self._event(
                connection,
                "message.handled",
                "message",
                str(row["id"]),
                actor_id,
                {
                    "recipient_id": str(row["recipient_id"]),
                    "evidence_digest": _digest(evidence),
                },
                causation_id=intent_id,
            )

    def _handle_boundary_deliveries_tx(
        self,
        connection: sqlite3.Connection,
        *,
        boundary_id: str,
        recipient_id: str,
        evidence: str,
    ) -> None:
        """Settle only notifications the CAO explicitly received before disposition.

        Resolving a Boundary is not evidence that every pending notification
        was read. Unreceived successors remain independently visible and can
        later be acknowledged and handled without repeating the disposition.
        """

        now = utc_now()
        for row in self._boundary_delivery_rows_tx(
            connection, boundary_id=boundary_id, recipient_id=recipient_id
        ):
            if row["state"] != DeliveryState.ACKNOWLEDGED.value:
                continue
            connection.execute(
                """
                UPDATE message_deliveries
                SET state = ?, handled_at = ?,
                    lease_until = NULL, owner_token = '', updated_at = ?
                WHERE message_id = ? AND recipient_id = ? AND state = ?
                """,
                (
                    DeliveryState.HANDLED.value,
                    now,
                    now,
                    row["id"],
                    recipient_id,
                    DeliveryState.ACKNOWLEDGED.value,
                ),
            )
            self._event(
                connection,
                "message.handled",
                "message",
                str(row["id"]),
                recipient_id,
                {"evidence_digest": _digest(evidence)},
                causation_id=boundary_id,
            )

    def _supersede_boundary_deliveries_tx(
        self,
        connection: sqlite3.Connection,
        *,
        boundary_id: str,
        recipient_id: str,
        reason: str,
    ) -> None:
        """Close stale wake-ups before issuing a recovery delivery."""

        now = utc_now()
        connection.execute(
            "UPDATE reasoner_turns SET state = ?, updated_at = ? "
            "WHERE boundary_id = ? AND state = ?",
            (
                ReasonerTurnState.ABANDONED.value,
                now,
                boundary_id,
                ReasonerTurnState.LEASED.value,
            ),
        )
        for row in self._boundary_delivery_rows_tx(
            connection, boundary_id=boundary_id, recipient_id=recipient_id
        ):
            if row["state"] in {DeliveryState.HANDLED.value, DeliveryState.DEAD.value}:
                continue
            connection.execute(
                """
                UPDATE message_deliveries
                SET state = ?, lease_until = NULL, owner_token = '',
                    last_error = ?, updated_at = ?
                WHERE message_id = ? AND recipient_id = ?
                """,
                (
                    DeliveryState.DEAD.value,
                    f"superseded;evidence_digest={_digest(reason)}",
                    now,
                    row["id"],
                    recipient_id,
                ),
            )
            self._event(
                connection,
                "message.delivery_superseded",
                "message",
                str(row["id"]),
                recipient_id,
                {
                    "boundary_id": boundary_id,
                    "reason_digest": _digest(reason),
                },
                causation_id=boundary_id,
            )

    def _message(
        self,
        connection: sqlite3.Connection,
        *,
        sender_id: str,
        recipient_id: str | None = None,
        recipient_ids: Iterable[str] | None = None,
        kind: MessageKind,
        payload: dict[str, Any],
        work_item_id: str | None = None,
        attempt_id: str | None = None,
        correlation_id: str = "",
        causation_id: str = "",
        idempotency_key: str = "",
        goal_version: int | None = None,
        runtime_session_id: str | None = None,
        create_delivery: bool = True,
    ) -> dict[str, Any]:
        recipients = list(
            dict.fromkeys(
                [
                    *([recipient_id] if recipient_id else []),
                    *(recipient_ids or []),
                ]
            )
        )
        if not recipients:
            raise ValidationError("message requires at least one recipient")
        if not create_delivery and kind != MessageKind.ARTIFACT:
            raise ValidationError("only an artifact-only Worker report may omit delivery")
        goal_digest_value = ""
        task_digest_value = ""
        bound_runtime_session_id = runtime_session_id
        attempt_runtime_id: str | None = None
        attempt_worker_id: str | None = None
        work_supervisor_id: str | None = None
        work_supervisor_attachment_id: str | None = None
        if work_item_id:
            if goal_version is None:
                raise ValidationError("work-scoped message requires a goal version")
            goal = connection.execute(
                "SELECT packet_digest FROM goal_revisions WHERE work_item_id = ? AND version = ?",
                (work_item_id, goal_version),
            ).fetchone()
            if goal is None or not goal["packet_digest"]:
                raise ConflictError("message cannot bind a missing goal packet")
            goal_digest_value = str(goal["packet_digest"])
            work_binding = connection.execute(
                "SELECT COALESCE(supervisor_id, created_by) AS supervisor_id, "
                "supervisor_attachment_id FROM work_items WHERE id = ?",
                (work_item_id,),
            ).fetchone()
            if work_binding is None:
                raise NotFoundError("work item", work_item_id)
            work_supervisor_id = str(work_binding["supervisor_id"])
            work_supervisor_attachment_id = (
                str(work_binding["supervisor_attachment_id"])
                if work_binding["supervisor_attachment_id"] is not None
                else None
            )
            if attempt_id:
                attempt = connection.execute(
                    "SELECT * FROM attempts WHERE id = ? AND work_item_id = ?",
                    (attempt_id, work_item_id),
                ).fetchone()
                if (
                    attempt is None
                    or int(attempt["goal_version"]) != goal_version
                    or str(attempt["goal_packet_digest"]) != goal_digest_value
                    or not attempt["task_packet_digest"]
                ):
                    raise ConflictError("message cannot bind a stale task packet")
                task_digest_value = str(attempt["task_packet_digest"])
                if not attempt["runtime_session_id"]:
                    raise ConflictError("Worker message cannot bind an attempt without a runtime")
                attempt_runtime_id = str(attempt["runtime_session_id"])
                attempt_worker_id = str(attempt["worker_id"])
            payload = dict(payload)
            for field, expected in (
                ("goal_packet_digest", goal_digest_value),
                ("task_packet_digest", task_digest_value),
            ):
                supplied = payload.get(field)
                if supplied not in {None, "", expected}:
                    raise ConflictError(f"message {field} does not match the durable packet")
                if expected:
                    payload[field] = expected
        payload_digest = _digest(payload)
        message_digest = _digest(
            {
                "sender_id": sender_id,
                "recipient_ids": recipients,
                "kind": kind.value,
                "payload": payload,
                "work_item_id": work_item_id,
                "attempt_id": attempt_id,
                "correlation_id": correlation_id,
                "causation_id": causation_id,
                "goal_version": goal_version,
                "goal_packet_digest": goal_digest_value,
                "task_packet_digest": task_digest_value,
                "runtime_session_id": bound_runtime_session_id,
            }
        )
        if idempotency_key:
            existing = connection.execute(
                "SELECT * FROM messages WHERE sender_id = ? AND idempotency_key = ?",
                (sender_id, idempotency_key),
            ).fetchone()
            if existing:
                if existing["message_digest"] and existing["message_digest"] != message_digest:
                    raise ConflictError("message idempotency key was reused with different content")
                return self._message_bundle_tx(connection, str(existing["id"]))
        message_id = _id("msg")
        now = utc_now()
        correlation = correlation_id or message_id
        connection.execute(
            """
            INSERT INTO messages(
                id, work_item_id, attempt_id, sender_id, kind,
                payload_json, payload_digest, message_digest,
                correlation_id, causation_id,
                idempotency_key, goal_version, goal_packet_digest,
                task_packet_digest, created_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                message_id,
                work_item_id,
                attempt_id,
                sender_id,
                kind.value,
                _json(payload),
                payload_digest,
                message_digest,
                correlation,
                causation_id,
                idempotency_key,
                goal_version,
                goal_digest_value,
                task_digest_value,
                now,
            ),
        )
        for recipient in recipients:
            principal = connection.execute(
                "SELECT id, role FROM principals WHERE id = ? AND enabled = 1",
                (recipient,),
            ).fetchone()
            if principal is None:
                raise NotFoundError("enabled message recipient", recipient)
            if not create_delivery:
                if (
                    not work_item_id
                    or not attempt_id
                    or sender_id != attempt_worker_id
                    or work_supervisor_id is None
                    or recipient != work_supervisor_id
                ):
                    raise ValidationError(
                        "informational report must bind its exact Worker attempt and supervisor"
                    )
                continue
            recipient_runtime_id = bound_runtime_session_id
            recipient_attachment_id: str | None = None
            if principal["role"] == PrincipalRole.CAO.value:
                if work_item_id and recipient != work_supervisor_id:
                    raise AuthorizationError(
                        "Work-bound CAO delivery must target its exact supervisor"
                    )
                recipient_attachment_id = work_supervisor_attachment_id
            if recipient == attempt_worker_id:
                if recipient_runtime_id is not None and recipient_runtime_id != attempt_runtime_id:
                    raise ConflictError("message runtime does not match the durable task packet")
                recipient_runtime_id = attempt_runtime_id
            if recipient_runtime_id is not None:
                runtime = connection.execute(
                    """
                    SELECT * FROM runtime_sessions
                    WHERE id = ? AND principal_id = ?
                      AND state NOT IN (?, ?, ?)
                    """,
                    (
                        recipient_runtime_id,
                        recipient,
                        RuntimeState.STOPPED.value,
                        RuntimeState.MISSING.value,
                        RuntimeState.FAILED.value,
                    ),
                ).fetchone()
                if runtime is None:
                    raise ConflictError(
                        "message is pinned to an unavailable runtime",
                        runtime_session_id=recipient_runtime_id,
                    )
            elif principal["role"] == PrincipalRole.WORKER.value:
                runtime = connection.execute(
                    """
                    SELECT r.*
                    FROM runtime_sessions AS r
                    JOIN worker_enrollments AS e ON e.runtime_session_id = r.id
                    JOIN runtime_credentials AS c
                      ON c.enrollment_id = e.id AND c.principal_id = e.principal_id
                    WHERE r.principal_id = ? AND e.state = 'ready'
                      AND e.lease_expires_at >= ?
                      AND r.lease_expires_at >= ?
                      AND r.state IN ('ready', 'busy', 'waiting')
                      AND c.state = 'active' AND c.expires_at >= ?
                      AND c.generation = e.generation
                    ORDER BY r.updated_at DESC LIMIT 1
                    """,
                    (recipient, now, now, now),
                ).fetchone()
            elif principal["role"] == PrincipalRole.CAO.value:
                # A Work-bound CAO delivery is pinned to the immutable
                # attachment chosen at delegation.  Do not infer a thread from
                # activity, timestamps, or a legacy runtime: that would allow
                # Work from thread A to wake thread B.
                runtime = connection.execute(
                    """
                    SELECT r.*
                    FROM work_items AS w
                    JOIN cao_session_attachments AS a
                      ON a.id = w.supervisor_attachment_id
                    JOIN runtime_sessions AS r ON r.id = a.runtime_session_id
                    WHERE w.id = ? AND w.supervisor_id = ?
                      AND a.principal_id = ? AND a.state = 'active'
                      AND a.lease_expires_at > ? AND r.lease_expires_at > ?
                      AND r.state IN ('ready', 'waiting', 'busy')
                    """,
                    (work_item_id, recipient, recipient, now, now),
                ).fetchone()
            else:
                runtime = connection.execute(
                    """
                    SELECT * FROM runtime_sessions
                    WHERE principal_id = ? AND state NOT IN (?, ?)
                    ORDER BY updated_at DESC LIMIT 1
                    """,
                    (
                        recipient,
                        RuntimeState.STOPPED.value,
                        RuntimeState.MISSING.value,
                    ),
                ).fetchone()
            connection.execute(
                """
                INSERT INTO message_deliveries(
                    message_id, recipient_id, recipient_attachment_id,
                    state, generation, attempts,
                    next_attempt_at, runtime_session_id, lease_until,
                    owner_token, delivered_at, acknowledged_at, handled_at,
                    last_error, created_at, updated_at
                ) VALUES(?, ?, ?, ?, 1, 0, ?, ?, NULL, '', NULL, NULL, NULL, '', ?, ?)
                """,
                (
                    message_id,
                    recipient,
                    recipient_attachment_id,
                    DeliveryState.QUEUED.value,
                    now,
                    runtime["id"] if runtime else None,
                    now,
                    now,
                ),
            )
        self._event(
            connection,
            "message.created",
            "message",
            message_id,
            sender_id,
            {
                "recipient_ids": recipients,
                "kind": kind.value,
                "work_item_id": work_item_id,
                "attempt_id": attempt_id,
            },
            correlation_id=correlation,
            causation_id=causation_id,
        )
        return self._message_bundle_tx(connection, message_id)

    def _event(
        self,
        connection: sqlite3.Connection,
        event_type: str,
        aggregate_type: str,
        aggregate_id: str,
        actor_id: str,
        data: dict[str, Any],
        *,
        correlation_id: str = "",
        causation_id: str = "",
        operator_scope: str | None = None,
    ) -> int:
        event_id = _id("evt")
        created_at = utc_now()
        event_operator_scope = (
            resolve_event_operator_scope_tx(connection, aggregate_type, aggregate_id)
            if operator_scope is None
            else normalize_event_operator_scope(operator_scope)
        )
        cursor = connection.execute(
            """
            INSERT INTO events(
                id, event_type, aggregate_type, aggregate_id, operator_scope, actor_id,
                data_json, correlation_id, causation_id, created_at
            ) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                event_id,
                event_type,
                aggregate_type,
                aggregate_id,
                event_operator_scope,
                actor_id,
                _json(data),
                correlation_id,
                causation_id,
                created_at,
            ),
        ).lastrowid
        if cursor is None:
            raise RuntimeError("event insert did not produce a sequence")
        sequence = int(cursor)
        work_id = ""
        if aggregate_type == "work_item":
            work_id = aggregate_id
        elif aggregate_type == "attempt":
            row = connection.execute(
                "SELECT work_item_id FROM attempts WHERE id = ?", (aggregate_id,)
            ).fetchone()
            work_id = str(row["work_item_id"]) if row else ""
        elif aggregate_type == "message":
            row = connection.execute(
                "SELECT work_item_id FROM messages WHERE id = ?", (aggregate_id,)
            ).fetchone()
            work_id = str(row["work_item_id"] or "") if row else ""
        if work_id:
            configs = connection.execute(
                """
                SELECT c.id
                FROM a2a_push_configs AS c
                JOIN a2a_task_map AS m ON m.task_id = c.task_id
                WHERE m.work_item_id = ?
                """,
                (work_id,),
            ).fetchall()
            for config in configs:
                connection.execute(
                    """
                    INSERT INTO a2a_push_deliveries(
                        id, config_id, event_sequence, state, attempts,
                        next_attempt_at, created_at, updated_at
                    ) VALUES(?, ?, ?, 'queued', 0, ?, ?, ?)
                    ON CONFLICT(config_id, event_sequence) DO NOTHING
                    """,
                    (_id("pushd"), config["id"], sequence, created_at, created_at, created_at),
                )
        return sequence

    def _correlation_for_tx(self, connection: sqlite3.Connection, message_id: str | None) -> str:
        if not message_id:
            return ""
        row = connection.execute(
            "SELECT correlation_id FROM messages WHERE id = ?", (message_id,)
        ).fetchone()
        return row["correlation_id"] if row else ""

    @staticmethod
    def _reactivate_deliveries_tx(
        connection: sqlite3.Connection,
        principal_id: str,
        runtime_id: str,
    ) -> int:
        """Re-arm unread messages when a runtime becomes available again.

        A delivery may exhaust bounded adapter retries while the durable inbox
        remains unread. Re-registering or heartbeating a runtime must restore
        delivery without requiring a new supervisor message.
        """

        now = utc_now()
        rows = connection.execute(
            """
            SELECT d.message_id, d.recipient_id
            FROM message_deliveries AS d
            JOIN messages AS m ON m.id = d.message_id
            LEFT JOIN attempts AS a ON a.id = m.attempt_id
            WHERE d.recipient_id = ? AND d.state = ?
              AND d.reactivation_policy = ?
              AND NOT EXISTS (
                    SELECT 1
                    FROM managed_worker_thread_epochs AS retired_epoch
                    WHERE retired_epoch.retired_at IS NOT NULL
                      AND (
                        retired_epoch.runtime_session_id = d.runtime_session_id
                        OR retired_epoch.runtime_session_id = a.runtime_session_id
                      )
                  )
              AND (
                    m.attempt_id IS NULL
                    OR m.kind = 'cancel'
                    OR a.worker_id <> d.recipient_id
                    OR a.state NOT IN ('completed', 'failed', 'canceled')
                  )
            """,
            (
                principal_id,
                DeliveryState.DEAD.value,
                DeliveryReactivationPolicy.RETRYABLE.value,
            ),
        ).fetchall()
        if not rows:
            return 0
        message_ids = [str(row["message_id"]) for row in rows]
        message_placeholders = ",".join("?" for _ in message_ids)
        connection.execute(
            f"""
            UPDATE message_deliveries
            SET state = ?, generation = generation + 1, attempts = 0,
                next_attempt_at = ?, runtime_session_id = ?,
                lease_until = NULL, owner_token = '', last_error = '',
                reactivation_policy = ?,
                updated_at = ?
            WHERE recipient_id = ?
              AND message_id IN ({message_placeholders})
            """,
            (
                DeliveryState.QUEUED.value,
                now,
                runtime_id,
                DeliveryReactivationPolicy.TERMINAL.value,
                now,
                principal_id,
                *message_ids,
            ),
        )
        return len(rows)

    def _idempotent_get(
        self,
        actor_id: str,
        operation: str,
        key: str,
        request_digest: str,
        *,
        compatible_request_digests: Iterable[str] = (),
    ) -> dict[str, Any] | None:
        if not key:
            return None
        row = self.db.fetchone(
            "SELECT request_digest, result_json FROM idempotency_results "
            "WHERE actor_id = ? AND operation = ? AND idempotency_key = ?",
            (actor_id, operation, key),
        )
        accepted_digests = {request_digest, *compatible_request_digests}
        if row and row["request_digest"] not in accepted_digests:
            raise ConflictError(
                "idempotency key was reused with different command parameters",
                operation=operation,
            )
        return _load(row["result_json"], {}) if row else None

    @staticmethod
    def _idempotent_get_tx(
        connection: sqlite3.Connection,
        actor_id: str,
        operation: str,
        key: str,
        request_digest: str,
        *,
        compatible_request_digests: Iterable[str] = (),
    ) -> dict[str, Any] | None:
        """Recheck idempotency after acquiring the write transaction.

        The optimistic precheck avoids unnecessary write locks for common
        retries. This second check is the correctness boundary: SQLite's
        ``BEGIN IMMEDIATE`` serializes concurrent mutations, so two requests
        carrying the same key cannot both apply their side effects.
        """

        if not key:
            return None
        row = connection.execute(
            "SELECT request_digest, result_json FROM idempotency_results "
            "WHERE actor_id = ? AND operation = ? AND idempotency_key = ?",
            (actor_id, operation, key),
        ).fetchone()
        accepted_digests = {request_digest, *compatible_request_digests}
        if row and row["request_digest"] not in accepted_digests:
            raise ConflictError(
                "idempotency key was reused with different command parameters",
                operation=operation,
            )
        return _load(row["result_json"], {}) if row else None

    def _idempotent_put(
        self,
        connection: sqlite3.Connection,
        actor_id: str,
        operation: str,
        key: str,
        request_digest: str,
        result: dict[str, Any],
    ) -> None:
        if not key:
            return
        connection.execute(
            """
            INSERT INTO idempotency_results(
                actor_id, operation, idempotency_key, request_digest,
                result_json, created_at
            ) VALUES(?, ?, ?, ?, ?, ?)
            ON CONFLICT(actor_id, operation, idempotency_key) DO NOTHING
            """,
            (actor_id, operation, key, request_digest, _json(result), utc_now()),
        )
        row = connection.execute(
            "SELECT request_digest FROM idempotency_results "
            "WHERE actor_id = ? AND operation = ? AND idempotency_key = ?",
            (actor_id, operation, key),
        ).fetchone()
        if row is None or row["request_digest"] != request_digest:
            raise ConflictError(
                "idempotency key was concurrently reused with different command parameters",
                operation=operation,
            )

    def _require_worker_runtime_actor_tx(
        self,
        connection: sqlite3.Connection,
        actor: dict[str, Any],
        *,
        expected_runtime_id: str | None = None,
        require_ready: bool = True,
    ) -> sqlite3.Row:
        """Fence a Worker operation to its current managed MCP launch.

        A Worker principal bootstrap token is deliberately insufficient.  The
        authenticated actor must carry a short-lived runtime credential that
        is still active, belongs to the exact enrollment generation, and (for
        ordinary Worker tools) has completed discovery plus a fresh heartbeat.
        This check belongs inside the same transaction as every Worker state
        mutation so a concurrent revoke linearizes before or after the whole
        operation rather than between authentication and the write.
        """

        self._require_role(actor, PrincipalRole.WORKER)
        credential_id = str(actor.get("_runtime_credential_id") or "")
        enrollment_id = str(actor.get("_enrollment_id") or "")
        runtime_id = str(actor.get("_runtime_session_id") or "")
        try:
            actor_generation = int(str(actor.get("_enrollment_generation")))
        except (TypeError, ValueError):
            actor_generation = -1
        if not credential_id or not enrollment_id or not runtime_id:
            raise AuthorizationError("Worker operation requires a managed MCP runtime credential")
        if expected_runtime_id is not None and runtime_id != expected_runtime_id:
            raise AuthorizationError("Worker credential is bound to another runtime")

        row = cast(
            sqlite3.Row | None,
            connection.execute(
                """
                SELECT e.*, r.state AS runtime_state,
                       r.lease_expires_at AS runtime_lease_expires_at,
                       c.id AS credential_id, c.state AS credential_state,
                       c.generation AS credential_generation,
                       c.expires_at AS credential_expires_at
                FROM worker_enrollments AS e
                JOIN runtime_sessions AS r ON r.id = e.runtime_session_id
                JOIN runtime_credentials AS c
                  ON c.enrollment_id = e.id AND c.principal_id = e.principal_id
                JOIN principals AS p ON p.id = e.principal_id
                WHERE e.id = ? AND e.principal_id = ?
                  AND e.runtime_session_id = ? AND c.id = ? AND p.enabled = 1
                """,
                (enrollment_id, actor["id"], runtime_id, credential_id),
            ).fetchone(),
        )
        if (
            row is None
            or row["credential_state"] != "active"
            or _is_expired(str(row["credential_expires_at"]))
            or int(row["generation"]) != actor_generation
            or int(row["credential_generation"]) != actor_generation
            or row["state"] in {"revoked", "failed", "stale"}
            or not row["lease_expires_at"]
            or _is_expired(str(row["lease_expires_at"]))
            or not row["runtime_lease_expires_at"]
            or _is_expired(str(row["runtime_lease_expires_at"]))
        ):
            raise AuthorizationError("Worker MCP runtime credential is stale or revoked")
        if not require_ready:
            return row
        if (
            row["state"] != "ready"
            or row["runtime_state"]
            not in {
                RuntimeState.READY.value,
                RuntimeState.BUSY.value,
                RuntimeState.WAITING.value,
            }
            or str(row["required_tools_digest"]) != worker_mcp_tool_contract_digest()
            or str(row["discovered_tools_digest"]) != worker_mcp_tool_contract_digest()
            or not str(row["protocol_version"])
        ):
            raise ConflictError("Worker MCP runtime has not completed a fresh handshake")
        return row

    def _bind_ready_worker_runtime_tx(
        self,
        connection: sqlite3.Connection,
        *,
        worker_id: str,
        runtime_session_id: str | None,
    ) -> str:
        """Resolve one exact, fresh managed Worker runtime or fail closed."""

        params: list[Any] = [
            worker_id,
            worker_mcp_tool_contract_digest(),
            worker_mcp_tool_contract_digest(),
            utc_now(),
            utc_now(),
            utc_now(),
        ]
        runtime_clause = ""
        if runtime_session_id is not None:
            runtime_clause = "AND r.id = ?"
            params.append(runtime_session_id)
        rows = connection.execute(
            f"""
            SELECT r.id
            FROM runtime_sessions AS r
            JOIN worker_enrollments AS e ON e.runtime_session_id = r.id
            WHERE r.principal_id = ?
              AND e.managed = 1 AND e.state = 'ready'
              AND (
                  NOT EXISTS (
                      SELECT 1 FROM managed_worker_specs AS any_spec
                      WHERE any_spec.principal_id = r.principal_id
                  )
                  OR EXISTS (
                      SELECT 1
                      FROM managed_worker_specs AS spec
                      JOIN managed_worker_threads AS thread
                        ON thread.managed_spec_id = spec.id
                      JOIN managed_worker_thread_epochs AS epoch
                        ON epoch.thread_id = thread.id
                       AND epoch.generation = thread.generation
                       AND epoch.retired_at IS NULL
                      WHERE spec.principal_id = r.principal_id
                        AND spec.runtime_session_id = r.id
                        AND spec.enrollment_id = e.id
                        AND spec.state = 'enabled'
                        AND thread.state = 'active'
                        AND epoch.runtime_session_id = r.id
                        AND epoch.enrollment_id = e.id
                  )
              )
              AND e.required_tools_digest = ?
              AND e.discovered_tools_digest = ?
              AND e.protocol_version <> ''
              AND e.lease_expires_at >= ?
              AND r.lease_expires_at >= ?
              AND (
                  (
                      r.state IN ('ready', 'busy')
                      AND EXISTS (
                          SELECT 1 FROM runtime_credentials AS c
                          WHERE c.enrollment_id = e.id
                            AND c.principal_id = e.principal_id
                            AND c.state = 'active' AND c.expires_at >= ?
                            AND c.generation = e.generation
                      )
                  )
                  OR (
                      r.state = 'waiting'
                      AND NOT EXISTS (
                          SELECT 1 FROM runtime_credentials AS c
                          WHERE c.enrollment_id = e.id AND c.state = 'active'
                      )
                  )
              )
              {runtime_clause}
            ORDER BY r.updated_at DESC, r.id DESC
            LIMIT 2
            """,
            params,
        ).fetchall()
        if not rows and runtime_session_id is not None:
            runtime = connection.execute(
                "SELECT principal_id FROM runtime_sessions WHERE id = ?",
                (runtime_session_id,),
            ).fetchone()
            if runtime is None:
                raise NotFoundError("runtime", runtime_session_id)
            if runtime["principal_id"] != worker_id:
                raise ValidationError("runtime session does not belong to the assigned Worker")
            initial = connection.execute(
                """
                SELECT r.id
                FROM runtime_sessions AS r
                JOIN worker_enrollments AS e ON e.runtime_session_id = r.id
                WHERE r.id = ? AND r.principal_id = ?
                  AND r.state = 'starting'
                  AND e.managed = 1 AND e.state = 'awaiting_handshake'
                  AND (
                      NOT EXISTS (
                          SELECT 1 FROM managed_worker_specs AS any_spec
                          WHERE any_spec.principal_id = r.principal_id
                      )
                      OR EXISTS (
                          SELECT 1
                          FROM managed_worker_specs AS spec
                          JOIN managed_worker_threads AS thread
                            ON thread.managed_spec_id = spec.id
                          JOIN managed_worker_thread_epochs AS epoch
                            ON epoch.thread_id = thread.id
                           AND epoch.generation = thread.generation
                           AND epoch.retired_at IS NULL
                          WHERE spec.principal_id = r.principal_id
                            AND spec.runtime_session_id = r.id
                            AND spec.enrollment_id = e.id
                            AND spec.state = 'enabled'
                            AND thread.state = 'active'
                            AND epoch.runtime_session_id = r.id
                            AND epoch.enrollment_id = e.id
                      )
                  )
                  AND e.required_tools_digest = ?
                  AND e.discovered_tools_digest = ''
                  AND e.protocol_version = ''
                  AND e.heartbeat_sequence = 0
                  AND e.lease_expires_at >= ?
                  AND r.lease_expires_at >= ?
                  AND NOT EXISTS (
                      SELECT 1 FROM runtime_credentials AS c
                      WHERE c.enrollment_id = e.id AND c.state = 'active'
                  )
                """,
                (
                    runtime_session_id,
                    worker_id,
                    worker_mcp_tool_contract_digest(),
                    utc_now(),
                    utc_now(),
                ),
            ).fetchone()
            if initial is not None:
                return str(initial["id"])
        if not rows:
            raise ConflictError(
                "current managed Worker is not assignment-ready",
                reason_code="worker_runtime_not_connected",
                retryable=False,
            )
        if runtime_session_id is None and len(rows) != 1:
            raise ConflictError("Worker assignment requires one unambiguous managed MCP runtime")
        return str(rows[0]["id"])

    def _require_managed_worker_work_attachment_tx(
        self,
        connection: sqlite3.Connection,
        *,
        supervisor_id: str,
        worker_id: str,
        runtime_session_id: str,
        supervisor_attachment_id: str | None,
    ) -> None:
        """Fence a managed Worker selection to its CAO project, not one conversation."""

        spec = connection.execute(
            """
            SELECT spec.attachment_id, spec.attachment_generation,
                   spec.runtime_session_id AS spec_runtime_session_id,
                   spec.enrollment_id AS spec_enrollment_id,
                   spec.state AS spec_state,
                   thread.state AS thread_state,
                   thread.generation AS thread_generation,
                   epoch.runtime_session_id AS epoch_runtime_session_id,
                   epoch.enrollment_id AS epoch_enrollment_id,
                   epoch.retired_at AS epoch_retired_at,
                   attachment.generation AS current_generation,
                   attachment.state AS attachment_state,
                   attachment.principal_id AS attachment_principal_id,
                   attachment.project_digest AS attachment_project_digest,
                   supervisor_attachment.principal_id AS supervisor_principal_id,
                   supervisor_attachment.project_digest AS supervisor_project_digest,
                   runtime.principal_id AS runtime_principal_id,
                   enrollment.id AS runtime_enrollment_id,
                   enrollment.principal_id AS enrollment_principal_id,
                   enrollment.runtime_session_id AS enrollment_runtime_session_id,
                   enrollment.state AS enrollment_state
            FROM managed_worker_specs AS spec
            LEFT JOIN managed_worker_threads AS thread
              ON thread.managed_spec_id = spec.id
            LEFT JOIN managed_worker_thread_epochs AS epoch
              ON epoch.thread_id = thread.id
             AND epoch.generation = thread.generation
             AND epoch.retired_at IS NULL
            LEFT JOIN runtime_sessions AS runtime
              ON runtime.id = spec.runtime_session_id
             AND runtime.principal_id = spec.principal_id
            LEFT JOIN worker_enrollments AS enrollment
              ON enrollment.id = spec.enrollment_id
             AND enrollment.runtime_session_id = runtime.id
             AND enrollment.principal_id = runtime.principal_id
            JOIN cao_session_attachments AS attachment
              ON attachment.id = spec.attachment_id
            LEFT JOIN cao_session_attachments AS supervisor_attachment
              ON supervisor_attachment.id = ?
            WHERE spec.principal_id = ?
            """,
            (supervisor_attachment_id, worker_id),
        ).fetchone()
        if spec is None:
            return
        if (
            not supervisor_attachment_id
            or str(spec["attachment_principal_id"]) != supervisor_id
            or str(spec["supervisor_principal_id"] or "") != supervisor_id
            or str(spec["attachment_project_digest"] or "")
            != str(spec["supervisor_project_digest"] or "")
            or int(spec["attachment_generation"]) > int(spec["current_generation"])
            or str(spec["spec_runtime_session_id"]) != runtime_session_id
            or str(spec["spec_enrollment_id"]) != str(spec["runtime_enrollment_id"])
            or str(spec["spec_state"]) != "enabled"
            or str(spec["thread_state"]) != WorkerThreadState.ACTIVE.value
            or spec["epoch_retired_at"] is not None
            or str(spec["epoch_runtime_session_id"]) != runtime_session_id
            or str(spec["epoch_enrollment_id"]) != str(spec["spec_enrollment_id"])
            or str(spec["runtime_principal_id"]) != worker_id
            or str(spec["enrollment_principal_id"]) != worker_id
            or str(spec["enrollment_runtime_session_id"]) != runtime_session_id
            or str(spec["enrollment_state"]) not in {"awaiting_handshake", "ready"}
        ):
            raise AuthorizationError("managed Worker belongs to a different CAO project")

    def _require_role(self, actor: dict[str, Any], *roles: PrincipalRole) -> None:
        allowed = {role.value for role in roles}
        if actor["role"] not in allowed:
            raise AuthorizationError(
                "principal role is not permitted",
                actual=actor["role"],
                allowed=sorted(allowed),
            )
        if actor.get("_cao_runtime_credential_id"):
            # Authentication is not sufficient for a long-running resumed
            # turn: recheck all lease and generation fences at every CAO tool
            # action so an attachment cannot act in the expiry boundary.
            now = utc_now()
            row = self.db.fetchone(
                """
                SELECT 1
                FROM cao_runtime_credentials AS c
                JOIN cao_session_attachments AS a ON a.id = c.attachment_id
                JOIN runtime_sessions AS r ON r.id = a.runtime_session_id
                WHERE c.id = ? AND c.principal_id = ? AND c.attachment_id = ?
                  AND c.state = 'active' AND c.expires_at > ?
                  AND c.generation = ? AND a.generation = ?
                  AND a.state = 'active' AND a.lease_expires_at > ?
                  AND r.id = ? AND r.state = 'busy' AND r.lease_expires_at > ?
                """,
                (
                    actor["_cao_runtime_credential_id"],
                    actor["id"],
                    actor["_cao_attachment_id"],
                    now,
                    actor["_cao_attachment_generation"],
                    actor["_cao_attachment_generation"],
                    now,
                    actor["_runtime_session_id"],
                    now,
                ),
            )
            if row is None:
                raise AuthorizationError("CAO runtime attachment lease is stale or revoked")
        if actor.get("_cao_conversation_credential_id"):
            now = utc_now()
            row = self.db.fetchone(
                """
                SELECT 1
                FROM cao_conversation_credentials AS c
                JOIN cao_attachment_connections AS conn
                  ON conn.id = c.connection_id
                 AND conn.attachment_id = c.attachment_id
                 AND conn.principal_id = c.principal_id
                 AND conn.generation = c.generation
                JOIN cao_session_attachments AS a
                  ON a.id = conn.attachment_id
                 AND a.principal_id = conn.principal_id
                WHERE c.id = ? AND c.principal_id = ? AND c.attachment_id = ?
                  AND c.state = 'active' AND c.expires_at > ?
                  AND c.generation = ? AND a.generation = ?
                  AND conn.id = ? AND conn.connection_generation = ?
                  AND conn.state = 'active' AND conn.lease_expires_at > ?
                  AND a.state = 'active'
                """,
                (
                    actor["_cao_conversation_credential_id"],
                    actor["id"],
                    actor["_cao_attachment_id"],
                    now,
                    actor["_cao_attachment_generation"],
                    actor["_cao_attachment_generation"],
                    actor.get("_cao_connection_id"),
                    actor.get("_cao_connection_generation"),
                    now,
                ),
            )
            if row is None:
                raise AuthorizationError("CAO conversation attachment lease is stale or revoked")

    @staticmethod
    def _require_current_cao_attachment_actor_tx(
        connection: sqlite3.Connection,
        actor: Mapping[str, Any],
        *,
        allow_runtime_credential: bool = True,
    ) -> None:
        """Recheck one exact CAO attachment bearer inside its use-case transaction.

        Authentication and the ordinary per-action role check happen before a
        use-case opens its write transaction. A same-conversation reattach can
        revoke that bearer in between those two steps, so authority-sensitive
        reads and mutations must linearize on the attachment generation again
        after ``BEGIN IMMEDIATE`` acquires the database write fence.
        """

        attachment_id = str(actor.get("_cao_attachment_id") or "")
        runtime_session_id = str(actor.get("_runtime_session_id") or "")
        attachment_generation = actor.get("_cao_attachment_generation")
        conversation_credential_id = str(actor.get("_cao_conversation_credential_id") or "")
        connection_id = str(actor.get("_cao_connection_id") or "")
        connection_generation = actor.get("_cao_connection_generation")
        runtime_credential_id = str(actor.get("_cao_runtime_credential_id") or "")
        if (
            str(actor.get("role") or "") != PrincipalRole.CAO.value
            or not attachment_id
            or isinstance(attachment_generation, bool)
            or not isinstance(attachment_generation, int)
            or bool(conversation_credential_id) == bool(runtime_credential_id)
            or (runtime_credential_id and not runtime_session_id)
            or (runtime_credential_id and not allow_runtime_credential)
            or (
                bool(conversation_credential_id)
                and (
                    not connection_id
                    or isinstance(connection_generation, bool)
                    or not isinstance(connection_generation, int)
                )
            )
        ):
            raise AuthorizationError("CAO attachment authority is unavailable")

        now = utc_now()
        if conversation_credential_id:
            row = connection.execute(
                """
                SELECT 1
                FROM cao_conversation_credentials AS credential
                JOIN cao_attachment_connections AS conn
                  ON conn.id = credential.connection_id
                 AND conn.attachment_id = credential.attachment_id
                 AND conn.principal_id = credential.principal_id
                 AND conn.generation = credential.generation
                JOIN cao_session_attachments AS attachment
                  ON attachment.id = conn.attachment_id
                 AND attachment.principal_id = conn.principal_id
                JOIN principals AS principal
                  ON principal.id = credential.principal_id
                WHERE credential.id = ? AND credential.principal_id = ?
                  AND credential.attachment_id = ?
                  AND credential.state = 'active'
                  AND credential.expires_at > ?
                  AND credential.generation = ?
                  AND conn.id = ? AND conn.connection_generation = ?
                  AND conn.state = 'active' AND conn.lease_expires_at > ?
                  AND attachment.generation = ?
                  AND attachment.state = 'active'
                  AND principal.role = 'cao' AND principal.enabled = 1
                """,
                (
                    conversation_credential_id,
                    actor["id"],
                    attachment_id,
                    now,
                    attachment_generation,
                    connection_id,
                    connection_generation,
                    now,
                    attachment_generation,
                ),
            ).fetchone()
            if row is None:
                raise AuthorizationError("CAO conversation attachment lease is stale or revoked")
            return

        row = connection.execute(
            """
            SELECT 1
            FROM cao_runtime_credentials AS credential
            JOIN cao_session_attachments AS attachment
              ON attachment.id = credential.attachment_id
             AND attachment.principal_id = credential.principal_id
            JOIN runtime_sessions AS runtime
              ON runtime.id = attachment.runtime_session_id
             AND runtime.principal_id = credential.principal_id
            JOIN principals AS principal
              ON principal.id = credential.principal_id
            WHERE credential.id = ? AND credential.principal_id = ?
              AND credential.attachment_id = ?
              AND credential.state = 'active'
              AND credential.expires_at > ?
              AND credential.generation = ?
              AND attachment.generation = ?
              AND attachment.state = 'active'
              AND attachment.lease_expires_at > ?
              AND attachment.runtime_session_id = ?
              AND runtime.state = 'busy' AND runtime.lease_expires_at > ?
              AND principal.role = 'cao' AND principal.enabled = 1
            """,
            (
                runtime_credential_id,
                actor["id"],
                attachment_id,
                now,
                attachment_generation,
                attachment_generation,
                now,
                runtime_session_id,
                now,
            ),
        ).fetchone()
        if row is None:
            raise AuthorizationError("CAO runtime attachment lease is stale or revoked")
